window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2022-2"]={"track":"written","round":"2022-2","questions":[{"id":"written-2022-2-1","no":1,"unit":"소프트웨어 설계","q":"UML 다이어그램 중 순차 다이어그램에 대한 설명으로 틀린 것은?","choices":["객체 간의 동적 상호작용을 시간 개념을 중심으로 모델링 하는 것이다.","주로 시스템의 정적 측면을 모델링하기 위해 사용한다.","일반적으로 다이어그램의 수직 방향이 시간의 흐름을 나타낸다.","회귀 메시지(Self-Message), 제어블록(Statement block) 등으로 구성된다."],"ans":2,"rate":70,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"},{"title":"시퀀스 다이어그램","url":"https://itwiki.kr/w/시퀀스 다이어그램"},{"title":"순차다이어그램","url":"https://itwiki.kr/w/순차다이어그램"}],"exp":{"concept":"UML 다이어그램은 시스템의 뼈대를 그리는 정적(구조) 다이어그램과, 시간에 따라 무엇이 일어나는지 그리는 동적(행위) 다이어그램으로 나뉜다. 순차 다이어그램(Sequence Diagram)은 객체들이 어떤 순서로 메시지를 주고받는지 시간 흐름에 따라 그리는 동적 다이어그램이다. 만화의 칸처럼 위에서 아래로 시간이 흘러간다고 생각하면 된다.","choices":[{"verdict":"오답","why":"순차 다이어그램은 객체 사이의 동적 상호작용을 시간 순서 중심으로 표현하므로 옳은 설명이다."},{"verdict":"정답","why":"순차 다이어그램은 동적(행위) 측면을 모델링한다. 정적 측면을 모델링하는 것은 클래스 다이어그램, 객체 다이어그램, 컴포넌트 다이어그램 같은 구조 다이어그램이다."},{"verdict":"오답","why":"순차 다이어그램은 세로축이 시간의 흐름이고, 위에서 아래로 갈수록 나중에 일어난 일이므로 옳다."},{"verdict":"오답","why":"순차 다이어그램은 액터, 객체, 생명선, 실행(활성화), 메시지, 회귀 메시지(자기 자신에게 보내는 메시지), 제어 블록 등으로 구성되므로 옳다."}],"keywords":[{"term":"순차 다이어그램","desc":"객체 간 메시지 교환을 시간 순서대로 표현하는 동적 다이어그램"},{"term":"생명선(Lifeline)","desc":"객체가 존재하는 기간을 나타내는 세로 점선"},{"term":"정적 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치 다이어그램처럼 구조를 표현"},{"term":"동적 다이어그램","desc":"유스케이스, 순차, 상태, 활동 다이어그램처럼 행위를 표현"}],"memo":"'순차'는 순서, 순서는 시간이니 동적이다. 정적이라는 말이 나오면 틀린 보기다."}},{"id":"written-2022-2-2","no":2,"unit":"소프트웨어 설계","q":"메시지 지향 미들웨어(Message-Oriented Middleware, MOM)에 대한 설명으로 틀린 것은?","choices":["느리고 안정적인 응답보다는 즉각적인 응답이 필요한 온라인 업무에 적합하다.","독립적인 애플리케이션을 하나의 통합된 시스템으로 묶기 위한 역할을 한다.","송신측과 수신측의 연결 시 메시지 큐를 활용하는 방법이 있다.","상이한 애플리케이션 간 통신을 비동기 방식으로 지원한다."],"ans":1,"rate":57,"exp":{"concept":"메시지 지향 미들웨어(MOM, Message-Oriented Middleware)는 서로 다른 프로그램이 메시지를 주고받을 수 있게 중간에서 메시지를 맡아 두었다 전달해 주는 소프트웨어다. 우체통처럼 보내는 쪽이 넣어 두면 받는 쪽이 나중에 꺼내 가는 비동기 방식이라, 응답은 조금 느려도 안정적으로 전달된다.","choices":[{"verdict":"정답","why":"MOM은 비동기 방식이라 즉각적인 응답이 필요한 온라인 업무보다는, 다소 느리더라도 안정적인 전달이 필요한 업무에 적합하다. 그래서 이 설명이 틀렸다."},{"verdict":"오답","why":"MOM은 독립적으로 만들어진 애플리케이션들을 메시지로 연결해 하나의 통합된 시스템처럼 동작하게 하므로 옳다."},{"verdict":"오답","why":"송신 측이 메시지 큐에 넣고 수신 측이 큐에서 꺼내는 방식으로 연결할 수 있으므로 옳다."},{"verdict":"오답","why":"MOM은 서로 다른 애플리케이션 간의 통신을 비동기 방식으로 지원하는 것이 핵심 특징이므로 옳다."}],"keywords":[{"term":"MOM","desc":"메시지 기반의 비동기 통신을 지원하는 미들웨어"},{"term":"메시지 큐","desc":"보낸 메시지를 받는 쪽이 꺼낼 때까지 보관하는 대기열"},{"term":"비동기 통신","desc":"상대의 응답을 기다리지 않고 다음 작업을 진행하는 통신 방식"}],"memo":"MOM은 '느리지만 안정적'이다. '즉각적인 응답'이 붙으면 틀린 설명이다."}},{"id":"written-2022-2-3","no":3,"unit":"소프트웨어 설계","q":"익스트림 프로그래밍에 대한 설명으로 틀린 것은?","choices":["대표적인 구조적 방법론 중 하나이다.","소규모 개발 조직이 불확실하고 변경이 많은 요구를 접하였을 때 적절한 방법이다.","익스트림 프로그래밍을 구동시키는 원리는 상식적인 원리와 경험을 최대한 끌어 올리는 것이다.","구체적인 실천 방법을 정의하고 있으며, 개발 문서 보다는 소스코드에 중점을 둔다."],"ans":1,"rate":55,"exp":{"concept":"익스트림 프로그래밍(XP, eXtreme Programming)은 애자일 방법론의 대표 주자로, 고객의 요구가 자주 바뀌는 상황에서 짧은 주기로 자주 배포하며 대응하는 방법이다. 짝 프로그래밍, 테스트 주도 개발, 지속적 통합처럼 구체적인 실천 방법(Practice)을 정해 두고, 문서보다 동작하는 코드를 중시한다.","choices":[{"verdict":"정답","why":"XP는 구조적 방법론이 아니라 애자일 방법론에 속한다. 구조적 방법론은 DFD, 자료 사전 등을 사용하는 하향식 기능 중심 방법론이다."},{"verdict":"오답","why":"XP는 소규모 개발 조직이 불확실하고 변경이 잦은 요구를 다룰 때 적합한 방법이므로 옳다."},{"verdict":"오답","why":"XP는 상식적인 원리와 경험을 극한(Extreme)까지 끌어올려 실천한다는 생각에서 출발하므로 옳다."},{"verdict":"오답","why":"XP는 짝 프로그래밍, 테스트 우선 개발 등 구체적인 실천 방법을 정의하고, 개발 문서보다 소스 코드를 중시하므로 옳다."}],"keywords":[{"term":"XP(eXtreme Programming)","desc":"고객 참여와 짧은 반복 개발을 중시하는 애자일 방법론"},{"term":"XP 5가지 가치","desc":"용기, 단순성, 의사소통, 피드백, 존중"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 사람이 한 컴퓨터에서 함께 코딩하는 XP 실천 방법"},{"term":"구조적 방법론","desc":"DFD, 자료 사전, 소단위 명세서를 쓰는 기능 중심 방법론"}],"memo":"애자일 계열(XP, 스크럼, 린, 칸반)을 구조적·정보공학 방법론과 섞어 놓는 보기가 자주 나온다."}},{"id":"written-2022-2-4","no":4,"unit":"소프트웨어 설계","q":"유스케이스(Use Case)의 구성 요소 간의 관계에 포함되지 않는 것은?","choices":["연관","확장","구체화","일반화"],"ans":3,"rate":57,"exp":{"concept":"유스케이스 다이어그램은 사용자(액터)가 시스템으로 무엇을 할 수 있는지 그린 그림이다. 액터와 유스케이스, 유스케이스와 유스케이스 사이를 잇는 관계에는 연관(Association), 포함(Include), 확장(Extend), 일반화(Generalization)가 있다.","choices":[{"verdict":"오답","why":"연관 관계는 액터와 유스케이스가 서로 상호작용함을 실선으로 나타내는 유스케이스 관계다."},{"verdict":"오답","why":"확장 관계는 특정 조건에서만 추가로 실행되는 유스케이스를 연결하는 관계로, 유스케이스 관계에 포함된다."},{"verdict":"정답","why":"구체화는 유스케이스 다이어그램의 관계에 해당하지 않는다. 비슷한 이름의 실체화(Realization)는 클래스와 인터페이스 사이처럼 기능을 실제로 구현하는 관계로, 클래스 다이어그램에서 주로 쓴다."},{"verdict":"오답","why":"일반화 관계는 일반적인 액터나 유스케이스와 더 구체적인 것 사이의 상속 관계로, 유스케이스 관계에 포함된다."}],"keywords":[{"term":"포함(Include)","desc":"기본 유스케이스를 실행할 때 반드시 함께 실행되는 유스케이스와의 관계"},{"term":"확장(Extend)","desc":"특정 조건에서만 추가로 실행되는 유스케이스와의 관계"},{"term":"연관(Association)","desc":"액터와 유스케이스 사이의 상호작용"},{"term":"일반화(Generalization)","desc":"상위 개념과 하위 개념 사이의 상속 관계"}],"memo":"유스케이스 관계는 '연포확일'(연관, 포함, 확장, 일반화) 네 가지로 외운다."}},{"id":"written-2022-2-5","no":5,"unit":"소프트웨어 설계","q":"요구사항 분석에서 비기능적(Nonfunctional) 요구에 대한 설명으로 옳은 것은?","choices":["시스템의 처리량(Throughput), 반응 시간 등의 성능 요구나 품질 요구는 비기능적 요구에 해당하지 않는다.","'차량 대여 시스템이 제공하는 모든 화면이 3초 이내에 사용자에게 보여야 한다'는 비기능적 요구이다.","시스템 구축과 관련된 안전, 보안에 대한 요구사항들은 비기능적 요구에 해당하지 않는다.","'금융 시스템은 조회, 인출, 입금, 송금의 기능이 있어야 한다'는 비기능적 요구이다."],"ans":2,"rate":63,"wiki":[{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"}],"exp":{"concept":"요구사항은 기능적 요구사항과 비기능적 요구사항으로 나뉜다. 기능적 요구사항은 시스템이 '무엇을 하는가'(조회, 입금 같은 기능)이고, 비기능적 요구사항은 '얼마나 잘하는가'(속도, 보안, 안전, 신뢰성 같은 품질과 제약)이다.","choices":[{"verdict":"오답","why":"처리량, 반응 시간 같은 성능 요구와 품질 요구는 대표적인 비기능적 요구이므로 '해당하지 않는다'는 설명은 틀렸다."},{"verdict":"정답","why":"'모든 화면이 3초 이내에 보여야 한다'는 응답 시간, 즉 성능에 관한 요구이므로 비기능적 요구가 맞다."},{"verdict":"오답","why":"안전과 보안에 관한 요구사항은 비기능적 요구에 해당하므로 '해당하지 않는다'는 설명은 틀렸다."},{"verdict":"오답","why":"조회, 인출, 입금, 송금 같은 기능이 있어야 한다는 것은 시스템이 할 일을 정한 기능적 요구이므로 비기능적 요구라는 설명은 틀렸다."}],"keywords":[{"term":"기능적 요구사항","desc":"시스템이 수행해야 할 기능(무엇을 하는가)"},{"term":"비기능적 요구사항","desc":"성능, 보안, 안전, 신뢰성 등 품질과 제약 조건(얼마나 잘하는가)"},{"term":"응답 시간","desc":"요청 후 결과가 나올 때까지 걸리는 시간으로 대표적인 성능 지표"}],"memo":"숫자(3초, 초당 처리 건수)나 품질 형용사(안전, 빠름)가 나오면 비기능, 동사형 기능 목록이 나오면 기능이다."}},{"id":"written-2022-2-6","no":6,"unit":"소프트웨어 설계","q":"정보공학 방법론에서 데이터베이스 설계의 표현으로 사용하는 모델링 언어는?","choices":["Package Diagram","State Transition Diagram","Deployment Diagram","Entity-Relationship Diagram"],"ans":4,"rate":75,"wiki":[{"title":"정보공학 방법론","url":"https://itwiki.kr/w/정보공학 방법론"}],"exp":{"concept":"정보공학 방법론은 기업 전체의 정보 시스템을 데이터 중심으로 계획·분석·설계하는 방법론이다. 데이터가 중심이므로 데이터베이스 설계를 표현할 때 개체(Entity)와 그 사이의 관계(Relationship)를 그리는 E-R 다이어그램을 사용한다.","choices":[{"verdict":"오답","why":"패키지 다이어그램은 UML에서 관련된 요소들을 패키지로 묶어 그 의존 관계를 나타내는 구조 다이어그램이다."},{"verdict":"오답","why":"상태 전이 다이어그램은 객체나 시스템이 사건에 따라 상태가 어떻게 바뀌는지 나타내는 그림으로, 데이터베이스 설계 표현과는 거리가 멀다."},{"verdict":"오답","why":"배치 다이어그램은 UML에서 소프트웨어가 어떤 물리적 노드(서버, 장치)에 배치되는지 나타내는 구조 다이어그램이다."},{"verdict":"정답","why":"E-R 다이어그램(Entity-Relationship Diagram)은 개체, 속성, 관계로 데이터 구조를 표현하며, 정보공학 방법론에서 데이터베이스 설계를 표현하는 모델링 언어다."}],"keywords":[{"term":"정보공학 방법론","desc":"데이터 중심으로 정보 시스템을 계획·분석·설계·구축하는 방법론"},{"term":"E-R 다이어그램","desc":"개체(사각형), 관계(마름모), 속성(타원)으로 데이터 구조를 나타내는 그림"},{"term":"구조적 방법론","desc":"DFD 중심의 기능(처리) 중심 방법론"}],"memo":"구조적 방법론은 DFD, 정보공학 방법론은 ERD, 객체지향 방법론은 UML로 짝지어 외운다."}},{"id":"written-2022-2-7","no":7,"unit":"소프트웨어 설계","q":"미들웨어(Middleware)에 대한 설명으로 틀린 것은?","choices":["여러 운영체제에서 응용 프로그램들 사이에 위치한 소프트웨어이다.","미들웨어의 서비스 이용을 위해 사용자가 정보 교환 방법 \n등의 내부 동작을 쉽게 확인할 수 있어야 한다.","소프트웨어 컴포넌트를 연결하기 위한 준비된 인프라 구조를 제공한다.","여러 컴포넌트를 1대 1, 1대 다, 다대 다 등 여러 가지 형태로 연결이 가능하다."],"ans":2,"rate":72,"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"exp":{"concept":"미들웨어(Middleware)는 운영체제와 응용 프로그램 사이, 또는 서로 다른 시스템 사이에 위치해 이들이 쉽게 통신하고 데이터를 주고받도록 돕는 소프트웨어다. 사용자는 미들웨어 내부에서 어떻게 정보가 교환되는지 몰라도 서비스를 쓸 수 있어야 하는데, 이를 투명성이라고 한다.","choices":[{"verdict":"오답","why":"미들웨어는 여러 운영체제 환경에서 응용 프로그램들 사이에 위치해 중간 다리 역할을 하는 소프트웨어이므로 옳다."},{"verdict":"정답","why":"미들웨어는 정보 교환 방법 같은 내부 동작을 사용자가 몰라도 쓸 수 있도록 감추는 것(투명성)이 목적이다. 내부 동작을 사용자가 확인할 수 있어야 한다는 설명은 틀렸다."},{"verdict":"오답","why":"미들웨어는 소프트웨어 컴포넌트들을 연결하기 위해 미리 준비된 인프라 구조를 제공하므로 옳다."},{"verdict":"오답","why":"미들웨어는 컴포넌트들을 1대1, 1대다, 다대다 등 여러 형태로 연결할 수 있으므로 옳다."}],"keywords":[{"term":"미들웨어","desc":"응용 프로그램과 운영체제 또는 시스템 사이에서 통신을 중개하는 소프트웨어"},{"term":"투명성(Transparency)","desc":"내부 동작이나 위치를 사용자가 의식하지 않고 쓸 수 있는 성질"},{"term":"미들웨어 종류","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS 등"}],"memo":"미들웨어는 '감춰 주는' 소프트웨어다. '사용자가 내부 동작을 확인'이 나오면 틀린 보기다."}},{"id":"written-2022-2-8","no":8,"unit":"소프트웨어 설계","q":"UI의 설계 지침으로 틀린 것은?","choices":["이해하기 편하고 쉽게 사용할 수 있는 환경을 제공해야 한다.","주요 기능을 메인 화면에 노출하여 조작이 쉽도록 하여야 한다.","치명적인 오류에 대한 부정적인 사항은 사용자가 인지할 수 없도록 한다.","사용자의 직무, 연령, 성별 등 다양한 계층을 수용하여야 한다."],"ans":3,"rate":94,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"},{"title":"UI/UX","url":"https://itwiki.kr/w/UI/UX"}],"exp":{"concept":"UI 설계 지침은 사용자가 화면을 편하고 안전하게 쓰도록 지켜야 할 원칙이다. 사용자 중심, 일관성, 단순성, 결과 예측 가능, 가시성, 표준화, 접근성, 명확성, 오류 발생 해결 등이 있다. 특히 오류가 생기면 사용자가 상황을 정확히 알 수 있도록 알려 주어야 한다.","choices":[{"verdict":"오답","why":"이해하기 쉽고 사용하기 편한 환경을 제공하는 것은 사용자 중심이라는 UI 설계 지침에 맞는다."},{"verdict":"오답","why":"주요 기능을 메인 화면에 노출해 쉽게 조작하게 하는 것은 가시성 지침에 맞는다."},{"verdict":"정답","why":"오류가 발생하면 사용자가 그 상황을 정확히 인지할 수 있도록 알려 주어야 한다(오류 발생 해결 지침). 치명적인 오류를 사용자가 모르게 숨기라는 설명은 틀렸다."},{"verdict":"오답","why":"직무, 연령, 성별 등 다양한 사용자 계층을 수용하는 것은 접근성 지침에 맞는다."}],"keywords":[{"term":"가시성","desc":"주요 기능을 메인 화면에 노출해 쉽게 조작하게 하는 원칙"},{"term":"접근성","desc":"다양한 계층의 사용자가 모두 이용할 수 있게 하는 원칙"},{"term":"오류 발생 해결","desc":"오류가 나면 사용자가 상황을 정확히 인지하게 하는 원칙"},{"term":"일관성","desc":"버튼, 조작 방법 등을 일관되게 유지하는 원칙"}],"memo":"오류는 숨기는 것이 아니라 알려 주는 것이다. '인지할 수 없도록'이 나오면 틀린 보기다."}},{"id":"written-2022-2-9","no":9,"unit":"소프트웨어 설계","q":"객체지향 개념에서 다형성(Polymorphism)과 관련한 설명으로 틀린 것은?","choices":["다형성은 현재 코드를 변경하지 않고 새로운 클래스를 쉽게 추가할 수 있게 한다.","다형성이란 여러 가지 형태를 가지고 있다는 의미로, 여러 형태를 받아들일 수 있는 특징을 말한다.","메소드 오버라이딩(Overriding)은 상위 클래스에서 정의한 일반 메소드의 구현을 하위 클래스에서 무시하고 재정의할 수 있다.","메소드 오버로딩(Overloading)의 경우 매개 변수 타입은 동일하지만 메소드명을 다르게 함으로써 구현, 구분할 수 있다."],"ans":4,"rate":59,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"},{"title":"다형성","url":"https://itwiki.kr/w/다형성"}],"exp":{"concept":"다형성(Polymorphism)은 같은 이름의 메시지에 대해 객체마다 다르게 반응하는 성질이다. 대표적으로 오버로딩(Overloading)은 이름은 같고 매개변수의 개수나 타입이 다른 메소드를 여러 개 정의하는 것이고, 오버라이딩(Overriding)은 상위 클래스의 메소드를 하위 클래스에서 같은 이름·같은 매개변수로 다시 정의하는 것이다.","choices":[{"verdict":"오답","why":"다형성 덕분에 상위 타입으로 작성한 기존 코드를 고치지 않고도 새로운 하위 클래스를 추가해 쓸 수 있으므로 옳다."},{"verdict":"오답","why":"다형성은 '여러 가지 형태'라는 뜻으로, 하나의 이름이 여러 형태를 받아들일 수 있는 특징을 말하므로 옳다."},{"verdict":"오답","why":"오버라이딩은 상위 클래스에서 정의한 메소드를 하위 클래스에서 무시하고 새로 정의하는 것이므로 옳다."},{"verdict":"정답","why":"오버로딩은 메소드 이름은 같고 매개변수의 개수나 타입을 다르게 해서 구분하는 것이다. '매개변수 타입은 같고 메소드명을 다르게'라는 설명은 반대로 되어 있어 틀렸다."}],"keywords":[{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체마다 다르게 반응하는 성질"},{"term":"오버로딩(Overloading)","desc":"같은 이름, 다른 매개변수(개수·타입)로 메소드를 여러 개 정의"},{"term":"오버라이딩(Overriding)","desc":"상위 클래스 메소드를 하위 클래스에서 같은 형태로 재정의"}],"memo":"오버로딩은 '이름 같고 매개변수 다름', 오버라이딩은 '이름도 매개변수도 같고 내용만 다름'이다."}},{"id":"written-2022-2-10","no":10,"unit":"소프트웨어 설계","q":"소프트웨어 개발 영역을 결정하는 요소 중 다음 사항과 관계있는 것은?\n<img src=\"data/img/eip_written_20220424_010.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["기능(Function)","성능(Performance)","제약 조건(Constraint)","인터페이스(Interface)"],"ans":4,"rate":70,"exp":{"concept":"소프트웨어 개발 영역(범위)을 결정하는 요소에는 기능, 성능, 제약 조건, 인터페이스, 신뢰도가 있다. 그중 인터페이스는 개발할 소프트웨어가 바깥의 무엇과 연결되는지를 다룬다. 지문의 '소프트웨어가 제어하는 장치와 실행하는 하드웨어', '기존 소프트웨어와 새 소프트웨어를 연결하는 소프트웨어', '소프트웨어를 실행하는 절차'는 모두 소프트웨어와 외부의 연결 관계이므로 인터페이스에 해당한다.","choices":[{"verdict":"오답","why":"기능(Function)은 소프트웨어가 수행해야 할 일과 처리 내용을 정하는 요소로, 외부와의 연결 관계를 다루는 지문 내용과 다르다."},{"verdict":"오답","why":"성능(Performance)은 처리 속도, 응답 시간, 처리량처럼 소프트웨어가 얼마나 빠르고 효율적으로 동작해야 하는지를 정하는 요소다."},{"verdict":"오답","why":"제약 조건(Constraint)은 비용, 기간, 하드웨어 사양, 법규처럼 개발 시 지켜야 할 제한 사항을 정하는 요소다."},{"verdict":"정답","why":"인터페이스(Interface)는 소프트웨어와 연결되는 하드웨어, 다른 소프트웨어, 실행 절차 등 외부와의 상호작용을 정하는 요소로, 지문의 세 항목이 모두 여기에 해당한다."}],"keywords":[{"term":"소프트웨어 개발 영역 결정 요소","desc":"기능, 성능, 제약 조건, 인터페이스, 신뢰도"},{"term":"인터페이스","desc":"소프트웨어와 하드웨어·다른 소프트웨어·절차 사이의 연결"},{"term":"제약 조건","desc":"비용, 기간, 하드웨어, 규정 등 개발 시 지켜야 할 제한"}],"memo":"지문에 '연결', '실행하는 하드웨어', '절차'처럼 바깥과 맞닿는 말이 반복되면 인터페이스다."}},{"id":"written-2022-2-11","no":11,"unit":"소프트웨어 설계","q":"객체에 대한 설명으로 틀린 것은?","choices":["객체는 상태, 동작, 고유 식별자를 가진 모든 것이라 할 수 있다.","객체는 공통 속성을 공유하는 클래스들의 집합이다.","객체는 필요한 자료 구조와 이에 수행되는 함수들을 가진 하나의 독립된 존재이다.","객체의 상태는 속성값에 의해 정의된다."],"ans":2,"rate":68,"exp":{"concept":"객체(Object)는 데이터(속성)와 그 데이터를 처리하는 함수(메소드)를 하나로 묶은 독립된 존재다. 클래스는 공통된 속성과 메소드를 가진 객체들을 찍어 내는 틀이고, 객체는 그 틀로 만든 실제 물건이다. 붕어빵 틀이 클래스, 붕어빵이 객체다.","choices":[{"verdict":"오답","why":"객체는 상태(속성 값), 동작(메소드), 다른 객체와 구별되는 고유 식별자를 가진 모든 것이라 할 수 있으므로 옳다."},{"verdict":"정답","why":"공통 속성을 공유하는 객체들의 집합(틀)은 클래스다. '객체는 클래스들의 집합'이라는 설명은 관계가 거꾸로 되어 있어 틀렸다."},{"verdict":"오답","why":"객체는 필요한 자료 구조와 그 자료에 수행되는 함수를 함께 가진 하나의 독립된 존재이므로 옳다."},{"verdict":"오답","why":"객체의 상태는 그 객체가 가진 속성들의 현재 값으로 정의되므로 옳다."}],"keywords":[{"term":"객체(Object)","desc":"속성과 메소드를 함께 가진 독립된 존재"},{"term":"클래스(Class)","desc":"공통 속성과 메소드를 가진 객체들의 틀(집합)"},{"term":"인스턴스(Instance)","desc":"클래스로부터 생성된 실제 객체"}],"memo":"클래스가 객체들의 집합이지, 객체가 클래스들의 집합이 아니다. 포함 관계가 뒤집힌 보기를 조심한다."}},{"id":"written-2022-2-12","no":12,"unit":"소프트웨어 설계","q":"속성과 관련된 연산(Operation)을 클래스 안에 묶어서 하나로 취급하는 것을 의미하는 객체지향 개념은?","choices":["Inheritance","Class","Encapsulation","Association"],"ans":3,"rate":58,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"캡슐화(Encapsulation)는 데이터(속성)와 그 데이터를 다루는 연산(메소드)을 하나의 클래스로 묶는 것이다. 약 성분을 캡슐 하나에 담아 겉에서는 내용물이 보이지 않게 하는 것과 같아서, 정보 은닉과 함께 설명되는 경우가 많다.","choices":[{"verdict":"오답","why":"Inheritance(상속)는 상위 클래스의 속성과 메소드를 하위 클래스가 물려받아 사용하는 개념이다."},{"verdict":"오답","why":"Class(클래스)는 공통된 속성과 연산을 가진 객체들을 만들기 위한 틀로, 묶는 '행위'를 뜻하는 개념은 아니다."},{"verdict":"정답","why":"Encapsulation(캡슐화)은 속성과 관련된 연산을 클래스 안에 묶어 하나로 취급하는 개념이다."},{"verdict":"오답","why":"Association(연관)은 클래스나 객체들이 서로 관계를 맺고 참조하는 관계를 뜻한다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"속성과 연산을 하나로 묶는 것"},{"term":"정보 은닉(Information Hiding)","desc":"캡슐화된 내부 정보를 외부에서 직접 접근하지 못하게 숨기는 것"},{"term":"상속(Inheritance)","desc":"상위 클래스의 속성과 연산을 하위 클래스가 물려받는 것"}],"memo":"'묶어서 하나로'는 캡슐화, '숨긴다'는 정보 은닉, '물려받는다'는 상속이다."}},{"id":"written-2022-2-13","no":13,"unit":"소프트웨어 설계","q":"애자일(Agile) 프로세스 모델에 대한 설명으로 틀린 것은?","choices":["변화에 대한 대응보다는 자세한 계획을 중심으로 소프트웨어를 개발한다.","프로세스와 도구 중심이 아닌 개개인과의 상호소통을 통해 의견을 수렴한다.","협상과 계약보다는 고객과의 협력을 중시한다.","문서 중심이 아닌, 실행 가능한 소프트웨어를 중시한다."],"ans":1,"rate":86,"wiki":[{"title":"애자일","url":"https://itwiki.kr/w/애자일"},{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"애자일(Agile)은 '민첩한'이라는 뜻으로, 고객과 자주 소통하며 짧은 주기로 동작하는 소프트웨어를 만들어 변화에 빠르게 대응하는 개발 방식이다. 애자일 선언문은 프로세스·도구보다 개인과 상호작용, 문서보다 동작하는 소프트웨어, 계약 협상보다 고객과의 협력, 계획을 따르기보다 변화에 대응하기를 더 가치 있게 여긴다.","choices":[{"verdict":"정답","why":"애자일 선언문은 '계획을 따르기보다 변화에 대응하기'를 중시한다. 변화 대응보다 자세한 계획을 중심으로 한다는 설명은 반대이므로 틀렸다."},{"verdict":"오답","why":"프로세스와 도구보다 개인과 상호작용(소통)을 중시한다는 애자일 선언문의 가치와 일치한다."},{"verdict":"오답","why":"계약 협상보다 고객과의 협력을 중시한다는 애자일 선언문의 가치와 일치한다."},{"verdict":"오답","why":"포괄적인 문서보다 작동하는 소프트웨어를 중시한다는 애자일 선언문의 가치와 일치한다."}],"keywords":[{"term":"애자일 선언문 4가지 가치","desc":"개인과 상호작용, 작동하는 소프트웨어, 고객과의 협력, 변화에 대응"},{"term":"애자일 방법론 종류","desc":"XP, 스크럼, 린, 칸반, FDD, 크리스탈 등"},{"term":"폭포수 모형","desc":"계획과 문서 중심으로 단계를 순서대로 진행하는 전통적 모형"}],"memo":"애자일 4가치는 모두 '~보다 사람·동작·협력·변화'다. 계획, 문서, 계약, 도구가 앞에 오면 틀린 보기다."}},{"id":"written-2022-2-14","no":14,"unit":"소프트웨어 설계","q":"명백한 역할을 가지고 독립적으로 존재할 수 있는 시스템의 부분으로 넓은 의미에서는 재사용되는 모든 단위라고 볼 수 있으며, 인터페이스를 통해서만 접근할 수 있는 것은?","choices":["Model","Sheet","Component","Cell"],"ans":3,"rate":75,"wiki":[{"title":"컴포넌트","url":"https://itwiki.kr/w/컴포넌트"}],"exp":{"concept":"컴포넌트(Component)는 독립적으로 동작할 수 있고 명확한 역할을 가진 소프트웨어 부품이다. 레고 블록처럼 정해진 연결부(인터페이스)를 통해서만 다른 부품과 결합되며, 이렇게 재사용할 수 있는 단위로 시스템을 조립하는 개발 방식을 컴포넌트 기반 개발(CBD)이라고 한다.","choices":[{"verdict":"오답","why":"Model(모델)은 시스템이나 현실을 단순화해 표현한 것으로, 인터페이스로만 접근하는 독립된 부품을 뜻하지 않는다."},{"verdict":"오답","why":"Sheet(시트)는 출제 범위에서 소프트웨어 구성 단위를 가리키는 표준 용어가 아니다."},{"verdict":"정답","why":"Component(컴포넌트)는 명백한 역할을 가지고 독립적으로 존재할 수 있는 시스템의 부분으로, 재사용 단위이며 인터페이스를 통해서만 접근할 수 있다."},{"verdict":"오답","why":"Cell(셀)은 출제 범위에서 소프트웨어 구성 단위를 가리키는 표준 용어가 아니다."}],"keywords":[{"term":"컴포넌트(Component)","desc":"인터페이스를 통해서만 접근하는 독립적인 재사용 소프트웨어 부품"},{"term":"CBD(Component Based Development)","desc":"컴포넌트를 조립해 소프트웨어를 만드는 개발 방법론"},{"term":"인터페이스(Interface)","desc":"컴포넌트가 외부에 기능을 제공하는 접점"}],"memo":"'독립적', '재사용', '인터페이스를 통해서만' 세 단서가 함께 나오면 컴포넌트다."}},{"id":"written-2022-2-15","no":15,"unit":"소프트웨어 설계","q":"GoF(Gang of Four) 디자인 패턴을 생성, 구조, 행동 패턴의 세 그룹으로 분류할 때, 구조 패턴이 아닌 것은?","choices":["Adapter 패턴","Bridge 패턴","Builder 패턴","Proxy 패턴"],"ans":3,"rate":60,"exp":{"concept":"GoF 디자인 패턴 23개는 목적에 따라 생성, 구조, 행위 패턴으로 나뉜다. 생성 패턴은 객체를 만드는 방법, 구조 패턴은 클래스와 객체를 조합해 더 큰 구조를 만드는 방법, 행위 패턴은 객체 사이의 책임 분배와 상호작용 방법을 다룬다.","choices":[{"verdict":"오답","why":"Adapter 패턴은 호환되지 않는 인터페이스를 맞춰 주는 구조 패턴이다."},{"verdict":"오답","why":"Bridge 패턴은 기능 계층과 구현 계층을 분리해 독립적으로 확장하게 하는 구조 패턴이다."},{"verdict":"정답","why":"Builder 패턴은 복잡한 객체를 단계별로 조립해 생성하는 생성 패턴이므로 구조 패턴이 아니다."},{"verdict":"오답","why":"Proxy 패턴은 대리 객체를 두어 실제 객체에 대한 접근을 제어하는 구조 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴","desc":"Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴","desc":"Chain of Responsibility, Command, Interpreter, Iterator, Mediator, Memento, Observer, State, Strategy, Template Method, Visitor"}],"memo":"Builder는 '짓는(만드는)' 사람이니 생성 패턴이다. 생성 패턴 5개(추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤)를 먼저 외워 두면 나머지 구분이 쉽다."}},{"id":"written-2022-2-16","no":16,"unit":"소프트웨어 설계","q":"UI와 관련된 기본 개념 중 하나로, 시스템의 상태와 사용자의 지시에 대한 효과를 보여주어 사용자가 명령에 대한 진행 상황과 표시된 내용을 해석할 수 있도록 도와주는 것은?","choices":["Feedback","Posture","Module","Hash"],"ans":1,"rate":77,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"}],"exp":{"concept":"피드백(Feedback)은 사용자가 무언가를 했을 때 시스템이 그 결과와 현재 상태를 보여 주는 것이다. 버튼을 누르면 색이 바뀌거나, 파일을 복사할 때 진행률 막대가 나오는 것처럼 사용자가 '내 명령이 처리되고 있구나'를 알 수 있게 해 준다.","choices":[{"verdict":"정답","why":"Feedback(피드백)은 시스템의 상태와 사용자 지시에 대한 효과를 보여 주어 사용자가 진행 상황과 결과를 해석할 수 있게 돕는 UI 기본 개념이다."},{"verdict":"오답","why":"Posture는 '자세'라는 뜻으로, 시스템 상태와 명령 효과를 보여 주는 UI 기본 개념을 가리키는 용어가 아니다."},{"verdict":"오답","why":"Module(모듈)은 소프트웨어를 기능 단위로 나눈 구성 단위로, UI의 피드백 개념과 관계없다."},{"verdict":"오답","why":"Hash(해시)는 임의 길이의 데이터를 고정 길이 값으로 바꾸는 함수나 그 값으로, UI 개념이 아니다."}],"keywords":[{"term":"피드백(Feedback)","desc":"사용자 행동에 대한 시스템의 반응과 상태를 보여 주는 것"},{"term":"UI 기본 원칙","desc":"직관성, 유효성, 학습성, 유연성"},{"term":"진행 표시줄","desc":"작업 진행 상황을 보여 주는 대표적인 피드백 요소"}],"memo":"'상태와 효과를 보여 준다', '진행 상황'이 나오면 피드백이다."}},{"id":"written-2022-2-17","no":17,"unit":"소프트웨어 설계","q":"UI의 종류로 멀티 터치(Multi-touch), 동작 인식(Gesture Recognition) 등 사용자의 자연스러운 움직임을 인식하여 서로 주고받는 정보를 제공하는 사용자 인터페이스를 의미하는 것은?","choices":["GUI(Graphical User Interface)","OUI(Organic User Interface)","NUI(Natural User Interface)","CLI(Command Line Interface)"],"ans":3,"rate":72,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"}],"exp":{"concept":"사용자 인터페이스(UI)는 사람이 기기와 소통하는 방식에 따라 나뉜다. 글자 명령을 치면 CLI, 아이콘과 마우스를 쓰면 GUI, 손가락으로 화면을 벌리거나 몸짓처럼 사람의 자연스러운 움직임을 그대로 인식하면 NUI다. 스마트폰에서 두 손가락으로 사진을 확대하는 것이 대표적인 NUI다.","choices":[{"verdict":"오답","why":"GUI(Graphical User Interface)는 아이콘, 창, 메뉴 같은 그래픽 요소를 마우스나 펜으로 선택해 조작하는 인터페이스다."},{"verdict":"오답","why":"OUI(Organic User Interface)는 모든 사물과 사용자 사이의 상호작용을 위한 인터페이스로, 사물 자체가 입출력 장치가 되는 형태를 말한다."},{"verdict":"정답","why":"NUI(Natural User Interface)는 멀티 터치, 동작 인식처럼 사용자의 자연스러운 움직임을 인식해 정보를 주고받는 인터페이스다."},{"verdict":"오답","why":"CLI(Command Line Interface)는 키보드로 명령어를 문자로 입력해 조작하는 인터페이스다."}],"keywords":[{"term":"CLI","desc":"명령어를 글자로 입력하는 인터페이스"},{"term":"GUI","desc":"아이콘·메뉴를 마우스로 조작하는 그래픽 인터페이스"},{"term":"NUI","desc":"터치·제스처 등 자연스러운 행동으로 조작하는 인터페이스"},{"term":"OUI","desc":"사물 자체가 입출력 장치가 되는 유기적 인터페이스"}],"memo":"Natural은 '자연스러운 몸짓', Organic은 '사물 자체'로 구분한다."}},{"id":"written-2022-2-18","no":18,"unit":"소프트웨어 설계","q":"소프트웨어 모델링과 관련한 설명으로 틀린 것은?","choices":["모델링 작업의 결과물은 다른 모델링 작업에 영향을 줄 수 없다.","구조적 방법론에서는 DFD(Data Flow Diagram), DD(Data Dictionary) 등을 사용하여 요구 사항의 결과를 표현한다.","객체지향 방법론에서는 UML 표기법을 사용한다.","소프트웨어 모델을 사용할 경우 개발될 소프트웨어에 대한 이해도 및 이해 당사자 간의 의사소통 향상에 도움이 된다."],"ans":1,"rate":78,"exp":{"concept":"소프트웨어 모델링은 만들 소프트웨어를 그림이나 표기법으로 미리 표현해 보는 작업이다. 건물 설계도처럼 이해 당사자들이 같은 그림을 보며 소통할 수 있게 해 주고, 한 모델링의 결과물(예: 요구사항 모델)은 다음 모델링(예: 설계 모델)의 입력이 되어 서로 영향을 준다.","choices":[{"verdict":"정답","why":"모델링 작업의 결과물은 다른 모델링 작업의 입력이 되는 등 서로 영향을 준다. 예를 들어 요구 분석 모델이 설계 모델의 기초가 된다. 영향을 줄 수 없다는 설명은 틀렸다."},{"verdict":"오답","why":"구조적 방법론은 DFD(자료 흐름도), DD(자료 사전) 등으로 요구 분석 결과를 표현하므로 옳다."},{"verdict":"오답","why":"객체지향 방법론에서는 표준 모델링 언어인 UML 표기법을 사용하므로 옳다."},{"verdict":"오답","why":"소프트웨어 모델을 사용하면 개발할 소프트웨어를 이해하기 쉬워지고 이해 당사자 간 의사소통이 향상되므로 옳다."}],"keywords":[{"term":"DFD(Data Flow Diagram)","desc":"자료의 흐름과 처리 과정을 그림으로 표현하는 구조적 분석 도구"},{"term":"DD(Data Dictionary)","desc":"자료 흐름도에 나오는 데이터를 정의하고 설명한 사전"},{"term":"UML(Unified Modeling Language)","desc":"객체지향 모델링의 표준 언어"}],"memo":"'~할 수 없다', '반드시 ~이다'처럼 단정적인 표현은 틀린 보기일 가능성이 높다."}},{"id":"written-2022-2-19","no":19,"unit":"소프트웨어 설계","q":"유스케이스 다이어그램(Use Case Diagram)에 관련된 내용으로 틀린 것은?","choices":["시스템과 상호작용하는 외부시스템은 액터로 파악해서는 안된다.","유스케이스는 사용자 측면에서의 요구사항으로, 사용자가 원하는 목표를 달성하기 위해 수행할 내용을 기술한다.","시스템 액터는 다른 프로젝트에서 이미 개발되어 사용되고 있으며, 본 시스템과 데이터를 주고받는 등 서로 연동되는 시스템을 말한다.","액터가 인식할 수 없는 시스템 내부의 기능을 하나의 유스케이스로 파악해서는 안된다."],"ans":1,"rate":61,"exp":{"concept":"유스케이스 다이어그램에서 액터(Actor)는 시스템 바깥에서 시스템과 상호작용하는 존재다. 사람인 주 액터뿐 아니라, 우리 시스템과 데이터를 주고받는 외부 시스템도 시스템 액터(부 액터)로 표현한다. 유스케이스는 액터 입장에서 보이는 기능만 나타낸다.","choices":[{"verdict":"정답","why":"시스템과 상호작용하는 외부 시스템도 시스템 액터로 파악해야 한다. 외부 시스템을 액터로 파악해서는 안 된다는 설명은 틀렸다."},{"verdict":"오답","why":"유스케이스는 사용자 측면의 요구사항으로, 사용자가 원하는 목표를 이루기 위해 시스템이 수행할 내용을 기술하므로 옳다."},{"verdict":"오답","why":"시스템 액터는 다른 프로젝트에서 이미 개발되어 쓰이고 있으면서 본 시스템과 데이터를 주고받는 등 연동되는 시스템을 말하므로 옳다."},{"verdict":"오답","why":"유스케이스는 액터가 인식할 수 있는 기능 단위이므로, 액터가 알 수 없는 내부 기능을 하나의 유스케이스로 잡아서는 안 된다는 설명은 옳다."}],"keywords":[{"term":"액터(Actor)","desc":"시스템 외부에서 시스템과 상호작용하는 사람이나 시스템"},{"term":"주 액터","desc":"시스템을 사용해 이득을 얻는 사용자"},{"term":"시스템 액터(부 액터)","desc":"본 시스템과 연동되는 외부 시스템"},{"term":"유스케이스","desc":"액터가 시스템을 통해 얻고자 하는 기능 단위"}],"memo":"액터는 사람만이 아니다. 연동되는 외부 시스템도 액터다."}},{"id":"written-2022-2-20","no":20,"unit":"소프트웨어 설계","q":"소프트웨어 아키텍처 모델 중 MVC(Model-View-Controller)와 관련한 설명으로 틀린 것은?","choices":["MVC 모델은 사용자 인터페이스를 담당하는 계층의 응집도를 높일 수 있고, 여러 개의 다른 UI를 만들어 그 사\n이에 결합도를 낮출 수 있다.","모델(Model)은 뷰(View)와 제어(Controller) 사이에서 전달자 역할을 하며, 뷰마다 모델 서브시스템이 각각 하나씩 연결된다.","뷰(View)는 모델(Model)에 있는 데이터를 사용자 인터페이스에 보이는 역할을 담당한다.","제어(Controller)는 모델(Model)에 명령을 보냄으로써 모델의 상태를 변경할 수 있다."],"ans":2,"rate":67,"wiki":[{"title":"MVC_패턴","url":"https://itwiki.kr/w/MVC_패턴"}],"exp":{"concept":"MVC(Model-View-Controller)는 프로그램을 데이터와 처리 로직(Model), 화면 표시(View), 사용자 입력 처리(Controller) 세 부분으로 나누는 아키텍처 패턴이다. 사용자의 입력은 Controller가 받아 Model을 변경하고, View는 Model의 데이터를 화면에 보여 준다. 화면과 데이터가 분리되어 있어 같은 데이터를 여러 화면으로 보여 주기 쉽다.","choices":[{"verdict":"오답","why":"MVC는 UI를 담당하는 부분을 분리해 응집도를 높이고, 여러 개의 UI(View)를 만들어도 서로 결합도가 낮게 유지되므로 옳다."},{"verdict":"정답","why":"모델은 데이터와 핵심 처리 로직을 담당하는 부분이다. 뷰와 사용자 입력 사이에서 전달자 역할을 하는 것은 컨트롤러이며, 모델은 뷰마다 따로 두지 않고 하나의 모델을 여러 뷰가 함께 보여 줄 수 있다."},{"verdict":"오답","why":"뷰는 모델에 있는 데이터를 사용자 인터페이스에 보여 주는 역할을 하므로 옳다."},{"verdict":"오답","why":"컨트롤러는 사용자 입력을 받아 모델에 명령을 보내 모델의 상태를 변경할 수 있으므로 옳다."}],"keywords":[{"term":"Model","desc":"데이터와 핵심 처리 로직 담당"},{"term":"View","desc":"모델의 데이터를 사용자에게 보여 주는 화면 담당"},{"term":"Controller","desc":"사용자 입력을 받아 모델과 뷰를 제어하는 전달자"},{"term":"MVC 패턴","desc":"데이터, 화면, 제어를 분리하는 아키텍처 패턴"}],"memo":"'전달자, 중재자'는 컨트롤러의 역할이다. 모델에 붙어 나오면 틀린 보기다."}},{"id":"written-2022-2-21","no":21,"unit":"소프트웨어 개발","q":"통합 테스트(Integration Test)와 관련한 설명으로 틀린 것은?","choices":["시스템을 구성하는 모듈의 인터페이스와 결합을 테스트하는 것이다.","하향식 통합 테스트의 경우 넓이 우선(Breadth First) 방식으로 테스트를 할 모듈을 선택할 수 있다.","상향식 통합 테스트의 경우 시스템 구조도의 최상위에 있는 모듈을 먼저 구현하고 테스트한다.","모듈 간의 인터페이스와 시스템의 동작이 정상적으로 잘되고 있는지를 빨리 파악하고자 할 때 상향식 보다는 하향식 통합 테스트를 사용하는 것이 좋다."],"ans":3,"rate":66,"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"통합 테스트는 단위 테스트를 마친 모듈들을 합치면서 모듈 간 인터페이스와 결합이 제대로 동작하는지 확인하는 테스트다. 위에서부터 합치면 하향식(가짜 하위 모듈인 스텁 필요), 아래에서부터 합치면 상향식(가짜 상위 모듈인 드라이버 필요)이다.","choices":[{"verdict":"오답","why":"통합 테스트는 시스템을 구성하는 모듈 사이의 인터페이스와 결합을 테스트하는 것이므로 옳다."},{"verdict":"오답","why":"하향식 통합 테스트는 주요 제어 모듈부터 아래로 내려가며 깊이 우선(Depth First) 또는 넓이 우선(Breadth First) 방식으로 통합할 모듈을 선택할 수 있으므로 옳다."},{"verdict":"정답","why":"상향식 통합 테스트는 시스템 구조도의 최하위 모듈부터 구현하고 테스트하며 위로 올라간다. 최상위 모듈부터 테스트하는 것은 하향식이다."},{"verdict":"오답","why":"하향식 통합은 상위의 주요 제어 흐름과 인터페이스를 먼저 테스트하므로, 모듈 간 인터페이스와 시스템 동작의 이상을 빨리 파악하려면 하향식이 유리하다."}],"keywords":[{"term":"하향식 통합 테스트","desc":"상위 모듈부터 아래로 통합하며 스텁(Stub)을 사용"},{"term":"상향식 통합 테스트","desc":"하위 모듈부터 위로 통합하며 드라이버(Driver)를 사용"},{"term":"클러스터(Cluster)","desc":"상향식 통합에서 하위 모듈들을 묶은 단위"},{"term":"빅뱅 통합","desc":"모든 모듈을 한 번에 결합해 테스트하는 방식"}],"memo":"상향식은 '아래(하위)'부터 시작한다. 이름과 시작 위치가 반대라고 헷갈리지 않도록 '올라가니까 상향'으로 외운다."}},{"id":"written-2022-2-22","no":22,"unit":"소프트웨어 개발","q":"다음과 같이 레코드가 구성되어 있을 때, 이진 검색 방법으로 14를 찾을 경우 비교되는 횟수는?\n<img src=\"data/img/eip_written_20220424_022.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["2","3","4","5"],"ans":2,"rate":64,"wiki":[{"title":"이진 검색","url":"https://itwiki.kr/w/이진 검색"}],"exp":{"concept":"이진 검색(Binary Search)은 정렬된 자료에서 가운데 값과 찾는 값을 비교해, 찾는 값이 더 크면 오른쪽 절반, 작으면 왼쪽 절반만 남기며 범위를 반씩 줄여 가는 방법이다. 가운데 위치는 (시작 + 끝) / 2에서 소수점을 버려 구한다.","choices":[{"verdict":"오답","why":"1~15에서 14를 찾으면 8, 12, 14와 차례로 비교하므로 비교 횟수는 3회다. 2회는 아직 14에 도달하지 못한 시점이다."},{"verdict":"정답","why":"1회: (1+15)/2=8번째 값 8과 비교, 14가 더 크므로 범위 9~15. 2회: (9+15)/2=12번째 값 12와 비교, 14가 더 크므로 범위 13~15. 3회: (13+15)/2=14번째 값 14와 비교해 찾는다. 총 3회다."},{"verdict":"오답","why":"14는 세 번째 비교에서 찾아지므로 4회는 틀렸다."},{"verdict":"오답","why":"14는 세 번째 비교에서 찾아지므로 5회는 틀렸다."}],"keywords":[{"term":"이진 검색","desc":"정렬된 자료를 반씩 나누며 찾는 검색 방법"},{"term":"중간 위치","desc":"(low + high) / 2, 소수점 이하 버림"},{"term":"이진 검색 전제 조건","desc":"자료가 반드시 정렬되어 있어야 함"}],"memo":"중간값이 찾는 값보다 작으면 오른쪽 절반, 크면 왼쪽 절반으로 범위를 갱신하며 비교 횟수를 하나씩 센다. 범위의 양 끝을 매번 적어 두면 실수가 줄어든다."}},{"id":"written-2022-2-23","no":23,"unit":"소프트웨어 개발","q":"소프트웨어 공학에서 워크스루(Walkthrough)에 대한 설명으로 틀린 것은?","choices":["사용사례를 확장하여 명세하거나 설계 다이어그램, 원시코드, 테스트 케이스 등에 적용할 수 있다.","복잡한 알고리즘 또는 반복, 실시간 동작, 병행 처리와 같은 기능이나 동작을 이해하려고 할 때 유용하다.","인스펙션(Inspection)과 동일한 의미를 가진다.","단순한 테스트 케이스를 이용하여 프로덕트를 수작업으로 수행해 보는 것이다."],"ans":3,"rate":61,"wiki":[{"title":"확인과 검증","url":"https://itwiki.kr/w/확인과 검증"},{"title":"정적 테스트","url":"https://itwiki.kr/w/정적 테스트"}],"exp":{"concept":"워크스루(Walkthrough)와 인스펙션(Inspection)은 모두 프로그램을 실행하지 않고 사람이 검토하는 정적 테스트다. 워크스루는 작성자가 회의를 열어 산출물을 설명하고 간단한 테스트 케이스로 손으로 따라가 보는 비공식적 검토이고, 인스펙션은 훈련받은 검토 전문가가 정해진 절차에 따라 수행하는 공식적인 검토다.","choices":[{"verdict":"오답","why":"워크스루는 사용 사례를 확장한 명세, 설계 다이어그램, 원시 코드, 테스트 케이스 등 다양한 산출물에 적용할 수 있으므로 옳다."},{"verdict":"오답","why":"워크스루는 복잡한 알고리즘, 반복, 실시간 동작, 병행 처리처럼 이해하기 어려운 기능이나 동작을 함께 따라가며 이해할 때 유용하므로 옳다."},{"verdict":"정답","why":"워크스루는 작성자 주도의 비공식 검토이고, 인스펙션은 검토 전문가가 계획, 사전 교육, 준비, 회의, 수정, 후속 조치의 공식 절차에 따라 수행하는 검토이므로 둘은 같은 의미가 아니다."},{"verdict":"오답","why":"워크스루는 단순한 테스트 케이스를 이용해 산출물(프로덕트)을 수작업으로 따라 수행해 보는 방식이므로 옳다."}],"keywords":[{"term":"워크스루(Walkthrough)","desc":"작성자 주도로 산출물을 설명하고 함께 검토하는 비공식 검토"},{"term":"인스펙션(Inspection)","desc":"검토 전문가가 정해진 절차로 수행하는 공식 검토"},{"term":"정적 테스트","desc":"프로그램을 실행하지 않고 산출물을 검토하는 테스트"}],"memo":"둘 다 정적 테스트지만 워크스루는 비공식, 인스펙션은 공식이다. '동일하다'는 틀린 보기다."}},{"id":"written-2022-2-24","no":24,"unit":"소프트웨어 개발","q":"소프트웨어의 개발과정에서 소프트웨어의 변경사항을 관리하기 위해 개발된 일련의 활동을 뜻하는 것은?","choices":["복호화","형상관리","저작권","크랙"],"ans":2,"rate":93,"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"}],"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 소프트웨어를 개발하면서 생기는 코드, 문서 등의 변경 사항을 체계적으로 기록하고 관리하는 활동이다. 누가 언제 무엇을 바꿨는지 추적하고, 필요하면 이전 버전으로 되돌릴 수 있게 해 준다.","choices":[{"verdict":"오답","why":"복호화는 암호문을 원래의 평문으로 되돌리는 과정으로, 변경 사항 관리와 관계없다."},{"verdict":"정답","why":"형상 관리는 소프트웨어 개발 과정에서 변경 사항을 관리하기 위해 개발된 일련의 활동으로, 형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록 등을 수행한다."},{"verdict":"오답","why":"저작권은 창작물에 대해 창작자가 갖는 법적 권리로, 변경 관리 활동이 아니다."},{"verdict":"오답","why":"크랙은 소프트웨어의 복제 방지나 인증 장치를 불법으로 무력화하는 행위나 그 도구로, 변경 관리 활동이 아니다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"소프트웨어 변경 사항을 체계적으로 관리하는 활동"},{"term":"형상 관리 절차","desc":"형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록"},{"term":"형상 관리 도구","desc":"CVS, SVN(Subversion), Git 등"}],"memo":"'변경 사항을 관리'라는 말이 나오면 형상 관리다."}},{"id":"written-2022-2-25","no":25,"unit":"소프트웨어 개발","q":"테스트 케이스와 관련한 설명으로 틀린 것은?","choices":["테스트의 목표 및 테스트 방법을 결정하기 전에 테스트 케이스를 작성해야 한다.","프로그램에 결함이 있더라도 입력에 대해 정상적인 결과를 낼 수 있기 때문에 결함을 검사할 수 있는 테스트 케이스를 찾는 것이 중요하다.","개발된 서비스가 정의된 요구 사항을 준수하는지 확인하기 위한 입력 값과 실행 조건, 예상 결과의 집합으로 볼 수 있다.","테스트 케이스 실행이 통과되었는지 실패하였는지 판단하기 위한 기준을 테스트 오라클(Test Oracle)이라고 한다."],"ans":1,"rate":57,"exp":{"concept":"테스트 케이스는 요구사항대로 동작하는지 확인하기 위해 만든 입력 값, 실행 조건, 예상 결과의 묶음이다. 테스트 목표와 방법을 먼저 정한 뒤 그에 맞춰 테스트 케이스를 작성한다. 결과가 맞았는지 판단하는 기준은 테스트 오라클이라고 한다.","choices":[{"verdict":"정답","why":"테스트 케이스는 테스트 목표와 테스트 방법을 결정한 다음에 그에 맞춰 작성한다. 목표와 방법을 정하기 전에 작성해야 한다는 설명은 순서가 틀렸다."},{"verdict":"오답","why":"결함이 있어도 특정 입력에는 정상 결과가 나올 수 있으므로, 결함을 드러낼 수 있는 테스트 케이스를 찾는 것이 중요하다는 설명은 옳다."},{"verdict":"오답","why":"테스트 케이스는 요구사항 준수 여부를 확인하기 위한 입력 값, 실행 조건, 예상 결과의 집합이므로 옳다."},{"verdict":"오답","why":"테스트 오라클은 테스트 결과가 참인지 거짓인지(통과·실패) 판단하기 위해 사전에 정의한 기준이므로 옳다."}],"keywords":[{"term":"테스트 케이스","desc":"입력 값, 실행 조건, 예상 결과로 구성된 테스트 항목 명세"},{"term":"테스트 오라클(Test Oracle)","desc":"테스트 결과의 통과·실패를 판단하는 기준"},{"term":"오라클 종류","desc":"참(True), 샘플링(Sampling), 추정(Heuristic), 일관성 검사(Consistent) 오라클"}],"memo":"순서는 '목표·방법 결정 → 테스트 케이스 작성 → 실행 → 오라클로 판정'이다."}},{"id":"written-2022-2-26","no":26,"unit":"소프트웨어 개발","q":"객체지향 개념을 활용한 소프트웨어 구현과 관련한 설명 중 틀린 것은?","choices":["객체(Object)란 필요한 자료 구조와 수행되는 함수들을 가진 하나의 독립된 존재이다.","JAVA에서 정보은닉(Information Hiding)을 표기할 때 private의 의미는 '공개'이다.","상속(Inheritance)은 개별 클래스를 상속 관계로 묶음으로써 클래스 간의 체계화된 전체 구조를 파악하기 쉽다는 장점이 있다.","같은 클래스에 속하는 개개의 객체이자 하나의 클래스에서 생성된 객체를 인스턴스(Instance)라고 한다."],"ans":2,"rate":91,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"객체지향 구현의 기본 개념에는 객체, 클래스, 인스턴스, 상속, 정보 은닉 등이 있다. 자바는 접근 제어자로 정보 은닉을 표현하는데, public은 어디서나 접근 가능한 '공개', private은 같은 클래스 안에서만 접근 가능한 '비공개'다.","choices":[{"verdict":"오답","why":"객체는 필요한 자료 구조와 그에 수행되는 함수들을 가진 하나의 독립된 존재이므로 옳다."},{"verdict":"정답","why":"자바에서 private은 같은 클래스 내부에서만 접근할 수 있는 '비공개'를 뜻한다. '공개'를 뜻하는 접근 제어자는 public이다."},{"verdict":"오답","why":"상속으로 클래스들을 상위·하위 관계로 묶으면 클래스 간의 전체 구조를 체계적으로 파악하기 쉬우므로 옳다."},{"verdict":"오답","why":"같은 클래스에 속하는 개개의 객체, 즉 하나의 클래스에서 생성된 객체를 인스턴스라고 하므로 옳다."}],"keywords":[{"term":"public","desc":"모든 곳에서 접근 가능"},{"term":"protected","desc":"같은 패키지와 상속받은 하위 클래스에서 접근 가능"},{"term":"default","desc":"접근 제어자를 생략한 경우로, 같은 패키지 안에서만 접근 가능"},{"term":"private","desc":"같은 클래스 안에서만 접근 가능"}],"memo":"private은 '사적인', 즉 비공개다. 접근 범위는 public > protected > default > private 순으로 좁아진다."}},{"id":"written-2022-2-27","no":27,"unit":"소프트웨어 개발","q":"DRM(Digital Rights Management)과 관련한 설명으로 틀린 것은?","choices":["디지털 콘텐츠와 디바이스의 사용을 제한하기 위해 하드웨어 제조업자, 저작권자, 출판업자 등이 사용할 수 있는 접근 제어 기술을 의미한다.","디지털 미디어의 생명 주기 동안 발생하는 사용 권한 관리, 과금, 유통 단계를 관리하는 기술로도 볼 수 있다.","클리어링 하우스(Clearing House)는 사용자에게 콘텐츠 라이센스를 발급하고 권한을 부여해주는 시스템을 말한다.","원본을 안전하게 유통하기 위한 전자적 보안은 고려하지 않기 때문에 불법 유통과 복제의 방지는 불가능하다."],"ans":4,"rate":84,"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"exp":{"concept":"DRM(Digital Rights Management, 디지털 저작권 관리)은 음원, 영상, 전자책 같은 디지털 콘텐츠를 허가된 사용자만 정해진 범위에서 쓰도록 암호화와 라이선스로 보호하는 기술이다. 불법 복제와 유통을 막는 것이 핵심 목적이다.","choices":[{"verdict":"오답","why":"DRM은 하드웨어 제조업자, 저작권자, 출판업자 등이 디지털 콘텐츠와 기기의 사용을 제한하기 위해 쓰는 접근 제어 기술이므로 옳다."},{"verdict":"오답","why":"DRM은 디지털 미디어의 생명 주기 동안 사용 권한 관리, 과금, 유통 단계를 관리하는 기술로도 볼 수 있으므로 옳다."},{"verdict":"오답","why":"클리어링 하우스(Clearing House)는 저작권에 대한 사용 권한, 라이선스 발급, 사용량에 따른 결제 관리 등을 수행하는 곳이므로 옳다."},{"verdict":"정답","why":"DRM은 암호화 등 전자적 보안 기술로 원본을 안전하게 유통하고 불법 유통과 복제를 방지하는 것이 목적이다. 전자적 보안을 고려하지 않아 복제 방지가 불가능하다는 설명은 틀렸다."}],"keywords":[{"term":"DRM","desc":"디지털 콘텐츠의 사용 권한을 관리하고 불법 복제를 막는 기술"},{"term":"클리어링 하우스(Clearing House)","desc":"라이선스 발급, 권한 부여, 결제를 관리하는 곳"},{"term":"콘텐츠 제공자 / 분배자 / 소비자","desc":"DRM 구성 요소 중 콘텐츠를 만드는 쪽, 유통하는 쪽, 구매해 사용하는 쪽"},{"term":"DRM 패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 가능한 형태로 묶어 암호화하는 프로그램"}],"memo":"DRM의 존재 이유가 불법 복제 방지다. '복제 방지는 불가능'이라는 말은 목적과 정면으로 어긋난다."}},{"id":"written-2022-2-28","no":28,"unit":"소프트웨어 개발","q":"위험 모니터링의 의미로 옳은 것은?","choices":["위험을 이해하는 것","첫 번째 조치로 위험을 피할 수 있도록 하는 것","위험 발생 후 즉시 조치하는 것","위험 요소 징후들에 대하여 계속적으로 인지하는 것"],"ans":4,"rate":77,"wiki":[{"title":"위험 관리","url":"https://itwiki.kr/w/위험 관리"}],"exp":{"concept":"위험 관리는 위험 식별, 위험 분석·평가, 위험 대응 계획, 위험 모니터링 순으로 이루어진다. 위험 모니터링은 위험 요소의 징후가 나타나는지 계속 지켜보며 상황 변화를 추적하는 활동이다. 일기 예보를 계속 확인하며 비가 올 조짐을 살피는 것과 같다.","choices":[{"verdict":"오답","why":"위험을 이해하는 것은 위험의 내용과 영향을 파악하는 위험 분석 활동에 가까우며, 모니터링의 의미가 아니다."},{"verdict":"오답","why":"첫 번째 조치로 위험을 피하도록 하는 것은 위험 대응 전략 중 회피(Avoidance)에 해당한다."},{"verdict":"오답","why":"위험이 발생한 뒤 즉시 조치하는 것은 사후 대응에 해당하며, 징후를 계속 지켜보는 모니터링과 다르다."},{"verdict":"정답","why":"위험 모니터링은 위험 요소의 징후들을 계속해서 인지하고 그 변화를 추적하는 활동이다."}],"keywords":[{"term":"위험 관리 절차","desc":"위험 식별 → 위험 분석·평가 → 위험 대응 계획 → 위험 모니터링"},{"term":"위험 대응 전략","desc":"회피, 전가, 완화, 수용"},{"term":"위험 모니터링","desc":"위험 징후를 지속적으로 인지하고 추적하는 활동"}],"memo":"모니터링은 '계속 지켜보기'다. '계속적으로 인지'라는 표현이 핵심 단서다."}},{"id":"written-2022-2-29","no":29,"unit":"소프트웨어 개발","q":"동시에 소스를 수정하는 것을 방지하며 다른 방향으로 진행된 개발 결과를 합치거나 변경 내용을 추적할 수 있는 소프트웨어 버전 관리 도구는?","choices":["RCS(Revision Control System)","RTS(Reliable Transfer Service)","RPC(Remote Procedure Call)","RVS(Relative Version System)"],"ans":1,"rate":61,"wiki":[{"title":"RCS","url":"https://itwiki.kr/w/RCS"}],"exp":{"concept":"버전 관리 도구는 소스 코드의 변경 이력을 저장하고 관리하는 도구다. RCS(Revision Control System)는 파일에 잠금(Lock)을 걸어 여러 사람이 동시에 같은 파일을 수정하지 못하게 하면서, 변경 내용을 추적하고 갈라진 개발 결과를 합칠 수 있게 해 준다.","choices":[{"verdict":"정답","why":"RCS(Revision Control System)는 소스 파일의 동시 수정을 잠금으로 방지하고 변경 이력을 관리하는 버전 관리 도구다."},{"verdict":"오답","why":"RTS(Reliable Transfer Service)는 OSI 응용 계층에서 신뢰성 있는 데이터 전송을 지원하는 서비스로, 버전 관리 도구가 아니다."},{"verdict":"오답","why":"RPC(Remote Procedure Call)는 다른 컴퓨터에 있는 프로시저를 네트워크를 통해 호출하는 기술이다."},{"verdict":"오답","why":"RVS(Relative Version System)는 출제 범위의 표준 버전 관리 도구가 아니다."}],"keywords":[{"term":"RCS","desc":"잠금으로 동시 수정을 막는 버전 관리 도구"},{"term":"CVS","desc":"서버-클라이언트 구조의 중앙 집중형 버전 관리 도구"},{"term":"SVN(Subversion)","desc":"CVS를 개선한 중앙 집중형 버전 관리 도구"},{"term":"Git","desc":"각 개발자가 저장소 전체를 복사해 쓰는 분산형 버전 관리 도구"}],"memo":"RCS의 R은 Revision(개정), 즉 버전이다. 'Revision Control'이면 버전 관리 도구다."}},{"id":"written-2022-2-30","no":30,"unit":"소프트웨어 개발","q":"화이트박스 테스트와 관련한 설명으로 틀린 것은?","choices":["화이트박스 테스트의 이해를 위해 논리흐름도(Logic-Flow Diagram)를 이용할 수 있다.","테스트 데이터를 이용해 실제 프로그램을 실행함으로써 오류를 찾는 동적 테스트(Dynamic Test)에 해당한다.","프로그램의 구조를 고려하지 않기 때문에 테스트 케이스는 프로그램 또는 모듈의 요구나 명세를 기초로 결정한다.","테스트 데이터를 선택하기 위하여 검증기준(Test Coverage)을 정한다."],"ans":3,"rate":72,"wiki":[{"title":"화이트박스 테스트","url":"https://itwiki.kr/w/화이트박스 테스트"}],"exp":{"concept":"화이트박스 테스트는 프로그램 내부 구조(소스 코드의 논리 흐름)를 보면서 모든 경로나 조건이 실행되는지 확인하는 테스트다. 반대로 블랙박스 테스트는 내부를 보지 않고 요구사항과 명세를 기준으로 입력과 출력만 확인한다. 상자 안이 투명하게 보이면 화이트박스, 안 보이면 블랙박스다.","choices":[{"verdict":"오답","why":"화이트박스 테스트는 내부 논리를 보는 테스트이므로 논리 흐름도(Logic-Flow Diagram)를 이용해 이해할 수 있다는 설명은 옳다."},{"verdict":"오답","why":"화이트박스 테스트는 테스트 데이터로 실제 프로그램을 실행해 오류를 찾으므로 동적 테스트에 해당한다."},{"verdict":"정답","why":"프로그램 구조를 고려하지 않고 요구사항과 명세를 기초로 테스트 케이스를 정하는 것은 블랙박스 테스트의 특징이다. 화이트박스 테스트는 프로그램 내부 구조를 기초로 테스트 케이스를 정한다."},{"verdict":"오답","why":"화이트박스 테스트는 구문, 결정(분기), 조건 커버리지 같은 검증 기준(Test Coverage)을 정해 테스트 데이터를 선택하므로 옳다."}],"keywords":[{"term":"화이트박스 테스트","desc":"내부 구조와 논리 경로를 기준으로 하는 테스트"},{"term":"블랙박스 테스트","desc":"요구사항과 명세를 기준으로 입력·출력을 확인하는 테스트"},{"term":"화이트박스 기법","desc":"기초 경로 검사, 조건 검사, 루프 검사, 데이터 흐름 검사"},{"term":"테스트 커버리지","desc":"구문, 결정(분기), 조건, 조건/결정, 변경 조건/결정, 다중 조건 커버리지"}],"memo":"'구조를 고려하지 않음', '명세 기반'은 블랙박스다. 화이트박스 보기에 섞여 나오면 틀린 보기다."}},{"id":"written-2022-2-31","no":31,"unit":"소프트웨어 개발","q":"알고리즘과 관련한 설명으로 틀린 것은?","choices":["주어진 작업을 수행하는 컴퓨터 명령어를 순서대로 나열한 것으로 볼 수 있다.","검색(Searching)은 정렬이 되지 않은 데이터 혹은 정렬이 된 데이터 중에서 키값에 해당되는 데이터를 찾는 알고리즘이다.","정렬(Sorting)은 흩어져있는 데이터를 키값을 이용하여 순서대로 열거하는 알고리즘이다.","선형 검색은 검색을 수행하기 전에 반드시 데이터의 집합이 정렬되어 있어야 한다."],"ans":4,"rate":70,"wiki":[{"title":"알고리즘","url":"https://itwiki.kr/w/알고리즘"},{"title":"정렬 알고리즘","url":"https://itwiki.kr/w/정렬 알고리즘"}],"exp":{"concept":"알고리즘은 문제를 해결하기 위한 명령어를 순서대로 나열한 절차다. 검색 알고리즘 중 선형 검색(순차 검색)은 처음부터 하나씩 차례로 비교하므로 정렬되지 않은 자료에도 쓸 수 있고, 이진 검색은 반씩 나누어 찾으므로 반드시 정렬된 자료가 필요하다.","choices":[{"verdict":"오답","why":"알고리즘은 주어진 작업을 수행하는 컴퓨터 명령어를 순서대로 나열한 것으로 볼 수 있으므로 옳다."},{"verdict":"오답","why":"검색은 정렬된 데이터든 정렬되지 않은 데이터든 그 안에서 키 값에 해당하는 데이터를 찾는 알고리즘이므로 옳다."},{"verdict":"오답","why":"정렬은 흩어져 있는 데이터를 키 값을 기준으로 오름차순이나 내림차순으로 늘어놓는 알고리즘이므로 옳다."},{"verdict":"정답","why":"선형 검색은 처음부터 끝까지 하나씩 차례로 비교하므로 데이터가 정렬되어 있지 않아도 된다. 반드시 정렬되어 있어야 하는 것은 이진 검색이다."}],"keywords":[{"term":"선형 검색(순차 검색)","desc":"처음부터 하나씩 차례로 비교하며 찾는 방법, 정렬 불필요"},{"term":"이진 검색","desc":"중간값과 비교해 범위를 반씩 줄이는 방법, 정렬 필수"},{"term":"해싱","desc":"해시 함수로 저장 위치를 계산해 바로 찾는 방법"}],"memo":"'반드시 정렬'이 필요한 것은 이진 검색이다. 선형 검색에 붙으면 틀린 보기다."}},{"id":"written-2022-2-32","no":32,"unit":"소프트웨어 개발","q":"버블 정렬을 이용하여 다음 자료를 오름차순으로 정렬할 경우 PASS 1의 결과는?\n<img src=\"data/img/eip_written_20220424_032.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["6, 9, 7, 3, 5","3, 9, 6, 7, 5","3, 6, 7, 9, 5","6, 7, 3, 5, 9"],"ans":4,"rate":69,"wiki":[{"title":"버블 정렬","url":"https://itwiki.kr/w/버블 정렬"}],"exp":{"concept":"버블 정렬은 이웃한 두 값을 비교해 앞의 값이 더 크면 자리를 바꾸는 과정을 끝까지 반복하는 정렬이다. 한 회전(PASS)이 끝나면 가장 큰 값이 거품처럼 맨 뒤로 올라가 자리를 잡는다.","choices":[{"verdict":"오답","why":"6, 9, 7, 3, 5는 첫 번째 비교(9와 6 교환)만 한 상태로, PASS 1이 끝난 결과가 아니다."},{"verdict":"오답","why":"3, 9, 6, 7, 5는 뒤에서부터 비교해 가장 작은 값 3을 맨 앞으로 끌어올린 결과다. 문제의 버블 정렬은 앞에서부터 비교해 가장 큰 값을 맨 뒤로 보내므로 PASS 1 결과와 다르다."},{"verdict":"오답","why":"3, 6, 7, 9, 5는 최솟값 3을 찾아 첫 자리의 9와 교환한 선택 정렬 1회전 결과다. 버블 정렬 1회전 후에는 가장 큰 값 9가 맨 뒤에 있어야 한다."},{"verdict":"정답","why":"9,6 비교 교환 → 6,9,7,3,5. 9,7 비교 교환 → 6,7,9,3,5. 9,3 비교 교환 → 6,7,3,9,5. 9,5 비교 교환 → 6,7,3,5,9. 따라서 PASS 1의 결과는 6, 7, 3, 5, 9다."}],"keywords":[{"term":"버블 정렬","desc":"인접한 두 값을 비교·교환해 큰 값을 뒤로 보내는 정렬"},{"term":"선택 정렬","desc":"남은 값 중 최솟값을 찾아 앞자리와 교환하는 정렬"},{"term":"삽입 정렬","desc":"앞쪽의 정렬된 부분에 새 값을 알맞은 위치로 끼워 넣는 정렬"}],"memo":"버블 정렬 1회전 결과는 항상 최댓값이 맨 뒤에 있다. 보기 중 맨 끝이 최댓값인 것부터 확인한다."}},{"id":"written-2022-2-33","no":33,"unit":"소프트웨어 개발","q":"다음은 인스펙션(Inspection) 과정을 표현한 것이다. (가)~(마)에 들어갈 말을 보기에서 찾아 바르게 연결한 것은?\n<img src=\"data/img/eip_written_20220424_033.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["(가) - ㉡, (나) - ㉢","(나) - ㉠, (다) - ㉢","(다) - ㉢, (라) - ㉤","(라) - ㉣, (마) - ㉢"],"ans":2,"rate":62,"exp":{"concept":"인스펙션(Inspection)은 검토 전문가가 정해진 절차에 따라 산출물을 꼼꼼히 검토하는 공식적인 정적 테스트다. 절차는 계획 → 사전 교육 → 준비 → 인스펙션 회의 → 수정 → 후속 조치 순서이며, 그림에서 (가)~(마)는 계획 다음의 다섯 단계에 해당한다.","choices":[{"verdict":"오답","why":"(가)-㉡ 사전 교육은 맞지만, (나)에는 준비(㉠)가 와야 하므로 (나)-㉢ 인스펙션 회의는 틀린 연결이다."},{"verdict":"정답","why":"(가) 사전 교육, (나) 준비, (다) 인스펙션 회의, (라) 수정, (마) 후속 조치이므로 (나)-㉠ 준비, (다)-㉢ 인스펙션 회의는 모두 올바른 연결이다."},{"verdict":"오답","why":"(다)-㉢ 인스펙션 회의는 맞지만, (라)에는 수정(㉣)이 와야 하므로 (라)-㉤ 후속 조치는 틀린 연결이다."},{"verdict":"오답","why":"(라)-㉣ 수정은 맞지만, (마)에는 후속 조치(㉤)가 와야 하므로 (마)-㉢ 인스펙션 회의는 틀린 연결이다."}],"keywords":[{"term":"인스펙션 절차","desc":"계획 → 사전 교육 → 준비 → 인스펙션 회의 → 수정 → 후속 조치"},{"term":"인스펙션","desc":"검토 전문가가 정해진 절차로 수행하는 공식 검토"},{"term":"워크스루","desc":"작성자 주도의 비공식 검토"}],"memo":"'계획하고, 가르치고, 준비해서, 회의하고, 고치고, 마무리한다'는 일의 자연스러운 흐름으로 외운다."}},{"id":"written-2022-2-34","no":34,"unit":"소프트웨어 개발","q":"소프트웨어를 보다 쉽게 이해할 수 있고 적은 비용으로 수정할 수 있도록 겉으로 보이는 동작의 변화 없이 내부구조를 변경하는 것은?","choices":["Refactoring","Architecting","Specification","Renewal"],"ans":1,"rate":82,"wiki":[{"title":"리팩토링","url":"https://itwiki.kr/w/리팩토링"}],"exp":{"concept":"리팩토링(Refactoring)은 프로그램이 겉으로 하는 일(기능, 동작)은 그대로 두고 코드 내부 구조만 더 깔끔하게 고치는 작업이다. 방 안 물건은 그대로 두고 정리만 다시 하는 것과 같아서, 코드를 이해하기 쉬워지고 나중에 수정하는 비용이 줄어든다.","choices":[{"verdict":"정답","why":"Refactoring(리팩토링)은 외부 동작의 변화 없이 내부 구조를 개선해 소프트웨어를 이해하기 쉽고 적은 비용으로 수정할 수 있게 하는 작업이다."},{"verdict":"오답","why":"Architecting은 시스템의 전체 구조(아키텍처)를 설계하는 활동으로, 기존 코드의 내부 구조를 개선하는 작업을 가리키지 않는다."},{"verdict":"오답","why":"Specification(명세)은 요구사항이나 설계를 정확하게 기술한 문서로, 코드 구조를 고치는 작업이 아니다."},{"verdict":"오답","why":"Renewal은 '갱신, 재생'이라는 일반 단어로, 출제 범위에서 외부 동작을 유지한 채 내부 구조를 바꾸는 작업을 가리키는 용어가 아니다."}],"keywords":[{"term":"리팩토링(Refactoring)","desc":"외부 동작은 유지하고 내부 구조를 개선하는 작업"},{"term":"코드 스멜(Code Smell)","desc":"리팩토링이 필요하다는 신호가 되는 나쁜 코드 특징"},{"term":"클린 코드","desc":"가독성이 높고 단순하며 의존성이 적은 코드"}],"memo":"'겉으로 보이는 동작 변화 없이 내부 구조 변경'은 리팩토링의 정의 그대로다."}},{"id":"written-2022-2-35","no":35,"unit":"소프트웨어 개발","q":"단위 테스트(Unit Test)와 관련한 설명으로 틀린 것은?","choices":["구현 단계에서 각 모듈의 개발을 완료한 후 개발자가 명세서의 내용대로 정확히 구현되었는지 테스트한다.","모듈 내부의 구조를 구체적으로 볼 수 있는 구조적 테스트를 주로 시행한다.","필요 데이터를 인자를 통해 넘겨주고, 테스트 완료 후 그 결과값을 받는 역할을 하는 가상의 모듈을 테스트 스텁(Stub)이라고 한다.","테스트할 모듈을 호출하는 모듈도 있고, 테스트할 모듈이 호출하는 모듈도 있다."],"ans":3,"rate":57,"wiki":[{"title":"단위 테스트","url":"https://itwiki.kr/w/단위 테스트"},{"title":"소프트웨어 테스트","url":"https://itwiki.kr/w/소프트웨어 테스트"},{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"단위 테스트는 하나의 모듈이 제대로 동작하는지 따로 떼어 확인하는 테스트다. 혼자서는 실행할 수 없으므로 가짜 모듈을 만든다. 테스트할 모듈을 호출하며 데이터를 넘겨주고 결과를 받는 가짜 상위 모듈이 테스트 드라이버, 테스트할 모듈이 호출하는 가짜 하위 모듈이 테스트 스텁이다.","choices":[{"verdict":"오답","why":"단위 테스트는 구현 단계에서 각 모듈을 완성한 뒤 개발자가 명세서대로 정확히 구현되었는지 확인하는 테스트이므로 옳다."},{"verdict":"오답","why":"단위 테스트는 모듈 내부 구조를 구체적으로 볼 수 있으므로 구조적(화이트박스) 테스트를 주로 시행한다는 설명은 옳다."},{"verdict":"정답","why":"필요한 데이터를 인자로 넘겨주고 테스트 후 결과값을 받는 가상 모듈은 테스트 드라이버(Driver)다. 테스트 스텁(Stub)은 테스트할 모듈이 호출하는 하위 모듈을 대신하는 가상 모듈이다."},{"verdict":"오답","why":"테스트할 모듈을 호출하는 상위 모듈(드라이버로 대체)도 있고 테스트할 모듈이 호출하는 하위 모듈(스텁으로 대체)도 있으므로 옳다."}],"keywords":[{"term":"테스트 드라이버(Driver)","desc":"테스트 대상 모듈을 호출하는 가상의 상위 모듈, 상향식 통합에 사용"},{"term":"테스트 스텁(Stub)","desc":"테스트 대상 모듈이 호출하는 가상의 하위 모듈, 하향식 통합에 사용"},{"term":"단위 테스트","desc":"개별 모듈의 기능을 확인하는 테스트"}],"memo":"드라이버는 운전자처럼 대상 모듈을 '부르는' 쪽, 스텁은 '불려 가는' 쪽이다."}},{"id":"written-2022-2-36","no":36,"unit":"소프트웨어 개발","q":"IDE(Integrated Development Environment) 도구의 각 기능에 대한 설명으로 틀린 것은?","choices":["Coding - 프로그래밍 언어를 가지고 컴퓨터 프로그램을 작성할 수 있는 환경을 제공","Compile - 저급언어의 프로그램을 고급언어 프로그램으로 변환하는 기능","Debugging - 프로그램에서 발견되는 버그를 찾아 수정할 수 있는 기능","Deployment - 소프트웨어를 최종 사용자에게 전달하기 위한 기능"],"ans":2,"rate":74,"wiki":[{"title":"컴파일","url":"https://itwiki.kr/w/컴파일"}],"exp":{"concept":"IDE(Integrated Development Environment, 통합 개발 환경)는 코드 작성, 컴파일, 디버깅, 배포 등 개발에 필요한 기능을 하나의 프로그램에 모아 놓은 도구다. 이클립스, 비주얼 스튜디오, 인텔리제이 등이 있다. 컴파일은 사람이 읽기 쉬운 고급 언어를 컴퓨터가 실행할 수 있는 저급 언어(기계어)로 바꾸는 작업이다.","choices":[{"verdict":"오답","why":"Coding 기능은 프로그래밍 언어로 프로그램을 작성할 수 있는 편집 환경을 제공하므로 옳다."},{"verdict":"정답","why":"Compile은 고급 언어로 작성된 프로그램을 저급 언어(기계어나 목적 코드)로 변환하는 기능이다. 저급 언어를 고급 언어로 바꾼다는 설명은 방향이 반대다."},{"verdict":"오답","why":"Debugging은 프로그램에서 발견되는 버그를 찾아 수정할 수 있는 기능이므로 옳다."},{"verdict":"오답","why":"Deployment(배포)는 완성된 소프트웨어를 최종 사용자에게 전달하기 위한 기능이므로 옳다."}],"keywords":[{"term":"IDE","desc":"코딩, 컴파일, 디버깅, 배포 등을 하나로 통합한 개발 환경"},{"term":"컴파일(Compile)","desc":"고급 언어를 저급 언어(기계어)로 번역"},{"term":"디버깅(Debugging)","desc":"프로그램의 오류(버그)를 찾아 수정"}],"memo":"컴파일은 '사람 말(고급) → 기계 말(저급)'이다. 방향이 뒤집힌 보기를 조심한다."}},{"id":"written-2022-2-37","no":37,"unit":"소프트웨어 개발","q":"아래 Tree 구조에 대하여 후위 순회(Postorder) 한 결과는?\n<img src=\"data/img/eip_written_20220424_037.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["a → b → d → c → e → g → h → f","d → b → g → h → e → f → c → a","d → b → a → g → e → h → c → f","a → b → d → g → e → h → c → f"],"ans":2,"rate":69,"wiki":[{"title":"순회","url":"https://itwiki.kr/w/순회"},{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"트리 순회는 노드를 방문하는 순서에 따라 전위(Preorder: 루트-왼쪽-오른쪽), 중위(Inorder: 왼쪽-루트-오른쪽), 후위(Postorder: 왼쪽-오른쪽-루트)로 나뉜다. 후위 순회는 자식들을 모두 방문한 뒤 마지막에 부모(루트)를 방문한다.","choices":[{"verdict":"오답","why":"a → b → d → c → e → g → h → f는 루트를 먼저 방문하는 전위 순회 결과로, 후위 순회가 아니다."},{"verdict":"정답","why":"루트 a의 왼쪽 서브트리 b에서 d → b, 오른쪽 서브트리 c에서는 c의 왼쪽 e의 서브트리를 g → h → e 순으로, 그다음 f, c를 방문한다. 마지막으로 루트 a를 방문하므로 d → b → g → h → e → f → c → a다."},{"verdict":"오답","why":"d → b → a → g → e → h → c → f는 왼쪽-루트-오른쪽 순서인 중위 순회 결과로, 후위 순회가 아니다."},{"verdict":"오답","why":"a → b → d → g → e → h → c → f는 루트 a를 맨 먼저 방문하고 있어 후위 순회가 될 수 없다. 후위 순회에서 루트는 항상 마지막이다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"루트 → 왼쪽 → 오른쪽"},{"term":"중위 순회(Inorder)","desc":"왼쪽 → 루트 → 오른쪽"},{"term":"후위 순회(Postorder)","desc":"왼쪽 → 오른쪽 → 루트"}],"memo":"전·중·후는 루트를 방문하는 위치다. 후위 순회 결과의 마지막은 항상 루트(a)이므로 끝이 a인 보기를 먼저 찾는다."}},{"id":"written-2022-2-38","no":38,"unit":"소프트웨어 개발","q":"인터페이스 구현 시 사용하는 기술로 속성-값 쌍(Attribute-Value Pairs)으로 이루어진 데이터 오브젝트를 전달하기 위해 사용하는 개방형 표준 포맷은?","choices":["JSON","HTML","AVPN","DOF"],"ans":1,"rate":82,"wiki":[{"title":"JSON","url":"https://itwiki.kr/w/JSON"},{"title":"HTML","url":"https://itwiki.kr/w/HTML"},{"title":"AVPN","url":"https://itwiki.kr/w/AVPN"},{"title":"DOF","url":"https://itwiki.kr/w/DOF"}],"exp":{"concept":"JSON(JavaScript Object Notation)은 \"이름\": 값 형태의 속성-값 쌍으로 데이터를 표현하는 가벼운 개방형 표준 데이터 형식이다. 사람이 읽기 쉽고 형식이 단순해, 시스템 사이에서 데이터를 주고받는 인터페이스 구현에 널리 쓰인다.","choices":[{"verdict":"정답","why":"JSON은 속성-값 쌍(Attribute-Value Pairs)으로 이루어진 데이터 오브젝트를 전달하기 위해 사용하는 개방형 표준 포맷이다."},{"verdict":"오답","why":"HTML(HyperText Markup Language)은 웹 문서의 구조를 태그로 표현하는 마크업 언어로, 속성-값 쌍 데이터 전달용 포맷이 아니다."},{"verdict":"오답","why":"AVPN은 출제 범위의 표준 데이터 포맷이 아니다."},{"verdict":"오답","why":"DOF는 출제 범위의 표준 데이터 포맷이 아니다."}],"keywords":[{"term":"JSON","desc":"속성-값 쌍으로 데이터를 표현하는 경량 개방형 표준 포맷"},{"term":"XML","desc":"사용자 정의 태그로 데이터를 표현하는 마크업 언어"},{"term":"AJAX","desc":"자바스크립트로 페이지 전체를 새로 고치지 않고 서버와 비동기 통신하는 기술"}],"memo":"'속성-값 쌍', '개방형 표준 포맷'이 나오면 JSON이다."}},{"id":"written-2022-2-39","no":39,"unit":"소프트웨어 개발","q":"순서가 있는 리스트에서 데이터의 삽입(Push), 삭제(Pop)가 한 쪽 끝에서 일어나며 LIFO(Last-In-First-Out)의 특징을 가지는 자료구조는?","choices":["Tree","Graph","Stack","Queue"],"ans":3,"rate":82,"wiki":[{"title":"그래프","url":"https://itwiki.kr/w/그래프"},{"title":"스택","url":"https://itwiki.kr/w/스택"},{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)에서만 넣고(Push) 빼는(Pop) 자료구조다. 접시를 쌓으면 마지막에 올린 접시를 가장 먼저 꺼내듯이, 나중에 들어간 것이 먼저 나오는 LIFO(Last-In-First-Out) 구조다.","choices":[{"verdict":"오답","why":"트리(Tree)는 노드들이 부모-자식 관계로 연결된 계층형 비선형 자료구조로, 한쪽 끝에서만 삽입·삭제하는 구조가 아니다."},{"verdict":"오답","why":"그래프(Graph)는 정점과 간선으로 이루어진 비선형 자료구조로, LIFO 특징을 갖지 않는다."},{"verdict":"정답","why":"스택은 한쪽 끝에서만 삽입(Push)과 삭제(Pop)가 일어나는 LIFO 구조의 선형 자료구조다."},{"verdict":"오답","why":"큐(Queue)는 한쪽 끝(Rear)에서 삽입하고 반대쪽 끝(Front)에서 삭제하는 FIFO(First-In-First-Out) 구조다."}],"keywords":[{"term":"스택(Stack)","desc":"한쪽 끝에서만 삽입·삭제하는 LIFO 구조"},{"term":"큐(Queue)","desc":"한쪽에서 삽입, 반대쪽에서 삭제하는 FIFO 구조"},{"term":"데크(Deque)","desc":"양쪽 끝 모두에서 삽입·삭제가 가능한 구조"}],"memo":"스택은 접시 쌓기(LIFO), 큐는 줄 서기(FIFO)다."}},{"id":"written-2022-2-40","no":40,"unit":"소프트웨어 개발","q":"다음 중 단위 테스트 도구로 사용될 수 없는 것은?","choices":["CppUnit","JUnit","HttpUnit","IgpUnit"],"ans":4,"rate":57,"wiki":[{"title":"단위 테스트","url":"https://itwiki.kr/w/단위 테스트"}],"exp":{"concept":"단위 테스트 도구는 모듈 하나하나를 자동으로 테스트할 수 있게 도와주는 프레임워크다. 언어별로 xUnit 계열 도구가 있는데, 자바는 JUnit, C++는 CppUnit, .NET은 NUnit 등이 있고, HttpUnit은 웹 애플리케이션을 테스트하는 도구다.","choices":[{"verdict":"오답","why":"CppUnit은 C++ 프로그램용 단위 테스트 도구다."},{"verdict":"오답","why":"JUnit은 자바 프로그램용 단위 테스트 도구다."},{"verdict":"오답","why":"HttpUnit은 웹 브라우저 없이 웹 애플리케이션의 동작을 테스트할 수 있게 해 주는 테스트 도구다."},{"verdict":"정답","why":"IgpUnit은 존재하지 않는 이름으로, 출제 범위의 표준 단위 테스트 도구가 아니다."}],"keywords":[{"term":"xUnit","desc":"JUnit, CppUnit, NUnit 등 언어별 단위 테스트 프레임워크의 통칭"},{"term":"JUnit","desc":"자바용 단위 테스트 프레임워크"},{"term":"CppUnit","desc":"C++용 단위 테스트 프레임워크"},{"term":"HttpUnit","desc":"웹 브라우저 없이 웹 애플리케이션을 테스트하는 도구"}],"memo":"'언어 이름 + Unit' 형태(Cpp, J, N)를 기억하면 IgpUnit처럼 없는 이름을 골라낼 수 있다."}},{"id":"written-2022-2-41","no":41,"unit":"데이터베이스 구축","q":"다음 조건을 모두 만족하는 정규형은?\n<img src=\"data/img/eip_written_20220424_041.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["BCNF","제1정규형","제2정규형","제3정규형"],"ans":1,"rate":57,"exp":{"concept":"정규화는 이상(Anomaly)이 생기지 않도록 테이블을 단계적으로 나누는 과정이다. 제1정규형은 모든 값이 원자값, 제2정규형은 부분 함수 종속 제거, 제3정규형은 이행 함수 종속 제거, BCNF는 모든 결정자가 후보키가 되도록 하는 단계다. 지문의 세 조건을 모두 만족하는 가장 높은 단계를 고르면 된다.","choices":[{"verdict":"정답","why":"지문의 세 조건은 차례로 원자값(제1정규형), 부분 종속 없음(제2정규형), 모든 결정자가 후보키(BCNF)를 뜻한다. 마지막 조건은 BCNF의 정의이며, 이를 만족하면 제3정규형 조건(이행 종속 제거)도 함께 만족하므로 BCNF다."},{"verdict":"오답","why":"제1정규형은 모든 도메인이 원자값이라는 첫 번째 조건만 요구하므로, 부분 종속 제거와 '모든 결정자가 후보키' 조건까지 모두 만족하는 정규형으로는 부족하다."},{"verdict":"오답","why":"제2정규형은 제1정규형에서 부분 함수 종속을 제거한 단계로, '모든 결정자가 후보키'라는 세 번째 조건은 요구하지 않는다."},{"verdict":"오답","why":"제3정규형은 이행 함수 종속까지 제거한 단계지만, 후보키가 아닌 결정자가 남아 있을 수 있어 '모든 결정자가 후보키'라는 조건은 보장하지 않는다."}],"keywords":[{"term":"제1정규형(1NF)","desc":"모든 도메인이 원자값"},{"term":"제2정규형(2NF)","desc":"부분 함수 종속 제거(완전 함수 종속)"},{"term":"제3정규형(3NF)","desc":"이행 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거, 즉 모든 결정자가 후보키"}],"memo":"'도부이결다조'(도메인 원자값, 부분 종속 제거, 이행 종속 제거, 결정자이면서 후보키 아닌 것 제거, 다치 종속 제거, 조인 종속 제거)로 정규화 순서를 외운다."}},{"id":"written-2022-2-42","no":42,"unit":"데이터베이스 구축","q":"데이터베이스의 트랜잭션 성질들 중에서 다음 설명에 해당하는 것은?\n<img src=\"data/img/eip_written_20220424_042.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Atomicity","Consistency","Isolation","Durability"],"ans":1,"rate":66,"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"},{"title":"트랜잭션 특징","url":"https://itwiki.kr/w/트랜잭션 특징"}],"exp":{"concept":"트랜잭션은 데이터베이스에서 한꺼번에 처리되어야 하는 작업 단위로, ACID라는 네 가지 성질을 가진다. 그중 원자성(Atomicity)은 '모두 되거나, 하나도 안 되거나(All or Nothing)'다. 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없도록, 중간에 실패하면 처음 상태로 되돌린다.","choices":[{"verdict":"정답","why":"Atomicity(원자성)는 트랜잭션의 연산이 모두 정상적으로 완료되거나, 아니면 전혀 수행되지 않은 원래 상태로 되돌아가야 한다는 성질로, 지문의 설명과 같다."},{"verdict":"오답","why":"Consistency(일관성)는 트랜잭션이 성공적으로 완료되면 데이터베이스가 언제나 일관성 있는 상태를 유지해야 한다는 성질이다."},{"verdict":"오답","why":"Isolation(독립성, 격리성)은 여러 트랜잭션이 동시에 실행될 때 한 트랜잭션이 끝나기 전에는 다른 트랜잭션이 그 중간 결과에 끼어들 수 없다는 성질이다."},{"verdict":"오답","why":"Durability(영속성, 지속성)는 성공적으로 완료된 트랜잭션의 결과는 시스템에 장애가 생겨도 영구히 반영되어야 한다는 성질이다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"모두 수행되거나 전혀 수행되지 않음(All or Nothing)"},{"term":"일관성(Consistency)","desc":"트랜잭션 후에도 데이터베이스가 일관된 상태 유지"},{"term":"독립성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"영속성(Durability)","desc":"완료된 결과는 영구히 반영됨"}],"memo":"'전부 아니면 전무', '원래 상태로 되돌린다(Rollback)'가 나오면 원자성이다."}},{"id":"written-2022-2-43","no":43,"unit":"데이터베이스 구축","q":"분산 데이터베이스 시스템과 관련한 설명으로 틀린 것은?","choices":["물리적으로 분산된 데이터베이스 시스템을 논리적으로 하나의 데이터베이스 시스템처럼 사용할 수 있도록 한 것이다.","물리적으로 분산되어 지역별로 필요한 데이터를 처리할 수 있는 지역 컴퓨터(Local Computer)를 분산 처리기(Distributed Processor)라고 한다.","분산 데이터베이스 시스템을 위한 통신 네트워크 구조가 데이터 통신에 영향을 주므로 효율적으로 설계해야 한다.","데이터베이스가 분산되어 있음을 사용자가 인식할 수 있도록 분산 투명성(Distribution Transparency)을 배제해야 한다."],"ans":4,"rate":83,"wiki":[{"title":"분산 데이터베이스","url":"https://itwiki.kr/w/분산 데이터베이스"}],"exp":{"concept":"분산 데이터베이스는 데이터가 여러 지역의 컴퓨터에 나뉘어 저장되어 있지만, 사용자에게는 하나의 데이터베이스처럼 보이도록 만든 시스템이다. 사용자가 데이터가 어디에 어떻게 나뉘어 있는지 신경 쓰지 않아도 되게 하는 성질을 분산 투명성이라고 하며, 분산 데이터베이스의 핵심 목표다.","choices":[{"verdict":"오답","why":"물리적으로 분산된 데이터베이스를 논리적으로 하나의 데이터베이스처럼 사용하도록 한 것이 분산 데이터베이스이므로 옳다."},{"verdict":"오답","why":"지역별로 필요한 데이터를 처리할 수 있는 지역 컴퓨터를 분산 처리기라고 하며, 분산 데이터베이스의 구성 요소이므로 옳다."},{"verdict":"오답","why":"분산된 사이트들은 통신 네트워크로 연결되고 그 구조가 데이터 통신 성능에 영향을 주므로 효율적으로 설계해야 한다는 설명은 옳다."},{"verdict":"정답","why":"분산 데이터베이스는 사용자가 데이터의 분산 여부를 의식하지 않도록 분산 투명성을 보장해야 한다. 분산을 인식할 수 있게 투명성을 배제해야 한다는 설명은 목표와 반대다."}],"keywords":[{"term":"분산 데이터베이스 구성 요소","desc":"분산 처리기, 분산 데이터베이스, 통신 네트워크"},{"term":"위치 투명성","desc":"데이터의 물리적 위치를 몰라도 접근 가능"},{"term":"중복(복제) 투명성","desc":"데이터가 여러 곳에 복제되어 있어도 하나처럼 사용"},{"term":"병행 투명성 / 장애 투명성","desc":"여러 트랜잭션이 동시에 실행되거나 장애가 생겨도 결과가 정확함"}],"memo":"투명성은 '보이지 않게 감춰 준다'는 뜻이다. 분산 DB는 투명성을 보장해야지 배제하면 안 된다. 분산 투명성은 '위중병장'(위치, 중복, 병행, 장애)으로 외운다."}},{"id":"written-2022-2-44","no":44,"unit":"데이터베이스 구축","q":"다음 테이블을 보고 강남지점의 판매량이 많은 제품부터 출력되도록 할 때 다음 중 가장 적절한 SQL 구문은? (단, 출력은 제품명과 판매량이 출력되도록 한다.)\n<img src=\"data/img/eip_written_20220424_044.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SELECT 제품명, 판매량 FROM 푸드ORDER BY 판매량 ASC;","SELECT 제품명, 판매량 FROM 푸드ORDER BY 판매량 DESC;","SELECT 제품명, 판매량 FROM 푸드WHERE 지점명 = '강남지점'ORDER BY 판매량 ASC;","SELECT 제품명, 판매량 FROM 푸드WHERE 지점명 = '강남지점'ORDER BY 판매량 DESC;"],"ans":4,"rate":74,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"SELECT 문은 FROM으로 테이블을 고르고, WHERE로 원하는 행만 거른 뒤, ORDER BY로 정렬한다. ASC는 오름차순(작은 값부터), DESC는 내림차순(큰 값부터)이다. '강남지점'만 골라 '판매량이 많은 것부터' 보여 주려면 WHERE 지점명 = '강남지점'과 ORDER BY 판매량 DESC가 모두 필요하다.","choices":[{"verdict":"오답","why":"WHERE 절이 없어 모든 지점의 행이 출력되고, ASC라서 판매량이 적은 것부터 정렬되므로 두 조건을 모두 어긴다."},{"verdict":"오답","why":"DESC로 많은 것부터 정렬하지만 WHERE 절이 없어 강남지점이 아닌 행(강북, 수원, 인천지점)까지 모두 출력된다."},{"verdict":"오답","why":"강남지점만 거르지만 ASC로 정렬하므로 판매량이 적은 것부터 도시락 200, 잡채밥 250, 비빔밥 500, 미역국 550 순으로 출력되어 조건과 반대다."},{"verdict":"정답","why":"WHERE 지점명 = '강남지점'으로 강남지점의 4개 행만 남기고, ORDER BY 판매량 DESC로 정렬하면 미역국 550, 비빔밥 500, 잡채밥 250, 도시락 200 순으로 제품명과 판매량이 출력된다."}],"keywords":[{"term":"WHERE","desc":"조건에 맞는 행만 골라내는 절"},{"term":"ORDER BY ~ ASC","desc":"오름차순 정렬(기본값)"},{"term":"ORDER BY ~ DESC","desc":"내림차순 정렬"}],"memo":"'많은 것부터, 최신부터, 높은 것부터'는 DESC다. ORDER BY에서 생략하면 ASC로 처리된다."}},{"id":"written-2022-2-45","no":45,"unit":"데이터베이스 구축","q":"데이터베이스의 인덱스와 관련한 설명으로 틀린 것은?","choices":["문헌의 색인, 사전과 같이 데이터를 쉽고 빠르게 찾을 수 있도록 만든 데이터 구조이다.","테이블에 붙여진 색인으로 데이터 검색 시 처리 속도 향상에 도움이 된다.","인덱스의 추가, 삭제 명령어는 각각 ADD, DELETE이다.","대부분의 데이터베이스에서 테이블을 삭제하면 인덱스도 같이 삭제된다."],"ans":3,"rate":79,"exp":{"concept":"인덱스(Index)는 책 뒤의 색인처럼, 데이터를 빨리 찾을 수 있도록 키 값과 데이터 위치를 따로 정리해 둔 구조다. SQL에서 인덱스는 CREATE INDEX로 만들고 DROP INDEX로 삭제하며, 인덱스가 붙은 테이블을 삭제하면 그 인덱스도 함께 삭제된다.","choices":[{"verdict":"오답","why":"인덱스는 문헌의 색인이나 사전처럼 데이터를 쉽고 빠르게 찾을 수 있도록 만든 데이터 구조이므로 옳다."},{"verdict":"오답","why":"인덱스는 테이블에 붙여진 색인으로, 검색 시 처리 속도를 높여 주므로 옳다."},{"verdict":"정답","why":"인덱스는 CREATE INDEX 명령으로 생성하고 DROP INDEX 명령으로 삭제한다. ADD와 DELETE는 인덱스 추가·삭제 명령어가 아니다."},{"verdict":"오답","why":"대부분의 데이터베이스에서 테이블을 삭제하면 그 테이블에 속한 인덱스도 함께 삭제되므로 옳다."}],"keywords":[{"term":"CREATE INDEX","desc":"인덱스를 생성하는 DDL 명령"},{"term":"DROP INDEX","desc":"인덱스를 삭제하는 DDL 명령"},{"term":"클러스터드 인덱스","desc":"인덱스 키 순서에 따라 데이터가 물리적으로 정렬되어 저장되는 인덱스"}],"memo":"인덱스는 데이터가 아니라 '구조'이므로 DDL(CREATE/DROP)로 다룬다. DELETE는 행을 지우는 DML이다."}},{"id":"written-2022-2-46","no":46,"unit":"데이터베이스 구축","q":"물리적 데이터베이스 구조의 기본 데이터 단위인 저장 레코드의 양식을 설계할 때 고려 사항이 아닌 것은?","choices":["데이터 타입","데이터 값의 분포","트랜잭션 모델링","접근 빈도"],"ans":3,"rate":59,"exp":{"concept":"물리적 데이터베이스 설계는 논리적으로 정한 구조를 실제 저장 장치에 어떻게 저장할지 정하는 단계다. 저장 레코드 양식을 설계할 때는 데이터 타입, 데이터 값의 분포, 접근 빈도 등을 고려한다. 트랜잭션 모델링은 그보다 앞선 개념적 설계 단계에서 하는 일이다.","choices":[{"verdict":"오답","why":"데이터 타입은 레코드의 각 필드를 어떤 형식과 크기로 저장할지 정하는 데 필요하므로 저장 레코드 양식 설계의 고려 사항이다."},{"verdict":"오답","why":"데이터 값의 분포는 저장 공간 할당과 인덱스 설계 등에 영향을 주므로 저장 레코드 양식 설계의 고려 사항이다."},{"verdict":"정답","why":"트랜잭션 모델링은 개념적 설계 단계에서 E-R 모델링과 함께 수행하는 작업으로, 물리적 저장 레코드 양식 설계의 고려 사항이 아니다."},{"verdict":"오답","why":"접근 빈도는 자주 쓰는 데이터를 어떻게 배치하고 묶을지 정하는 데 영향을 주므로 저장 레코드 양식 설계의 고려 사항이다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 모델링, 트랜잭션 모델링, DBMS에 독립적인 개념 스키마 설계"},{"term":"논리적 설계","desc":"특정 DBMS의 논리적 자료 구조로 변환, 트랜잭션 인터페이스 설계"},{"term":"물리적 설계","desc":"저장 레코드 양식, 접근 경로, 저장 구조 설계, 트랜잭션 세부 설계"}],"memo":"트랜잭션은 개념적 설계에서 '모델링', 논리적 설계에서 '인터페이스 설계', 물리적 설계에서 '세부 설계'로 단계마다 하는 일이 다르다."}},{"id":"written-2022-2-47","no":47,"unit":"데이터베이스 구축","q":"SQL의 기능에 따른 분류 중에서 REVOKE문과 같이 데이터 의 사용 권한을 관리하는데 사용하는 언어는?","choices":["DDL(Data Definition Language)","DML(Data Manipulation Language)","DCL(Data Control Language)","DUL(Data User Language)"],"ans":3,"rate":75,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"DDL","url":"https://itwiki.kr/w/DDL"},{"title":"DML","url":"https://itwiki.kr/w/DML"},{"title":"DCL","url":"https://itwiki.kr/w/DCL"}],"exp":{"concept":"SQL은 기능에 따라 세 가지로 나뉜다. DDL(정의어)은 테이블 같은 구조를 만들고 고치며, DML(조작어)은 데이터를 넣고 조회하고 고치고 지우며, DCL(제어어)은 권한 부여·회수와 트랜잭션 처리를 담당한다. GRANT(권한 부여)와 REVOKE(권한 회수)는 DCL이다.","choices":[{"verdict":"오답","why":"DDL(Data Definition Language)은 CREATE, ALTER, DROP, TRUNCATE처럼 데이터베이스 구조를 정의하는 언어다."},{"verdict":"오답","why":"DML(Data Manipulation Language)은 SELECT, INSERT, UPDATE, DELETE처럼 데이터를 조작하는 언어다."},{"verdict":"정답","why":"DCL(Data Control Language)은 GRANT, REVOKE, COMMIT, ROLLBACK처럼 데이터 사용 권한과 무결성, 회복 등을 제어하는 언어이며, REVOKE는 DCL에 속한다."},{"verdict":"오답","why":"DUL은 SQL 기능 분류에 쓰이는 표준 용어가 아니다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"권한(GRANT, REVOKE)과 트랜잭션 제어(COMMIT, ROLLBACK)는 Control, 즉 DCL이다."}},{"id":"written-2022-2-48","no":48,"unit":"데이터베이스 구축","q":"데이터 사전에 대한 설명으로 틀린 것은?","choices":["시스템 카탈로그 또는 시스템 데이터베이스라고도 한다.","데이터 사전 역시 데이터베이스의 일종이므로 일반 사용자가 생성, 유지 및 수정 할 수 있다.","데이터베이스에 대한 데이터인 메타데이터(Metadata)를 저장하고 있다.","데이터 사전에 있는 데이터에 실제로 접근하는 데 필요한 위치 정보는 데이터 디렉토리(Data Directory)라는 곳에서 관리한다."],"ans":2,"rate":79,"wiki":[{"title":"시스템 카탈로그","url":"https://itwiki.kr/w/시스템 카탈로그"}],"exp":{"concept":"데이터 사전(Data Dictionary)은 데이터베이스에 들어 있는 테이블, 속성, 제약 조건, 사용자 같은 '데이터에 대한 데이터(메타데이터)'를 저장한 곳으로, 시스템 카탈로그라고도 한다. DBMS가 스스로 생성하고 갱신하며, 사용자는 조회만 할 수 있다.","choices":[{"verdict":"오답","why":"데이터 사전은 시스템 카탈로그 또는 시스템 데이터베이스라고도 부르므로 옳다."},{"verdict":"정답","why":"데이터 사전은 DBMS가 스스로 생성하고 유지하며, 일반 사용자는 SELECT로 내용을 조회할 수만 있고 직접 생성·수정할 수 없다."},{"verdict":"오답","why":"데이터 사전은 데이터베이스에 대한 데이터인 메타데이터를 저장하므로 옳다."},{"verdict":"오답","why":"데이터 사전에 수록된 데이터에 실제로 접근하는 데 필요한 위치 정보는 데이터 디렉터리(Data Directory)에서 관리하므로 옳다."}],"keywords":[{"term":"데이터 사전(시스템 카탈로그)","desc":"메타데이터를 저장하는 시스템 데이터베이스"},{"term":"메타데이터(Metadata)","desc":"데이터에 대한 데이터"},{"term":"데이터 디렉터리","desc":"데이터 사전에 접근하기 위한 위치 정보를 관리하며 시스템만 접근"}],"memo":"카탈로그는 사용자가 '읽기만' 가능하다. 갱신은 DBMS가 자동으로 한다."}},{"id":"written-2022-2-49","no":49,"unit":"데이터베이스 구축","q":"데이터베이스에서 릴레이션에 대한 설명으로 틀린 것은?","choices":["모든 튜플은 서로 다른 값을 가지고 있다.","하나의 릴레이션에서 튜플은 특정한 순서를 가진다.","각 속성은 릴레이션 내에서 유일한 이름을 가진다.","모든 속성 값은 원자 값(atomic value)을 가진다."],"ans":2,"rate":68,"exp":{"concept":"릴레이션(테이블)은 행(튜플)과 열(속성)로 이루어진다. 릴레이션에는 몇 가지 특징이 있는데, 똑같은 튜플이 두 개 있을 수 없고, 튜플과 속성 사이에는 정해진 순서가 없으며, 모든 속성 값은 더 나눌 수 없는 원자값이다.","choices":[{"verdict":"오답","why":"릴레이션의 모든 튜플은 서로 다른 값을 가지며, 똑같은 튜플이 중복될 수 없으므로 옳다."},{"verdict":"정답","why":"하나의 릴레이션에서 튜플들 사이에는 순서가 없다. 튜플은 특정한 순서를 가진다는 설명은 틀렸다."},{"verdict":"오답","why":"각 속성은 릴레이션 안에서 유일한 이름을 가지므로 옳다."},{"verdict":"오답","why":"모든 속성 값은 더 이상 나눌 수 없는 원자값이므로 옳다."}],"keywords":[{"term":"튜플의 유일성","desc":"릴레이션 안의 튜플은 모두 서로 다름"},{"term":"튜플의 무순서성","desc":"튜플 사이에 순서가 없음"},{"term":"속성의 무순서성","desc":"속성 사이에도 순서가 없음"},{"term":"속성의 원자성","desc":"속성 값은 더 이상 나눌 수 없는 원자값"}],"memo":"릴레이션에서는 튜플도 속성도 '순서가 없다'. 순서가 있다고 하면 틀린 보기다."}},{"id":"written-2022-2-50","no":50,"unit":"데이터베이스 구축","q":"데이터베이스에서의 뷰(View)에 대한 설명으로 틀린 것은?","choices":["뷰는 다른 뷰를 기반으로 새로운 뷰를 만들 수 있다.","뷰는 일종의 가상 테이블이며, update에는 제약이 따른다.","뷰는 기본 테이블을 만드는 것처럼 create view를 사용하여 만들 수 있다.","뷰는 논리적으로 존재하는 기본 테이블과 다르게 물리적으로만 존재하며 카탈로그에 저장된다."],"ans":4,"rate":77,"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"exp":{"concept":"뷰(View)는 하나 이상의 기본 테이블에서 필요한 부분만 뽑아 만든 가상 테이블이다. 실제 데이터를 따로 저장하지 않고 정의(SELECT 문)만 저장해 두었다가 사용할 때마다 기본 테이블에서 가져온다. 그래서 뷰는 논리적으로만 존재하고, 그 정의는 시스템 카탈로그에 저장된다.","choices":[{"verdict":"오답","why":"뷰를 기반으로 또 다른 뷰를 만들 수 있으므로 옳다."},{"verdict":"오답","why":"뷰는 가상 테이블이며, 기본 테이블로 변경을 그대로 반영하기 어려운 경우가 있어 삽입·삭제·갱신(UPDATE)에 제약이 따르므로 옳다."},{"verdict":"오답","why":"뷰는 기본 테이블처럼 CREATE VIEW 문으로 만들 수 있으므로 옳다."},{"verdict":"정답","why":"뷰는 물리적으로 존재하는 기본 테이블과 달리 논리적으로만 존재하는 가상 테이블이다. 논리와 물리가 거꾸로 되어 있어 틀렸다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"CREATE VIEW / DROP VIEW","desc":"뷰 생성과 삭제 명령, 뷰는 ALTER로 정의를 바꿀 수 없음"},{"term":"기본 테이블(Base Table)","desc":"물리적으로 데이터가 저장된 실제 테이블"}],"memo":"뷰는 '가상', 즉 논리적으로만 존재한다. '물리적으로만 존재'는 기본 테이블에 대한 설명을 뒤집은 것이다."}},{"id":"written-2022-2-51","no":51,"unit":"데이터베이스 구축","q":"트랜잭션의 상태 중 트랜잭션의 마지막 연산이 실행된 직후의 상태로, 모든 연산의 처리는 끝났지만 트랜잭션이 수행한 최종 결과를 데이터베이스에 반영하지 않은 상태는?","choices":["Active","Partially Committed","Committed","Aborted"],"ans":2,"rate":69,"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"exp":{"concept":"트랜잭션은 실행되는 동안 여러 상태를 거친다. 실행 중이면 활동(Active), 마지막 연산까지 끝났지만 아직 결과를 데이터베이스에 확정하지 않았으면 부분 완료(Partially Committed), 확정(COMMIT)까지 마치면 완료(Committed), 실패하면 실패(Failed)를 거쳐 철회(Aborted)된다. 시험 답안을 다 썼지만 아직 제출 버튼을 누르지 않은 상태가 부분 완료다.","choices":[{"verdict":"오답","why":"Active(활동)는 트랜잭션이 실행 중인 상태로, 마지막 연산이 끝난 상태가 아니다."},{"verdict":"정답","why":"Partially Committed(부분 완료)는 마지막 연산까지 실행했지만 COMMIT 연산이 실행되기 전이라 최종 결과를 데이터베이스에 반영하지 않은 상태다."},{"verdict":"오답","why":"Committed(완료)는 트랜잭션이 성공적으로 종료되어 COMMIT 연산까지 실행되고 결과가 반영된 상태다."},{"verdict":"오답","why":"Aborted(철회)는 트랜잭션이 비정상적으로 종료되어 ROLLBACK 연산을 수행한 상태다."}],"keywords":[{"term":"Active","desc":"트랜잭션이 실행 중인 상태"},{"term":"Partially Committed","desc":"마지막 연산을 마쳤지만 COMMIT 전인 상태"},{"term":"Committed","desc":"COMMIT으로 결과가 확정된 상태"},{"term":"Failed / Aborted","desc":"실행 중 오류로 중단된 상태 / ROLLBACK으로 되돌린 상태"}],"memo":"'연산은 끝났지만 아직 반영 전'은 '부분' 완료다. '반영까지 끝'이면 완료(Committed)다."}},{"id":"written-2022-2-52","no":52,"unit":"데이터베이스 구축","q":"SQL의 명령을 사용 용도에 따라 DDL, DML, DCL로 구분할 경우, 그 성격이 나머지 셋과 다른 것은?","choices":["SELECT","UPDATE","INSERT","GRANT"],"ans":4,"rate":85,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"DDL","url":"https://itwiki.kr/w/DDL"},{"title":"DML","url":"https://itwiki.kr/w/DML"},{"title":"DCL","url":"https://itwiki.kr/w/DCL"}],"exp":{"concept":"SQL 명령은 용도에 따라 DDL(구조 정의), DML(데이터 조작), DCL(권한·트랜잭션 제어)로 나뉜다. SELECT, INSERT, UPDATE, DELETE는 데이터를 다루는 DML이고, GRANT와 REVOKE는 권한을 다루는 DCL이다.","choices":[{"verdict":"오답","why":"SELECT는 데이터를 조회하는 DML 명령이다."},{"verdict":"오답","why":"UPDATE는 데이터를 수정하는 DML 명령이다."},{"verdict":"오답","why":"INSERT는 데이터를 삽입하는 DML 명령이다."},{"verdict":"정답","why":"GRANT는 사용자에게 권한을 부여하는 DCL 명령으로, 나머지 셋(DML)과 성격이 다르다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"GRANT(주다)와 REVOKE(빼앗다)는 권한 짝꿍으로 DCL이다."}},{"id":"written-2022-2-53","no":53,"unit":"데이터베이스 구축","q":"키의 종류 중 유일성과 최소성을 만족하는 속성 또는 속성들의 집합은?","choices":["Atomic key","Super key","Candidate key","Test key"],"ans":3,"rate":58,"wiki":[{"title":"데이터베이스 키","url":"https://itwiki.kr/w/데이터베이스 키"}],"exp":{"concept":"키는 튜플을 구별하는 기준이 되는 속성이다. 유일성은 키 값으로 모든 튜플을 하나씩 구별할 수 있다는 뜻이고, 최소성은 꼭 필요한 속성만으로 이루어져 하나라도 빼면 구별할 수 없다는 뜻이다. 두 조건을 모두 만족하면 후보키, 유일성만 만족하면 슈퍼키다.","choices":[{"verdict":"오답","why":"Atomic key는 키의 종류를 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"Super key(슈퍼키)는 유일성은 만족하지만 최소성은 만족하지 않는 키다."},{"verdict":"정답","why":"Candidate key(후보키)는 유일성과 최소성을 모두 만족하는 속성 또는 속성들의 집합이다."},{"verdict":"오답","why":"Test key는 키의 종류를 가리키는 표준 용어가 아니다."}],"keywords":[{"term":"후보키(Candidate Key)","desc":"유일성과 최소성을 모두 만족하는 키"},{"term":"슈퍼키(Super Key)","desc":"유일성만 만족하는 키"},{"term":"기본키(Primary Key)","desc":"후보키 중 선택한 대표 키, NULL 불가"},{"term":"대체키(Alternate Key)","desc":"후보키 중 기본키로 선택되지 않은 나머지 키"}],"memo":"'유일성 + 최소성 = 후보키', '유일성만 = 슈퍼키'로 짝지어 외운다."}},{"id":"written-2022-2-54","no":54,"unit":"데이터베이스 구축","q":"데이터베이스에서 개념적 설계 단계에 대한 설명으로 틀린 것은?","choices":["산출물로 E-R Diagram을 만들 수 있다.","DBMS에 독립적인 개념 스키마를 설계한다.","트랜잭션 인터페이스를 설계 및 작성한다.","논리적 설계 단계의 앞 단계에서 수행된다."],"ans":3,"rate":59,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행된다. 개념적 설계에서는 현실 세계를 E-R 다이어그램으로 추상화하고, 특정 DBMS와 상관없는 개념 스키마를 만들며, 트랜잭션 모델링을 한다.","choices":[{"verdict":"오답","why":"개념적 설계의 대표 산출물은 E-R 다이어그램이므로 옳다."},{"verdict":"오답","why":"개념적 설계에서는 특정 DBMS에 독립적인 개념 스키마를 설계하므로 옳다."},{"verdict":"정답","why":"트랜잭션 인터페이스 설계는 논리적 설계 단계에서 수행한다. 개념적 설계에서는 트랜잭션 모델링을 한다."},{"verdict":"오답","why":"개념적 설계는 요구 조건 분석 다음, 논리적 설계 앞에서 수행되므로 옳다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 모델링, 트랜잭션 모델링, DBMS 독립적 개념 스키마 설계"},{"term":"논리적 설계","desc":"특정 DBMS의 논리 스키마로 변환, 정규화, 트랜잭션 인터페이스 설계"},{"term":"물리적 설계","desc":"저장 레코드 양식, 접근 경로, 트랜잭션 세부 설계"}],"memo":"트랜잭션은 개념(모델링) → 논리(인터페이스 설계) → 물리(세부 설계) 순으로 구체화된다."}},{"id":"written-2022-2-55","no":55,"unit":"데이터베이스 구축","q":"테이블의 기본키(Primary Key)로 지정된 속성에 관한 설명으로 가장 거리가 먼 것은?","choices":["NOT NULL로 널 값을 가지지 않는다.","릴레이션에서 튜플을 구별할 수 있다.","외래키로 참조될 수 있다.","검색할 때 반드시 필요하다."],"ans":4,"rate":67,"exp":{"concept":"기본키(Primary Key)는 후보키 중에서 테이블의 대표로 정한 키다. 튜플을 유일하게 구별해야 하므로 NULL 값을 가질 수 없고 중복될 수 없다. 다른 테이블이 이 테이블을 참조할 때는 기본키를 외래키로 가져간다.","choices":[{"verdict":"오답","why":"기본키는 개체 무결성에 따라 NULL 값을 가질 수 없으므로 옳은 설명이다."},{"verdict":"오답","why":"기본키는 릴레이션 안의 튜플을 유일하게 구별하는 데 쓰이므로 옳은 설명이다."},{"verdict":"오답","why":"기본키는 다른 릴레이션의 외래키에 의해 참조될 수 있으므로 옳은 설명이다."},{"verdict":"정답","why":"검색은 기본키가 아닌 다른 속성으로도 얼마든지 할 수 있으므로, 검색할 때 반드시 필요하다는 설명은 기본키의 성질과 거리가 멀다."}],"keywords":[{"term":"기본키(Primary Key)","desc":"튜플을 유일하게 식별하는 대표 키, NULL·중복 불가"},{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조하는 속성"},{"term":"개체 무결성","desc":"기본키는 NULL이나 중복 값을 가질 수 없다는 제약"}],"memo":"기본키의 역할은 '구별'이지 '검색 필수 조건'이 아니다."}},{"id":"written-2022-2-56","no":56,"unit":"데이터베이스 구축","q":"데이터 모델의 구성 요소 중 데이터 구조에 따라 개념 세계나 컴퓨터 세계에서 실제로 표현된 값들을 처리하는 작업을 의미하는 것은?","choices":["Relation","Data Structure","Constraint","Operation"],"ans":4,"rate":59,"exp":{"concept":"데이터 모델은 현실 세계를 데이터베이스로 옮기기 위한 틀이며, 세 가지 구성 요소로 이루어진다. 구조(Structure)는 데이터들이 어떤 모양으로 연결되는지, 연산(Operation)은 그 데이터를 어떻게 처리(조회, 삽입, 삭제, 변경)하는지, 제약 조건(Constraint)은 저장될 수 있는 데이터의 논리적 제한이다.","choices":[{"verdict":"오답","why":"Relation(릴레이션)은 관계 데이터 모델에서 데이터를 저장하는 표(테이블)를 뜻하며, 데이터 모델의 구성 요소(구조, 연산, 제약 조건) 이름이 아니다."},{"verdict":"오답","why":"Data Structure(구조)는 개체 타입들과 그 사이의 관계, 즉 데이터의 논리적 구조를 표현하는 요소로, 값을 처리하는 작업이 아니다."},{"verdict":"오답","why":"Constraint(제약 조건)는 데이터베이스에 저장될 수 있는 실제 데이터의 논리적 제약을 나타내는 요소다."},{"verdict":"정답","why":"Operation(연산)은 데이터 구조에 따라 개념 세계나 컴퓨터 세계에서 실제로 표현된 값들을 처리하는 작업으로, 데이터베이스를 조작하는 기본 도구다."}],"keywords":[{"term":"구조(Structure)","desc":"개체 타입과 관계 등 데이터의 논리적 구조"},{"term":"연산(Operation)","desc":"실제로 표현된 값들을 처리하는 작업"},{"term":"제약 조건(Constraint)","desc":"저장될 수 있는 데이터의 논리적 제약"}],"memo":"데이터 모델 3요소는 '구연제'(구조, 연산, 제약 조건)다. '처리하는 작업'은 연산이다."}},{"id":"written-2022-2-57","no":57,"unit":"데이터베이스 구축","q":"다음 [조건]에 부합하는 SQL문을 작성하고자 할 때, [SQL문]의 빈칸에 들어갈 내용으로 옳은 것은? (단, '팀코드' 및 '이름'은 속성이며, '직원'은 테이블이다.)\n<img src=\"data/img/eip_written_20220424_057.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["WHERE 이름 = '정도일'","SELECT 팀코드 FROM 이름WHERE 직원 = '정도일'","WHERE 직원 = '정도일'","SELECT 팀코드 FROM 직원WHERE 이름 = '정도일'"],"ans":4,"rate":80,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"하위 질의(서브쿼리)는 SQL 문 안에 괄호로 넣은 또 하나의 SELECT 문이다. 안쪽 질의가 먼저 실행되어 결과를 만들고, 바깥 질의가 그 결과를 조건으로 사용한다. 이 문제는 안쪽에서 '정도일'의 팀코드를 구하고, 바깥에서 그 팀코드를 가진 직원의 이름을 출력한다.","choices":[{"verdict":"오답","why":"괄호 안에 WHERE 절만 넣으면 SELECT와 FROM이 없어 값을 돌려주는 하위 질의가 되지 않으므로 문법 오류다."},{"verdict":"오답","why":"FROM 뒤에는 테이블 이름이 와야 하는데 속성인 '이름'을 썼고, WHERE 뒤에 테이블인 '직원'을 조건 속성처럼 썼으므로 틀렸다."},{"verdict":"오답","why":"괄호 안에 WHERE 절만 있고, '직원'은 테이블이므로 조건 속성으로 쓸 수 없어 틀렸다."},{"verdict":"정답","why":"괄호 안에 SELECT 팀코드 FROM 직원 WHERE 이름 = '정도일'을 넣으면 안쪽 질의가 정도일의 팀코드를 돌려주고, 바깥 질의가 그 팀코드와 같은 직원들의 이름을 출력한다."}],"keywords":[{"term":"하위 질의(Subquery)","desc":"SQL 문 안에 포함된 SELECT 문, 괄호로 감싸며 먼저 실행됨"},{"term":"FROM 절","desc":"조회할 테이블을 지정"},{"term":"WHERE 절","desc":"조건에 맞는 행을 거르는 절"}],"memo":"하위 질의도 SELECT ~ FROM 테이블 ~ WHERE 속성 조건의 완전한 형태여야 한다. FROM 뒤에는 테이블, WHERE 뒤에는 속성이 온다."}},{"id":"written-2022-2-58","no":58,"unit":"데이터베이스 구축","q":"무결성 제약조건 중 개체 무결성 제약조건에 대한 설명으로 옳은 것은?","choices":["릴레이션 내의 튜플들이 각 속성의 도메인에 정해진 값만을 가져야 한다.","기본키는 NULL 값을 가져서는 안되며 릴레이션 내에 오직 하나의 값만 존재해야 한다.","자식 릴레이션의 외래키는 부모 릴레이션의 기본키와 도메인이 동일해야 한다.","자식 릴레이션의 값이 변경될 때 부모 릴레이션의 제약을 받는다."],"ans":2,"rate":69,"wiki":[{"title":"데이터베이스 무결성","url":"https://itwiki.kr/w/데이터베이스 무결성"}],"exp":{"concept":"무결성 제약 조건은 데이터베이스에 잘못된 데이터가 들어가지 않도록 하는 규칙이다. 개체 무결성은 기본키가 NULL이거나 중복되면 안 된다는 규칙이고, 참조 무결성은 외래키가 참조하는 테이블의 기본키에 실제로 있는 값이거나 NULL이어야 한다는 규칙이며, 도메인 무결성은 속성 값이 정해진 도메인 안에 있어야 한다는 규칙이다.","choices":[{"verdict":"오답","why":"튜플들이 각 속성의 도메인에 정해진 값만 가져야 한다는 것은 도메인 무결성에 대한 설명이다."},{"verdict":"정답","why":"기본키는 NULL 값을 가질 수 없고 릴레이션 안에서 오직 하나의 값만 존재해야(중복 불가) 한다는 것이 개체 무결성 제약 조건이다."},{"verdict":"오답","why":"자식 릴레이션의 외래키와 부모 릴레이션의 기본키 사이의 관계에 관한 설명으로, 개체 무결성이 아니라 참조 무결성과 관련된 내용이다."},{"verdict":"오답","why":"자식 릴레이션의 값이 바뀔 때 부모 릴레이션의 제약을 받는다는 것은 참조 무결성에 대한 설명이다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL·중복 불가"},{"term":"참조 무결성","desc":"외래키 값은 NULL이거나 참조하는 릴레이션의 기본키 값이어야 함"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인에 속해야 함"}],"memo":"'기본키 + NULL 불가'는 개체, '외래키'가 나오면 참조, '도메인'이 나오면 도메인 무결성이다."}},{"id":"written-2022-2-59","no":59,"unit":"데이터베이스 구축","q":"관계 데이터 모델에서 릴레이션(Relation)에 포함되어 있는 튜플(Tuple)의 수를 무엇이라고 하는가?","choices":["Degree","Cardinality","Attribute","Cartesian product"],"ans":2,"rate":71,"exp":{"concept":"릴레이션(테이블)에서 행 하나를 튜플, 열 하나를 속성이라고 한다. 튜플의 개수를 카디널리티(Cardinality, 기수), 속성의 개수를 디그리(Degree, 차수)라고 한다. 학생 30명, 항목 5개인 명단이라면 카디널리티는 30, 디그리는 5다.","choices":[{"verdict":"오답","why":"Degree(차수)는 릴레이션을 구성하는 속성(열)의 개수다."},{"verdict":"정답","why":"Cardinality(기수)는 릴레이션에 포함된 튜플(행)의 개수다."},{"verdict":"오답","why":"Attribute(속성)는 릴레이션의 열 하나, 즉 데이터의 가장 작은 논리적 단위를 말하며 개수를 뜻하는 용어가 아니다."},{"verdict":"오답","why":"Cartesian product(교차곱)는 두 릴레이션의 모든 튜플을 서로 짝지어 결합하는 연산이다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행"},{"term":"속성(Attribute)","desc":"릴레이션의 열"},{"term":"카디널리티(Cardinality)","desc":"튜플의 수"},{"term":"디그리(Degree)","desc":"속성의 수"}],"memo":"튜플 수는 카디널리티(기수), 속성 수는 디그리(차수)다. '기수는 행 개수, 차수는 열 개수'로 짝지어 외운다."}},{"id":"written-2022-2-60","no":60,"unit":"데이터베이스 구축","q":"사용자 'PARK'에게 테이블을 생성할 수 있는 권한을 부여하기 위한 SQL문의 구성으로 빈칸에 적합한 내용은?\n<img src=\"data/img/eip_written_20220424_060.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["CREATE TABLE TO","CREATE TO","CREATE FROM","CREATE TABLE FROM"],"ans":1,"rate":74,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"DDL","url":"https://itwiki.kr/w/DDL"}],"exp":{"concept":"GRANT 문은 사용자에게 권한을 부여하는 DCL 명령으로, 형식은 GRANT 권한 TO 사용자다. 반대로 권한을 회수하는 REVOKE 문은 REVOKE 권한 FROM 사용자 형식을 쓴다. 테이블을 생성할 수 있는 권한의 이름은 CREATE TABLE이다.","choices":[{"verdict":"정답","why":"GRANT CREATE TABLE TO PARK;은 사용자 PARK에게 테이블 생성 권한(CREATE TABLE)을 부여하는 올바른 문장이다."},{"verdict":"오답","why":"권한 이름이 CREATE TABLE이어야 하므로 CREATE만으로는 테이블 생성 권한을 지정할 수 없다."},{"verdict":"오답","why":"권한 이름이 불완전하고, FROM은 권한을 회수하는 REVOKE 문에서 쓰는 키워드다."},{"verdict":"오답","why":"권한 이름은 맞지만 GRANT 문은 TO를 써야 한다. FROM은 REVOKE 문에서 쓴다."}],"keywords":[{"term":"GRANT 권한 TO 사용자","desc":"권한 부여"},{"term":"REVOKE 권한 FROM 사용자","desc":"권한 회수"},{"term":"WITH GRANT OPTION","desc":"부여받은 권한을 다른 사용자에게 다시 부여할 수 있게 하는 옵션"}],"memo":"'주는 건 TO, 빼앗는 건 FROM'. GRANT는 TO, REVOKE는 FROM이다."}},{"id":"written-2022-2-61","no":61,"unit":"프로그래밍 언어 활용","q":"C언어에서 문자열 처리 함수의 서식과 그 기능의 연결로 틀린 것은?","choices":["strlen(s) - s의 길이를 구한다.","strcpy(s1, s2) - s2를 s1으로 복사한다.","strcmp(s1, s2) - s1과 s2를 연결한다.","strrev(s)－s를 거꾸로 변환한다."],"ans":3,"rate":75,"exp":{"concept":"C 언어의 문자열 처리 함수는 string.h 헤더에 선언되어 있다. strlen은 길이, strcpy는 복사, strcat은 연결, strcmp는 비교를 한다. 함수 이름이 영어 단어의 줄임말이라 뜻을 풀면 외우기 쉽다(len=length, cpy=copy, cat=concatenate, cmp=compare).","choices":[{"verdict":"오답","why":"strlen(s)는 문자열 s의 길이(널 문자 제외)를 구하므로 옳다."},{"verdict":"오답","why":"strcpy(s1, s2)는 문자열 s2를 s1으로 복사하므로 옳다."},{"verdict":"정답","why":"strcmp(s1, s2)는 두 문자열을 비교해 같으면 0, s1이 사전 순으로 앞서면 음수, 뒤면 양수를 돌려준다. s1과 s2를 연결하는 함수는 strcat(s1, s2)다."},{"verdict":"오답","why":"strrev(s)는 문자열 s를 거꾸로 뒤집는 함수로, 표준 C 라이브러리 함수는 아니지만 일부 컴파일러가 제공하며 설명 자체는 옳다."}],"keywords":[{"term":"strlen","desc":"문자열 길이 반환"},{"term":"strcpy","desc":"문자열 복사"},{"term":"strcat","desc":"문자열 연결(concatenate)"},{"term":"strcmp","desc":"두 문자열 비교, 같으면 0"}],"memo":"cmp는 compare(비교), cat은 concatenate(연결)다. 이름 뒷부분으로 기능을 구별한다."}},{"id":"written-2022-2-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220424_062.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["０","２","５","14"],"ans":2,"rate":72,"exp":{"concept":"C 언어에서 논리 연산자 &&(AND), ||(OR), !(NOT)는 결과를 참이면 1, 거짓이면 0으로 돌려준다. 0이 아닌 값은 모두 참으로 본다. 그래서 5, 3, 12처럼 0이 아닌 수는 모두 참으로 취급된다.","choices":[{"verdict":"오답","why":"t1, t2가 모두 1이므로 합은 최소 2이며 0이 나올 수 없다."},{"verdict":"정답","why":"t1 = a && b = 5 && 3: 둘 다 0이 아니므로 참, t1 = 1. t2 = a || b = 5 || 3: 참, t2 = 1. t3 = !c = !12: 12는 참이므로 그 부정은 거짓, t3 = 0. 따라서 t1 + t2 + t3 = 1 + 1 + 0 = 2가 출력된다."},{"verdict":"오답","why":"논리 연산 결과는 항상 0 또는 1이므로 세 값을 더해도 최대 3이다. 5는 나올 수 없다."},{"verdict":"오답","why":"논리 연산 결과는 0 또는 1이므로 세 값의 합은 최대 3이다. 14는 나올 수 없다."}],"keywords":[{"term":"&&","desc":"두 피연산자가 모두 참이면 1, 아니면 0"},{"term":"||","desc":"하나라도 참이면 1, 둘 다 거짓이면 0"},{"term":"!","desc":"참이면 0, 거짓이면 1로 뒤집음"},{"term":"C의 참 거짓","desc":"0은 거짓, 0이 아닌 모든 값은 참"}],"memo":"논리 연산의 결과는 무조건 0 아니면 1이다. !(0이 아닌 수)는 0이다."}},{"id":"written-2022-2-63","no":63,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220424_063.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["30","60","80","120"],"ans":2,"rate":67,"exp":{"concept":"구조체(struct)는 여러 변수를 하나로 묶은 자료형이며, 구조체 변수.멤버 형식으로 각 멤버에 접근한다. 이 프로그램은 두 구조체 변수 ob1, ob2의 배열 c를 채운 뒤, 짝수 번째 칸(i = 0, 2, 4, 6, 8)만 골라 a에 더한다.","choices":[{"verdict":"오답","why":"짝수 인덱스만 더하면 ob1.a = 20, ob2.a = 40이므로 합은 60이다. 30은 이 값과 다르다."},{"verdict":"정답","why":"첫 번째 반복에서 ob1.c[i] = i, ob2.c[i] = i + i = 2i가 된다. 두 번째 반복은 i = 0, 2, 4, 6, 8만 돌며, ob1.a = 0+2+4+6+8 = 20, ob2.a = 0+4+8+12+16 = 40이 된다. 따라서 ob1.a + ob2.a = 60이 출력된다."},{"verdict":"오답","why":"80은 실제 합 20 + 40 = 60과 다르다."},{"verdict":"오답","why":"120은 실제 합 60의 두 배로, 결과와 다르다. 두 번째 반복은 i = 0, 2, 4, 6, 8의 5번만 실행된다."}],"keywords":[{"term":"구조체(struct)","desc":"서로 다른 자료형의 변수들을 하나로 묶은 사용자 정의 자료형"},{"term":"멤버 접근 연산자 .","desc":"구조체 변수의 멤버에 접근"},{"term":"i = i + 2","desc":"반복 변수를 2씩 증가시켜 짝수 인덱스만 방문"}],"memo":"두 번째 for 문의 증감식이 i++가 아니라 i = i + 2인지 반드시 확인한다. 방문하는 인덱스를 먼저 적어 두면 실수가 줄어든다."}},{"id":"written-2022-2-64","no":64,"unit":"프로그래밍 언어 활용","q":"IP 프로토콜에서 사용하는 필드와 해당 필드에 대한 설명으로 틀린 것은?","choices":["Header Length는 IP 프로토콜의 헤더 길이를 32비트 워드 단위로 표시한다.","Packet Length는 IP 헤더를 제외한 패킷 전체의 길이를 나타내며 최대 크기는 2<sup>32</sup>－1비트이다.","Time To Live는 송신 호스트가 패킷을 전송하기 전 네트워크에서 생존할 수 있는 시간을 지정한 것이다.","Version Number는 IP 프로토콜의 버전번호를 나타낸다."],"ans":2,"rate":61,"wiki":[{"title":"인터넷 프로토콜","url":"https://itwiki.kr/w/인터넷 프로토콜"},{"title":"IP 데이터그램","url":"https://itwiki.kr/w/IP 데이터그램"}],"exp":{"concept":"IP 패킷의 헤더에는 여러 필드가 있다. Version은 IP 버전(4 또는 6), Header Length(IHL)는 헤더 길이를 32비트(4바이트) 단위로, Total Length(전체 길이)는 헤더와 데이터를 포함한 패킷 전체 길이를 바이트 단위로, TTL은 패킷이 네트워크에서 살아 있을 수 있는 한계를 나타낸다.","choices":[{"verdict":"오답","why":"Header Length는 IP 헤더의 길이를 32비트 워드 단위로 표시하므로 옳다. 예를 들어 값이 5면 5 × 4 = 20바이트다."},{"verdict":"정답","why":"패킷 전체 길이 필드(Total Length)는 IP 헤더를 포함한 패킷 전체의 길이를 바이트 단위로 나타내며, 16비트 필드라 최대 2^16 - 1 = 65,535바이트다. 헤더를 제외한다는 점과 최대 크기 2^32 - 1비트라는 점 모두 틀렸다."},{"verdict":"오답","why":"Time To Live는 송신 호스트가 패킷을 보내기 전에 네트워크에서 생존할 수 있는 한계를 지정한 값으로, 라우터를 지날 때마다 1씩 줄어 0이 되면 패킷이 폐기되므로 옳다."},{"verdict":"오답","why":"Version Number는 IP 프로토콜의 버전 번호(IPv4는 4)를 나타내므로 옳다."}],"keywords":[{"term":"Header Length(IHL)","desc":"헤더 길이, 32비트 워드 단위"},{"term":"Total Length","desc":"헤더 포함 패킷 전체 길이, 16비트, 최대 65,535바이트"},{"term":"TTL(Time To Live)","desc":"라우터를 지날 때마다 1씩 감소, 0이 되면 폐기"},{"term":"Header Checksum","desc":"IP 헤더만을 대상으로 하는 오류 검사 값"}],"memo":"IP 패킷 최대 크기는 65,535바이트(2^16 - 1)다. '2^32', '헤더 제외'가 보이면 틀린 보기다."}},{"id":"written-2022-2-65","no":65,"unit":"프로그래밍 언어 활용","q":"다음 Python 프로그램의 실행 결과가 [실행결과]와 같을 때, 빈칸에 적합한 것은?\n<img src=\"data/img/eip_written_20220424_065.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["either","elif","else if","else"],"ans":2,"rate":70,"exp":{"concept":"파이썬의 조건문은 if, elif, else로 이루어진다. 첫 조건은 if, 그다음 추가 조건은 elif(else if의 줄임), 나머지 모든 경우는 조건 없이 else로 쓴다. 각 줄 끝에는 콜론(:)이 붙고, 실행할 문장은 들여쓰기로 구분한다.","choices":[{"verdict":"오답","why":"either는 파이썬의 키워드가 아니므로 문법 오류가 난다."},{"verdict":"정답","why":"빈칸에 elif를 넣으면 x == 10은 거짓이라 건너뛰고, elif x == 20이 참이므로 print('20')이 실행되어 [실행결과]처럼 20이 출력된다."},{"verdict":"오답","why":"파이썬에서 else 뒤에는 바로 콜론이 와야 하므로 else if x == 20:은 문법 오류다. C나 자바의 else if와 혼동하기 쉬운 보기다."},{"verdict":"오답","why":"else는 조건식을 가질 수 없으므로 else x == 20:은 문법 오류다."}],"keywords":[{"term":"if","desc":"첫 번째 조건 검사"},{"term":"elif","desc":"앞 조건이 거짓일 때 추가 조건 검사"},{"term":"else","desc":"위 조건이 모두 거짓일 때 실행, 조건식 없음"}],"memo":"C·자바는 else if, 파이썬은 elif다. 언어별 문법 차이를 비교하는 문제가 자주 나온다."}},{"id":"written-2022-2-66","no":66,"unit":"프로그래밍 언어 활용","q":"RIP 라우팅 프로토콜에 대한 설명으로 틀린 것은?","choices":["경로 선택 메트릭은 홉 카운트(hop count)이다.","라우팅 프로토콜을 IGP와 EGP로 분류했을 때 EGP에 해당한다.","최단 경로 탐색에 Bellman-Ford 알고리즘을 사용한다.","각 라우터는 이웃 라우터들로부터 수신한 정보를 이용하여 라우팅 표를 갱신한다."],"ans":2,"rate":62,"wiki":[{"title":"RIP","url":"https://itwiki.kr/w/RIP"}],"exp":{"concept":"라우팅 프로토콜은 하나의 기관 내부(자율 시스템, AS 안)에서 쓰는 IGP와, 서로 다른 자율 시스템 사이에서 쓰는 EGP로 나뉜다. RIP(Routing Information Protocol)는 대표적인 IGP로, 거리 벡터 방식이며 거쳐 가는 라우터 수(홉 수)가 가장 적은 경로를 고르고 최대 홉 수는 15다.","choices":[{"verdict":"오답","why":"RIP는 경로를 고를 때 거쳐 가는 라우터 수인 홉 카운트를 메트릭으로 사용하므로 옳다."},{"verdict":"정답","why":"RIP는 하나의 자율 시스템 내부에서 사용하는 IGP(Interior Gateway Protocol)에 해당한다. EGP에 해당하는 대표 프로토콜은 BGP다."},{"verdict":"오답","why":"RIP는 거리 벡터 라우팅 프로토콜로, 최단 경로 탐색에 벨만-포드(Bellman-Ford) 알고리즘을 사용하므로 옳다."},{"verdict":"오답","why":"RIP의 각 라우터는 이웃 라우터들과 주기적으로 라우팅 정보를 주고받아 라우팅 표를 갱신하므로 옳다."}],"keywords":[{"term":"RIP","desc":"거리 벡터 방식 IGP, 벨만-포드 알고리즘, 최대 홉 수 15"},{"term":"OSPF","desc":"링크 상태 방식 IGP, 다익스트라 알고리즘"},{"term":"BGP","desc":"자율 시스템 간 라우팅에 쓰는 EGP"},{"term":"IGP / EGP","desc":"자율 시스템 내부 / 자율 시스템 간 라우팅 프로토콜"}],"memo":"RIP와 OSPF는 내부(IGP), BGP는 외부(EGP)다. RIP는 벨만-포드, OSPF는 다익스트라로 짝지어 외운다."}},{"id":"written-2022-2-67","no":67,"unit":"프로그래밍 언어 활용","q":"다음에서 설명하는 프로세스 스케줄링은?\n<img src=\"data/img/eip_written_20220424_067.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["FIFO 스케줄링","RR 스케줄링","HRN 스케줄링","MQ 스케줄링"],"ans":3,"rate":74,"wiki":[{"title":"HRRN_스케줄링","url":"https://itwiki.kr/w/HRRN_스케줄링"}],"exp":{"concept":"HRN(Highest Response-ratio Next)은 SJF(최단 작업 우선)에서 실행 시간이 긴 작업이 계속 밀리는 기아 현상을 보완한 비선점 스케줄링이다. 우선순위 = (대기 시간 + 서비스 시간) / 서비스 시간으로 계산하고, 값이 클수록 먼저 실행한다. 오래 기다릴수록 분자가 커져 우선순위가 올라간다.","choices":[{"verdict":"오답","why":"FIFO(FCFS) 스케줄링은 준비 큐에 먼저 도착한 프로세스부터 처리하는 방식으로, 우선순위 계산식을 쓰지 않는다."},{"verdict":"오답","why":"RR(Round Robin) 스케줄링은 프로세스마다 같은 시간 할당량만큼 돌아가며 실행하는 선점형 방식이다."},{"verdict":"정답","why":"HRN 스케줄링은 SJF의 약점을 보완한 비선점 방식으로, (대기 시간 + 서비스 시간) / 서비스 시간으로 우선순위를 정한다."},{"verdict":"오답","why":"MQ(Multi-level Queue, 다단계 큐) 스케줄링은 프로세스를 성격에 따라 여러 우선순위 큐로 나누고 큐마다 다른 스케줄링을 적용하는 방식이다."}],"keywords":[{"term":"HRN","desc":"(대기 시간 + 서비스 시간) / 서비스 시간이 큰 것부터 실행하는 비선점 방식"},{"term":"SJF","desc":"실행 시간이 가장 짧은 작업부터 처리하는 비선점 방식"},{"term":"기아 현상(Starvation)","desc":"우선순위가 낮은 작업이 무한정 기다리는 현상"},{"term":"에이징(Aging)","desc":"오래 기다린 작업의 우선순위를 높여 기아를 막는 기법"}],"memo":"HRN 식의 분모는 서비스 시간이다. 분모를 대기 시간으로 바꾼 보기가 자주 나온다."}},{"id":"written-2022-2-68","no":68,"unit":"프로그래밍 언어 활용","q":"UNIX 운영체제에 관한 특징으로 틀린 것은?","choices":["하나 이상의 작업에 대하여 백그라운드에서 수행이 가능하다.","Multi-User는 지원하지만 Multi-Tasking은 지원하지 않는다.","트리 구조의 파일 시스템을 갖는다.","이식성이 높으며 장치 간의 호환성이 높다."],"ans":2,"rate":80,"wiki":[{"title":"유닉스","url":"https://itwiki.kr/w/유닉스"}],"exp":{"concept":"유닉스(UNIX)는 여러 사용자가 동시에 쓸 수 있고(다중 사용자, Multi-User), 여러 작업을 동시에 실행할 수 있는(다중 작업, Multi-Tasking) 운영체제다. 대부분 C 언어로 작성되어 이식성이 높고, 파일 시스템은 루트(/)에서 시작하는 계층적 트리 구조다.","choices":[{"verdict":"오답","why":"유닉스는 명령 뒤에 &를 붙이는 등의 방법으로 하나 이상의 작업을 백그라운드에서 실행할 수 있으므로 옳다."},{"verdict":"정답","why":"유닉스는 다중 사용자(Multi-User)와 다중 작업(Multi-Tasking)을 모두 지원한다. 다중 작업을 지원하지 않는다는 설명은 틀렸다."},{"verdict":"오답","why":"유닉스는 루트 디렉터리에서 시작하는 계층적 트리 구조의 파일 시스템을 가지므로 옳다."},{"verdict":"오답","why":"유닉스는 대부분 C 언어로 작성되어 이식성이 높고, 장치를 파일처럼 다루어 장치 간 호환성이 높으므로 옳다."}],"keywords":[{"term":"UNIX 특징","desc":"다중 사용자, 다중 작업, 트리 구조 파일 시스템, 높은 이식성"},{"term":"커널(Kernel)","desc":"하드웨어를 직접 관리하는 유닉스의 핵심부"},{"term":"쉘(Shell)","desc":"사용자 명령을 해석해 커널에 전달하는 명령어 해석기"}],"memo":"유닉스는 Multi-User와 Multi-Tasking을 둘 다 지원한다. '하나만 지원'이라는 보기는 틀린 것이다."}},{"id":"written-2022-2-69","no":69,"unit":"프로그래밍 언어 활용","q":"UDP 프로토콜의 특징이 아닌 것은?","choices":["비연결형 서비스를 제공한다.","단순한 헤더 구조로 오버헤드가 적다.","주로 주소를 지정하고, 경로를 설정하는 기능을 한다.","TCP와 같이 트랜스포트 계층에 존재한다."],"ans":3,"rate":53,"wiki":[{"title":"UDP","url":"https://itwiki.kr/w/UDP"}],"exp":{"concept":"UDP(User Datagram Protocol)는 전송 계층(트랜스포트 계층) 프로토콜로, 연결 설정 없이 데이터를 바로 보내는 비연결형 방식이다. 헤더가 단순해 빠르지만, 순서 보장이나 재전송 같은 신뢰성 기능은 없다. 실시간 방송이나 음성 통화처럼 빠름이 중요한 곳에 쓰인다.","choices":[{"verdict":"오답","why":"UDP는 연결 설정 없이 데이터를 보내는 비연결형 서비스를 제공하므로 UDP의 특징이다."},{"verdict":"오답","why":"UDP는 헤더 구조가 단순해(8바이트) 오버헤드가 적으므로 UDP의 특징이다."},{"verdict":"정답","why":"주소를 지정하고 경로를 설정(라우팅)하는 기능은 네트워크 계층 프로토콜인 IP의 역할이다. UDP는 전송 계층에서 프로세스 간 데이터 전달을 담당한다."},{"verdict":"오답","why":"UDP는 TCP와 같이 전송(트랜스포트) 계층에 속하므로 UDP의 특징이다."}],"keywords":[{"term":"UDP","desc":"비연결형, 비신뢰성, 헤더가 단순한 전송 계층 프로토콜"},{"term":"TCP","desc":"연결형, 신뢰성(순서 보장·재전송)을 제공하는 전송 계층 프로토콜"},{"term":"IP","desc":"주소 지정과 경로 설정을 담당하는 네트워크 계층 프로토콜"}],"memo":"주소 지정과 경로 설정은 네트워크 계층(IP)의 일이다. 전송 계층(TCP, UDP)에 붙이면 틀린 보기다."}},{"id":"written-2022-2-70","no":70,"unit":"프로그래밍 언어 활용","q":"Python 데이터 타입 중 시퀀스(Sequence) 데이터 타입에 해당하며 다양한 데이터 타입들을 주어진 순서에 따라 저장할 수 있으나 저장된 내용을 변경할 수 없는 것은?","choices":["복소수(complex) 타입","리스트(list) 타입","사전(dict) 타입","튜플(tuple) 타입"],"ans":4,"rate":59,"exp":{"concept":"파이썬의 시퀀스 자료형은 값들을 순서대로 저장하고 번호(인덱스)로 접근하는 자료형으로, 리스트, 튜플, 문자열, range 등이 있다. 리스트는 [ ]로 만들고 내용을 바꿀 수 있지만, 튜플은 ( )로 만들고 한 번 만들면 내용을 바꿀 수 없다.","choices":[{"verdict":"오답","why":"복소수(complex) 타입은 3 + 4j처럼 실수부와 허수부를 갖는 숫자 자료형으로, 시퀀스가 아니다."},{"verdict":"오답","why":"리스트(list) 타입은 순서가 있는 시퀀스지만, 저장된 내용을 추가·삭제·변경할 수 있다."},{"verdict":"오답","why":"사전(dict) 타입은 키와 값의 쌍으로 저장하는 매핑 자료형으로, 인덱스로 접근하는 시퀀스가 아니며 내용을 변경할 수 있다."},{"verdict":"정답","why":"튜플(tuple) 타입은 다양한 자료형의 값을 순서대로 저장하는 시퀀스 자료형이며, 한 번 만든 뒤에는 내용을 변경할 수 없다."}],"keywords":[{"term":"리스트(list)","desc":"[ ]로 생성, 순서 있음, 변경 가능"},{"term":"튜플(tuple)","desc":"( )로 생성, 순서 있음, 변경 불가"},{"term":"딕셔너리(dict)","desc":"{키: 값}으로 생성, 키로 접근, 변경 가능"},{"term":"세트(set)","desc":"{1, 2}처럼 중괄호에 값을 넣어 생성(빈 세트는 set()), 순서 없음, 중복 불가"}],"memo":"'순서 있음 + 변경 불가'는 튜플이다."}},{"id":"written-2022-2-71","no":71,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램이 실행되었을 때, 실행결과는?\n<img src=\"data/img/eip_written_20220424_071.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["1 2 3 4","0 1 2 3","1 2 3","0 1 2"],"ans":2,"rate":87,"exp":{"concept":"자바에서 배열은 new int[4]처럼 크기를 정해 만들고, 배열 이름.length로 그 크기를 알 수 있다. 메소드는 배열을 반환할 수 있으며, 반환된 배열의 주소를 받은 변수로 같은 배열을 사용할 수 있다. 배열의 인덱스는 0부터 시작한다.","choices":[{"verdict":"오답","why":"temp[i] = i이므로 배열에는 0부터 들어간다. 1부터 시작하는 1 2 3 4는 인덱스를 1부터 센 착각이다."},{"verdict":"정답","why":"marr()에서 크기 4인 배열 temp를 만들고 i = 0~3에 대해 temp[i] = i를 넣어 {0, 1, 2, 3}을 반환한다. main에서 iarr이 이 배열을 받고, i = 0부터 iarr.length - 1 = 3까지 iarr[i]와 공백을 출력하므로 0 1 2 3이 출력된다."},{"verdict":"오답","why":"1 2 3은 배열 크기와 시작 값을 모두 잘못 본 결과다. 배열 크기는 4이고 값은 0부터 시작한다."},{"verdict":"오답","why":"0 1 2는 반복 조건을 i < temp.length - 1로 착각한 결과다. 실제 조건은 i < 4이므로 i = 3까지 실행된다."}],"keywords":[{"term":"new int[n]","desc":"크기 n인 정수 배열 생성, 기본값 0"},{"term":"배열.length","desc":"배열의 크기(원소 개수)"},{"term":"배열 반환","desc":"메소드는 배열의 참조(주소)를 반환할 수 있음"}],"memo":"배열 크기가 4면 인덱스는 0~3이다. 반복 조건의 <와 <=를 반드시 구별한다."}},{"id":"written-2022-2-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20220424_072.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["1","2","3","4"],"ans":3,"rate":72,"exp":{"concept":"삼항 조건 연산자 '조건 ? 값1 : 값2'는 조건이 참이면 값1, 거짓이면 값2가 된다. if-else를 한 줄로 줄인 것으로, 각 단계의 변수 값을 차례로 적어 가며 따라가면 된다.","choices":[{"verdict":"오답","why":"1은 mn = a > mx ? b : a의 결과로 착각한 값이지만, mx가 1이 아니므로 그 줄은 실행되지 않는다."},{"verdict":"오답","why":"2는 mx의 값이다. 출력하는 변수는 mn이므로 답이 아니다."},{"verdict":"정답","why":"mx = a < b ? b : a에서 1 < 2가 참이므로 mx = b = 2. mx == 1이 거짓이므로 else 블록에서 mn = b < mx ? d : c를 계산한다. b < mx는 2 < 2로 거짓이므로 mn = c = 3이 출력된다."},{"verdict":"오답","why":"4는 b < mx를 2 <= 2처럼 참으로 잘못 판단해 d를 고른 값이다. 2 < 2는 거짓이므로 c가 선택된다."}],"keywords":[{"term":"삼항 조건 연산자","desc":"조건 ? 참일 때 값 : 거짓일 때 값"},{"term":"관계 연산자 <","desc":"같은 값이면 거짓(2 < 2는 false)"},{"term":"System.out.println","desc":"값을 출력하고 줄을 바꿈"}],"memo":"같은 값끼리 < 비교는 거짓이다. 삼항 연산자는 변수 값을 한 줄씩 적어 가며 계산한다."}},{"id":"written-2022-2-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 중 Myers가 구분한 응집도(Cohesion)의 정도에서 가\n장 낮은 응집도를 갖는 단계는?","choices":["순차적 응집도(Sequential Cohesion)","기능적 응집도(Functional Cohesion)","시간적 응집도(Temporal Cohesion)","우연적 응집도(Coincidental Cohesion)"],"ans":4,"rate":85,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 구성 요소들이 얼마나 밀접하게 관련되어 있는지를 나타내며, 높을수록 좋다. 강한 것부터 기능적 > 순차적 > 교환(통신)적 > 절차적 > 시간적 > 논리적 > 우연적 응집도 순이다. 우연적 응집도는 서로 아무 관계없는 요소들이 우연히 한 모듈에 모인 가장 약한 단계다.","choices":[{"verdict":"오답","why":"순차적 응집도는 한 활동의 출력이 다음 활동의 입력으로 쓰이는 요소들로 구성된 경우로, 두 번째로 강한 응집도다."},{"verdict":"오답","why":"기능적 응집도는 모듈 안의 모든 요소가 하나의 기능을 위해 수행되는 경우로, 가장 강한(좋은) 응집도다."},{"verdict":"오답","why":"시간적 응집도는 특정 시점에 함께 처리해야 하는 기능들(예: 초기화 작업)을 한 모듈에 모은 경우로, 우연적 응집도보다는 강하다."},{"verdict":"정답","why":"우연적 응집도(Coincidental Cohesion)는 모듈 안의 요소들이 서로 아무 관련 없이 모인 경우로, 가장 낮은 응집도다."}],"keywords":[{"term":"응집도 순서(강 → 약)","desc":"기능적 > 순차적 > 교환적 > 절차적 > 시간적 > 논리적 > 우연적"},{"term":"기능적 응집도","desc":"모든 요소가 단일 기능을 수행, 가장 강함"},{"term":"우연적 응집도","desc":"서로 관련 없는 요소들로 구성, 가장 약함"}],"memo":"응집도 강한 순서는 '기순교절시논우'(기능, 순차, 교환, 절차, 시간, 논리, 우연)로 외운다."}},{"id":"written-2022-2-74","no":74,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220424_074.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["0","1","2","3"],"ans":2,"rate":71,"exp":{"concept":"C 언어에서 관계 연산(<=, >, <)과 논리 연산(||, &&, !)의 결과는 참이면 1, 거짓이면 0이다. 괄호 안의 비교를 하나씩 0과 1로 바꾼 뒤 논리 연산을 하면 된다.","choices":[{"verdict":"오답","why":"r3 - r2 + r1 = 0 - 0 + 1 = 1이므로 0이 아니다. r1이 1이라는 점을 놓치면 0으로 착각할 수 있다."},{"verdict":"정답","why":"r1 = (2 <= 2) || (3 > 3) = 1 || 0 = 1. r2 = !3 = 0(3은 참이므로 부정하면 거짓). r3 = (1 > 1) && (2 < 3) = 0 && 1 = 0. 따라서 r3 - r2 + r1 = 0 - 0 + 1 = 1이 출력된다."},{"verdict":"오답","why":"2는 r3를 1로 잘못 계산한 결과다. n1 > 1은 1 > 1로 거짓이므로 r3 = 0이다."},{"verdict":"오답","why":"r1, r2, r3는 모두 0 또는 1이므로 r3 - r2 + r1의 최댓값은 1 - 0 + 1 = 2다. 3은 나올 수 없다."}],"keywords":[{"term":"관계 연산 결과","desc":"참이면 1, 거짓이면 0"},{"term":"||","desc":"하나라도 참이면 1"},{"term":"&&","desc":"모두 참이어야 1"},{"term":"!","desc":"0이 아닌 값은 0으로, 0은 1로"}],"memo":"1 > 1, 3 > 3처럼 같은 값의 > 비교는 거짓(0)이다. 경계값에서 실수하지 않도록 한다."}},{"id":"written-2022-2-75","no":75,"unit":"프로그래밍 언어 활용","q":"IP 프로토콜의 주요 특징에 해당하지 않는 것은?","choices":["체크섬(Checksum) 기능으로 데이터 체크섬(Data Checksum)만 제공한다.","패킷을 분할, 병합하는 기능을 수행하기도 한다.","비연결형 서비스를 제공한다.","Best Effort 원칙에 따른 전송 기능을 제공한다."],"ans":1,"rate":59,"wiki":[{"title":"인터넷 프로토콜","url":"https://itwiki.kr/w/인터넷 프로토콜"}],"exp":{"concept":"IP(Internet Protocol)는 네트워크 계층에서 패킷의 주소 지정과 경로 설정을 담당한다. 연결을 미리 맺지 않는 비연결형이고, 전달을 최대한 노력하되 보장하지는 않는 Best Effort 방식이다. 오류 검사는 헤더 체크섬으로 IP 헤더만 검사하고, 데이터 부분은 검사하지 않는다.","choices":[{"verdict":"정답","why":"IP의 체크섬은 헤더 체크섬(Header Checksum)으로, IP 헤더만 검사하고 데이터 부분은 검사하지 않는다. 데이터 체크섬만 제공한다는 설명은 반대다."},{"verdict":"오답","why":"IP는 패킷이 지나갈 네트워크의 최대 전송 단위(MTU)에 맞춰 패킷을 단편화(분할)하고 목적지에서 재조립(병합)하므로 옳다."},{"verdict":"오답","why":"IP는 연결 설정 없이 패킷을 보내는 비연결형 서비스를 제공하므로 옳다."},{"verdict":"오답","why":"IP는 패킷 전달을 최대한 시도하지만 도착이나 순서를 보장하지 않는 Best Effort 방식이므로 옳다."}],"keywords":[{"term":"IP","desc":"네트워크 계층의 비연결형, Best Effort 프로토콜"},{"term":"Header Checksum","desc":"IP 헤더만을 대상으로 한 오류 검사"},{"term":"단편화(Fragmentation)","desc":"MTU보다 큰 패킷을 나누어 전송하는 것"},{"term":"Best Effort","desc":"최선을 다해 전달하되 신뢰성은 보장하지 않음"}],"memo":"IP는 '헤더'만 검사한다. 데이터 오류 검사는 상위 계층(TCP, UDP)의 몫이다."}},{"id":"written-2022-2-76","no":76,"unit":"프로그래밍 언어 활용","q":"4개의 페이지를 수용할 수 있는 주기억장치가 있으며, 초기에는 모두 비어 있다고 가정한다. 다음의 순서로 페이지 참조가 발생할 때, LRU 페이지 교체 알고리즘을 사용할 경우 몇 번의 페이지 결함이 발생하는가?\n<img src=\"data/img/eip_written_20220424_076.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["5회","6회","7회","8회"],"ans":1,"rate":65,"exp":{"concept":"LRU(Least Recently Used)는 페이지 프레임이 꽉 찼을 때 가장 오랫동안 사용되지 않은 페이지를 내보내는 교체 알고리즘이다. 페이지 결함(Page Fault)은 참조하려는 페이지가 주기억장치에 없을 때 발생한다. 프레임이 비어 있는 동안 처음 들어오는 페이지도 결함으로 센다.","choices":[{"verdict":"정답","why":"프레임 4개로 1, 2, 3, 1, 2, 4, 1, 2, 5를 처리한다. 1, 2, 3은 빈 프레임에 들어가며 결함 3회. 1, 2는 적중. 4는 빈 프레임에 들어가며 결함 4회(프레임 1, 2, 3, 4). 1, 2는 적중. 5가 들어올 때 프레임이 꽉 차 있으므로 가장 오래 쓰지 않은 3을 내보내고 결함 5회. 총 5회다."},{"verdict":"오답","why":"6회는 적중(1, 2의 재참조)을 일부 결함으로 잘못 센 값이다. 실제 결함은 5회다."},{"verdict":"오답","why":"7회는 재참조된 1, 2를 다수 결함으로 센 값으로, 프레임이 4개라 1, 2는 계속 남아 있어 적중한다."},{"verdict":"오답","why":"8회는 거의 모든 참조를 결함으로 센 값이다. 같은 페이지가 프레임에 있으면 결함이 발생하지 않는다."}],"keywords":[{"term":"LRU","desc":"가장 오랫동안 사용되지 않은 페이지를 교체"},{"term":"FIFO","desc":"가장 먼저 들어온 페이지를 교체"},{"term":"LFU","desc":"사용 횟수가 가장 적은 페이지를 교체"},{"term":"페이지 결함(Page Fault)","desc":"참조한 페이지가 주기억장치에 없는 상황"}],"memo":"프레임이 비어 있을 때 처음 들어오는 페이지도 결함으로 센다. 표를 그려 참조마다 프레임 상태를 적으면 정확하다."}},{"id":"written-2022-2-77","no":77,"unit":"프로그래밍 언어 활용","q":"사용자 수준에서 지원되는 스레드(thread)가 커널에서 지원되는 스레드에 비해 가지는 장점으로 옳은 것은?","choices":["한 프로세스가 운영체제를 호출할 때 전체 프로세스가 대기할 필요가 없으므로 시스템 성능을 높일 수 있다.","동시에 여러 스레드가 커널에 접근할 수 있으므로 여러 스레드가 시스템 호출을 동시에 사용할 수 있다.","각 스레드를 개별적으로 관리할 수 있으므로 스레드의 독립적인 스케줄링이 가능하다.","커널 모드로의 전환 없이 스레드 교환이 가능하므로 오버헤드가 줄어든다."],"ans":4,"rate":50,"wiki":[{"title":"스레드","url":"https://itwiki.kr/w/스레드"}],"exp":{"concept":"스레드는 프로세스 안에서 실행되는 작은 작업 흐름이다. 사용자 수준 스레드는 커널이 모르는 상태에서 사용자 영역의 라이브러리가 관리하므로, 스레드를 바꿀 때 커널 모드로 들어갈 필요가 없어 빠르다. 대신 한 스레드가 시스템 호출로 멈추면 같은 프로세스의 다른 스레드도 함께 멈춘다. 커널 수준 스레드는 커널이 직접 관리해 그 반대의 장단점을 가진다.","choices":[{"verdict":"오답","why":"한 스레드가 운영체제를 호출해도 전체 프로세스가 대기하지 않는 것은 커널 수준 스레드의 장점이다. 사용자 수준 스레드는 한 스레드가 시스템 호출로 멈추면 프로세스 전체가 대기한다."},{"verdict":"오답","why":"여러 스레드가 동시에 커널에 접근해 시스템 호출을 동시에 사용할 수 있는 것은 커널 수준 스레드의 장점이다."},{"verdict":"오답","why":"커널이 각 스레드를 개별적으로 인식해 독립적으로 스케줄링할 수 있는 것은 커널 수준 스레드의 장점이다."},{"verdict":"정답","why":"사용자 수준 스레드는 커널 모드로 전환하지 않고 사용자 영역에서 스레드를 교환하므로 문맥 교환 오버헤드가 줄어든다. 이것이 커널 스레드에 비한 장점이다."}],"keywords":[{"term":"사용자 수준 스레드","desc":"사용자 라이브러리가 관리, 교환이 빠르지만 하나가 멈추면 전체 대기"},{"term":"커널 수준 스레드","desc":"커널이 관리, 독립 스케줄링 가능하지만 교환 오버헤드가 큼"},{"term":"문맥 교환(Context Switching)","desc":"실행 중인 작업을 바꿀 때 상태를 저장·복원하는 과정"}],"memo":"사용자 수준 스레드의 장점은 '빠름(커널 모드 전환 없음)' 하나로 기억하고, 나머지 독립성 관련 장점은 커널 스레드 쪽이다."}},{"id":"written-2022-2-78","no":78,"unit":"프로그래밍 언어 활용","q":"한 모듈이 다른 모듈의 내부 기능 및 그 내부 자료를 참조하는 경우의 결합도는?","choices":["내용 결합도(Content Coupling)","제어 결합도(Control Coupling)","공통 결합도(Common Coupling)","스탬프 결합도(Stamp Coupling)"],"ans":1,"rate":74,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"}],"exp":{"concept":"결합도(Coupling)는 모듈과 모듈 사이의 의존 정도이며, 낮을수록 좋다. 약한 것부터 자료 < 스탬프 < 제어 < 외부 < 공통 < 내용 결합도 순이다. 내용 결합도는 한 모듈이 다른 모듈의 내부 기능이나 자료를 직접 참조하는 가장 강한(나쁜) 결합도다.","choices":[{"verdict":"정답","why":"내용 결합도(Content Coupling)는 한 모듈이 다른 모듈의 내부 기능 및 내부 자료를 직접 참조하거나 수정하는 경우로, 가장 강한 결합도다."},{"verdict":"오답","why":"제어 결합도(Control Coupling)는 한 모듈이 다른 모듈의 처리 흐름을 제어하기 위해 제어 신호(플래그)를 넘기는 경우다."},{"verdict":"오답","why":"공통 결합도(Common Coupling)는 여러 모듈이 공유되는 공통 데이터 영역(전역 변수 등)을 함께 사용하는 경우다."},{"verdict":"오답","why":"스탬프 결합도(Stamp Coupling)는 모듈 간에 배열이나 레코드 같은 자료 구조를 통째로 넘기는 경우다."}],"keywords":[{"term":"결합도 순서(약 → 강)","desc":"자료 < 스탬프 < 제어 < 외부 < 공통 < 내용"},{"term":"자료 결합도","desc":"필요한 데이터 값만 매개변수로 주고받음, 가장 바람직"},{"term":"내용 결합도","desc":"다른 모듈의 내부를 직접 참조, 가장 나쁨"}],"memo":"결합도 약한 순서는 '자스제외공내'(자료, 스탬프, 제어, 외부, 공통, 내용)다. '내부를 참조'하면 내용 결합도다."}},{"id":"written-2022-2-79","no":79,"unit":"프로그래밍 언어 활용","q":"a[0]의 주소값이 10일 경우 다음 C언어 프로그램이 실행되었을 때의 결과는? (단, int 형의 크기는 4Byte로 가정한다.)\n<img src=\"data/img/eip_written_20220424_079.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["14, 10","14, 14","18, 10","18, 14"],"ans":3,"rate":66,"exp":{"concept":"배열 이름은 배열의 첫 번째 원소의 주소와 같다. &a[i]는 i번째 원소의 주소이고, a[0]의 주소에 i × (원소 크기)를 더한 값이다. int가 4바이트이면 a[1]은 시작 주소 + 4, a[2]는 시작 주소 + 8이다.","choices":[{"verdict":"오답","why":"14는 &a[2]를 a[0] 주소 + 2 × 2처럼 잘못 계산하거나 a[0]의 값 14와 혼동한 결과다. &a[2]는 10 + 8 = 18이다."},{"verdict":"오답","why":"14, 14는 주소와 배열 원소 값을 혼동한 결과다. 출력하는 것은 값이 아니라 주소다."},{"verdict":"정답","why":"&a[2]는 a[0]의 주소 10에서 int 2개(2 × 4 = 8바이트)만큼 떨어져 있으므로 18이다. a는 배열 이름이므로 첫 원소의 주소 10이다. 따라서 18, 10이 출력된다."},{"verdict":"오답","why":"a는 배열의 시작 주소인 10이므로, 두 번째 값이 14가 될 수 없다."}],"keywords":[{"term":"배열 이름","desc":"배열 첫 원소의 주소와 같음(a == &a[0])"},{"term":"&a[i]","desc":"a[0]의 주소 + i × 원소 크기"},{"term":"포인터 연산","desc":"주소에 1을 더하면 자료형 크기만큼 이동"}],"memo":"주소 계산은 '시작 주소 + 인덱스 × 자료형 크기'다. 배열 이름 단독은 시작 주소다."}},{"id":"written-2022-2-80","no":80,"unit":"프로그래밍 언어 활용","q":"모듈화(Modularity)와 관련한 설명으로 틀린 것은?","choices":["시스템을 모듈로 분할하면 각각의 모듈을 별개로 만들고 수정할 수 있기 때문에 좋은 구조가 된다.","응집도는 모듈과 모듈 사이의 상호의존 또는 연관 정도를 의미한다.","모듈 간의 결합도가 약해야 독립적인 모듈이 될 수 있다.","모듈 내 구성 요소들 간의 응집도가 강해야 좋은 모듈 설계이다."],"ans":2,"rate":60,"wiki":[{"title":"소프트웨어_모듈화","url":"https://itwiki.kr/w/소프트웨어_모듈화"}],"exp":{"concept":"모듈화는 큰 시스템을 기능 단위의 작은 모듈로 나누는 것이다. 좋은 모듈은 내부 요소끼리는 서로 밀접하고(응집도 높음), 다른 모듈과는 느슨하게 연결되어(결합도 낮음) 독립적이다. 응집도는 모듈 '안', 결합도는 모듈 '사이'의 관계다.","choices":[{"verdict":"오답","why":"시스템을 모듈로 나누면 각 모듈을 따로 만들고 수정할 수 있어 좋은 구조가 되므로 옳다."},{"verdict":"정답","why":"모듈과 모듈 사이의 상호 의존 또는 연관 정도는 결합도(Coupling)다. 응집도(Cohesion)는 한 모듈 내부의 구성 요소들이 서로 관련된 정도를 뜻한다."},{"verdict":"오답","why":"모듈 간 결합도가 약해야 다른 모듈의 영향을 덜 받는 독립적인 모듈이 되므로 옳다."},{"verdict":"오답","why":"모듈 내부 구성 요소들 간의 응집도가 강해야 좋은 모듈 설계이므로 옳다."}],"keywords":[{"term":"응집도(Cohesion)","desc":"모듈 내부 요소들 간의 관련 정도, 강할수록 좋음"},{"term":"결합도(Coupling)","desc":"모듈과 모듈 사이의 의존 정도, 약할수록 좋음"},{"term":"모듈화","desc":"시스템을 기능 단위 모듈로 분해하는 것"}],"memo":"'응집도는 안, 결합도는 사이'. 좋은 설계는 응집도는 높게, 결합도는 낮게다."}},{"id":"written-2022-2-81","no":81,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발에서 정보보안 3요소에 해당 하지 않는 설명은?","choices":["기밀성 : 인가된 사용자에 대해서만 자원 접근이 가능하다.","무결성 : 인가된 사용자에 대해서만 자원 수정이 가능하며 전송중인 정보는 수정되지 않는다.","가용성 : 인가된 사용자는 가지고 있는 권한 범위 내에서 언제든 자원 접근이 가능하다.","휘발성 : 인가된 사용자가 수행한 데이터는 처리 완료 즉시 폐기 되어야 한다."],"ans":4,"rate":81,"wiki":[{"title":"보안","url":"https://itwiki.kr/w/보안"}],"exp":{"concept":"정보 보안의 3요소는 기밀성(Confidentiality), 무결성(Integrity), 가용성(Availability)으로, 영어 앞 글자를 따 CIA라고 부른다. 기밀성은 허락된 사람만 볼 수 있게, 무결성은 허락된 사람만 고칠 수 있게, 가용성은 허락된 사람이 필요할 때 언제든 쓸 수 있게 하는 것이다.","choices":[{"verdict":"오답","why":"기밀성은 인가된 사용자에게만 자원 접근을 허용하는 것이므로 보안 3요소에 해당한다."},{"verdict":"오답","why":"무결성은 인가된 사용자만 자원을 수정할 수 있고 전송 중인 정보가 변조되지 않게 하는 것이므로 보안 3요소에 해당한다."},{"verdict":"오답","why":"가용성은 인가된 사용자가 권한 범위 안에서 언제든 자원에 접근할 수 있게 하는 것이므로 보안 3요소에 해당한다."},{"verdict":"정답","why":"휘발성은 정보 보안 3요소에 해당하지 않는다. 보안 3요소는 기밀성, 무결성, 가용성뿐이다."}],"keywords":[{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 정보에 접근"},{"term":"무결성(Integrity)","desc":"인가된 사용자만 정보를 수정, 변조 방지"},{"term":"가용성(Availability)","desc":"인가된 사용자가 필요할 때 언제든 사용"},{"term":"인증(Authentication)","desc":"사용자가 누구인지 확인하는 보안 기능"}],"memo":"보안 3요소는 CIA(Confidentiality, Integrity, Availability)다."}},{"id":"written-2022-2-82","no":82,"unit":"정보시스템 구축 관리","q":"어떤 외부 컴퓨터가 접속되면 접속 인가 여부를 점검해서 인가된 경우에는 접속이 허용되고, 그 반대의 경우에는 거부할 수 있는 접근제어 유틸리티는?","choices":["tcp wrapper","trace checker","token finder","change detector"],"ans":1,"rate":57,"wiki":[{"title":"TCP Wrapper","url":"https://itwiki.kr/w/TCP Wrapper"}],"exp":{"concept":"TCP 래퍼(TCP Wrapper)는 외부 컴퓨터가 서버에 접속하려 할 때, 미리 정한 규칙에 따라 접속을 허용할지 거부할지 판단하는 접근 제어 유틸리티다. 건물 입구의 경비원이 출입 명단을 확인하고 들여보내는 것과 같다.","choices":[{"verdict":"정답","why":"tcp wrapper는 외부 컴퓨터의 접속 요청에 대해 접속 인가 여부를 점검해 허용하거나 거부하는 접근 제어 유틸리티다."},{"verdict":"오답","why":"trace checker는 출제 범위에서 접근 제어 유틸리티를 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"token finder는 출제 범위에서 접근 제어 유틸리티를 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"change detector는 출제 범위에서 접근 제어 유틸리티를 가리키는 표준 용어가 아니다."}],"keywords":[{"term":"TCP Wrapper","desc":"접속 요청의 허용·거부를 판단하는 접근 제어 유틸리티"},{"term":"접근 제어","desc":"인가된 사용자만 자원에 접근하도록 통제하는 것"},{"term":"방화벽(Firewall)","desc":"내부 네트워크와 외부 네트워크 사이의 트래픽을 통제하는 시스템"}],"memo":"'접속 인가 여부 점검 → 허용/거부'는 TCP 래퍼다. 서비스를 감싸(wrap) 앞에서 검문한다고 생각한다."}},{"id":"written-2022-2-83","no":83,"unit":"정보시스템 구축 관리","q":"기기를 키오스크에 갖다 대면 원하는 데이터를 바로 가져올 수 있는 기술로 10㎝ 이내 근접 거리에서 기가급 속도로 데이터 전송이 가능한 초고속 근접무선통신(NFC : Near Field Communication) 기술은?","choices":["BcN(Broadband Convergence Network)","Zing","Marine Navi","C-V2X(Cellular Vehicle To Everything)"],"ans":2,"rate":62,"wiki":[{"title":"NFC","url":"https://itwiki.kr/w/NFC"}],"exp":{"concept":"징(Zing)은 기기를 키오스크 같은 단말에 가까이 대기만 하면 데이터를 빠르게 주고받는 초고속 근접 무선 통신(NFC) 기술이다. 10cm 이내의 아주 가까운 거리에서 기가비트급 속도로 전송한다는 점이 특징이다.","choices":[{"verdict":"오답","why":"BcN(Broadband Convergence Network, 광대역 통합망)은 음성, 데이터, 방송, 통신 서비스를 통합해 제공하는 차세대 통합 네트워크로, 근접 무선 통신 기술이 아니다."},{"verdict":"정답","why":"Zing은 기기를 키오스크에 갖다 대면 10cm 이내 근접 거리에서 기가급 속도로 데이터를 전송할 수 있는 초고속 근접 무선 통신 기술이다."},{"verdict":"오답","why":"Marine Navi는 출제 범위에서 초고속 근접 무선 통신 기술을 가리키는 용어가 아니다."},{"verdict":"오답","why":"C-V2X(Cellular Vehicle To Everything)는 이동통신망을 이용해 차량과 다른 차량, 인프라, 보행자 등이 정보를 주고받는 차량 통신 기술이다."}],"keywords":[{"term":"Zing","desc":"10cm 이내 기가급 속도의 초고속 근접 무선 통신 기술"},{"term":"NFC(Near Field Communication)","desc":"가까운 거리에서 무선으로 데이터를 주고받는 기술"},{"term":"C-V2X","desc":"이동통신망 기반 차량-사물 간 통신 기술"},{"term":"BcN","desc":"음성·데이터·방송을 통합한 광대역 통합망"}],"memo":"'키오스크에 갖다 대면', '10cm', '기가급'이 함께 나오면 Zing이다."}},{"id":"written-2022-2-84","no":84,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위한 응용 프로그램의 보안 설정과 가장 거리가 먼 것은?","choices":["서버 관리실 출입 통제","실행 프로세스 권한 설정","운영체제의 접근 제한","운영체제의 정보 수집 제한"],"ans":1,"rate":75,"exp":{"concept":"응용 프로그램의 보안 설정은 소프트웨어와 운영체제 수준에서 취약점을 줄이는 조치다. 실행 프로세스의 권한을 최소로 제한하고, 운영체제에 대한 접근과 정보 수집을 제한하는 것 등이 이에 해당한다. 사람이 서버실에 드나드는 것을 막는 것은 물리적 보안이다.","choices":[{"verdict":"정답","why":"서버 관리실 출입 통제는 사람의 출입을 막는 물리적 보안 조치로, 응용 프로그램의 보안 설정과는 거리가 멀다."},{"verdict":"오답","why":"실행 프로세스의 권한을 필요한 만큼만 부여하도록 설정하는 것은 응용 프로그램의 보안 설정에 해당한다."},{"verdict":"오답","why":"응용 프로그램이 운영체제에 접근하는 범위를 제한하는 것은 응용 프로그램의 보안 설정에 해당한다."},{"verdict":"오답","why":"응용 프로그램이 운영체제의 정보를 수집하는 것을 제한하는 것은 응용 프로그램의 보안 설정에 해당한다."}],"keywords":[{"term":"물리적 보안","desc":"출입 통제, CCTV, 잠금 장치 등 물리적 접근 차단"},{"term":"최소 권한의 원칙","desc":"프로세스와 사용자에게 꼭 필요한 권한만 부여"},{"term":"취약점 관리","desc":"시스템의 보안 약점을 찾아 점검하고 보완하는 활동"}],"memo":"'출입', '관리실'처럼 공간에 관한 말이 나오면 물리적 보안이지 응용 프로그램 설정이 아니다."}},{"id":"written-2022-2-85","no":85,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크와 관련한 설명으로 가장 적절하지 않은 것은?","choices":["반제품 상태의 제품을 토대로 도메인별로 필요한 서비스 컴포넌트를 사용하여 재사용성 확대와 성능을 보장 받을 수 있게 하는 개발 소프트웨어이다.","라이브러리와는 달리 사용자 코드에서 프레임워크를 호출해서 사용하고, 그에 대한 제어도 사용자 코드가 가지는 방식이다.","설계 관점에 개발 방식을 패턴화시키기 위한 노력의 결과물인 소프트웨어 디자인 패턴을 반제품 소프트웨어 상태로 집적화시킨 것으로 볼 수 있다.","프레임워크의 동작 원리를 그 제어 흐름의 일반적인 프로그램 흐름과 반대로 동작한다고 해서 IoC(Inversion of Control)이라고 설명하기도 한다."],"ans":2,"rate":62,"wiki":[{"title":"소프트웨어 개발 프레임워크","url":"https://itwiki.kr/w/소프트웨어 개발 프레임워크"}],"exp":{"concept":"소프트웨어 개발 프레임워크는 자주 쓰는 기능과 구조를 미리 만들어 둔 반제품 소프트웨어다. 라이브러리는 개발자 코드가 필요할 때 불러 쓰지만, 프레임워크는 프레임워크가 흐름을 쥐고 개발자의 코드를 호출한다. 제어의 흐름이 뒤바뀌었다고 해서 이를 제어의 역전(IoC, Inversion of Control)이라고 한다.","choices":[{"verdict":"오답","why":"프레임워크는 반제품 상태의 제품을 토대로 도메인별 서비스 컴포넌트를 사용해 재사용성을 높이고 일정 수준의 성능을 보장받게 하는 소프트웨어이므로 옳다."},{"verdict":"정답","why":"사용자 코드가 필요한 것을 불러 쓰고 제어도 사용자 코드가 가지는 방식은 라이브러리다. 프레임워크는 프레임워크가 사용자 코드를 호출하고 제어 흐름도 프레임워크가 가진다."},{"verdict":"오답","why":"프레임워크는 디자인 패턴을 반제품 소프트웨어 형태로 집약해 놓은 것으로 볼 수 있으므로 옳다."},{"verdict":"오답","why":"프레임워크는 일반적인 프로그램과 제어 흐름이 반대로 동작하므로 IoC(제어의 역전)라고 설명하기도 하므로 옳다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"제어 흐름을 쥐고 사용자 코드를 호출하는 반제품 소프트웨어"},{"term":"라이브러리(Library)","desc":"사용자 코드가 필요할 때 호출해 쓰는 기능 모음"},{"term":"IoC(Inversion of Control)","desc":"제어 흐름의 주도권이 프레임워크로 넘어간 구조"}],"memo":"라이브러리는 '내가 부른다', 프레임워크는 '나를 부른다'."}},{"id":"written-2022-2-86","no":86,"unit":"정보시스템 구축 관리","q":"클라우드 기반 HSM(Cloud-based Hardware Security Module)에 대한 설명으로 틀린 것은?","choices":["클라우드(데이터센터) 기반 암호화 키 생성, 처리, 저장 등을 하는 보안 기기이다.","국내에서는 공인인증제의 폐지와 전자서명법 개정을 추진하면서 클라우드 HSM 용어가 자주 등장하였다.","클라우드에 인증서를 저장하므로 기존 HSM 기기나 휴대폰에 인증서를 저장해 다닐 필요가 없다.","하드웨어가 아닌 소프트웨어적으로만 구현되기 때문에 소프트웨어식 암호 기술에 내재된 보안 취약점을 해결할 수 없다는 것이 주요 단점이다."],"ans":4,"rate":76,"wiki":[{"title":"HSM","url":"https://itwiki.kr/w/HSM"}],"exp":{"concept":"HSM(Hardware Security Module)은 암호화 키를 안전하게 생성·보관·처리하는 전용 하드웨어 보안 장치다. 클라우드 기반 HSM은 이 장치를 클라우드(데이터센터)에 두고 서비스로 제공하는 것이다. 하드웨어로 구현되어 있어, 소프트웨어 방식 암호 기술에 있는 보안 취약점을 해결할 수 있다는 것이 장점이다.","choices":[{"verdict":"오답","why":"클라우드 HSM은 클라우드(데이터센터)에서 암호화 키의 생성, 처리, 저장 등을 수행하는 보안 기기이므로 옳다."},{"verdict":"오답","why":"국내에서 공인인증제 폐지와 전자서명법 개정이 추진되면서 클라우드 HSM이라는 용어가 자주 등장했으므로 옳다."},{"verdict":"오답","why":"인증서를 클라우드에 저장하므로 HSM 기기나 휴대폰에 인증서를 저장해 다닐 필요가 없다는 설명은 옳다."},{"verdict":"정답","why":"클라우드 HSM은 하드웨어 보안 모듈이므로 하드웨어적으로 구현된다. 그 덕분에 소프트웨어식 암호 기술에 내재된 보안 취약점을 해결할 수 있다는 것이 장점이며, 소프트웨어로만 구현된다는 설명은 틀렸다."}],"keywords":[{"term":"HSM(Hardware Security Module)","desc":"암호화 키를 안전하게 생성·저장·처리하는 하드웨어 장치"},{"term":"클라우드 HSM","desc":"클라우드 데이터센터 기반으로 제공되는 HSM"},{"term":"전자서명법","desc":"전자서명의 효력과 이용에 관한 법률, 개정으로 공인인증서의 독점적 지위가 폐지됨"}],"memo":"HSM의 H는 Hardware다. '소프트웨어적으로만 구현'은 이름부터 맞지 않는다."}},{"id":"written-2022-2-87","no":87,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 기술로 가장 적절한 것은?\n<img src=\"data/img/eip_written_20220424_087.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Virtual Local Area Network","Simple Station Network","Mesh Network","Modem Network"],"ans":3,"rate":77,"wiki":[{"title":"네트워크 토폴로지","url":"https://itwiki.kr/w/네트워크 토폴로지"}],"exp":{"concept":"메시 네트워크(Mesh Network)는 그물(mesh)처럼 여러 노드가 서로 직접 연결되어, 중계 장치를 거치지 않고도 데이터를 주고받는 네트워크다. 한 경로가 끊겨도 다른 경로로 전달할 수 있어 안정적이므로, 대용량 데이터를 빠르게 전달해야 하는 행사장이나 군 등에서 많이 쓴다.","choices":[{"verdict":"오답","why":"VLAN(Virtual Local Area Network)은 물리적 위치와 관계없이 스위치에서 논리적으로 LAN을 나누는 기술로, 그물 모양의 직접 연결 네트워크가 아니다."},{"verdict":"오답","why":"Simple Station Network는 출제 범위에서 네트워크 형태를 가리키는 표준 용어가 아니다."},{"verdict":"정답","why":"Mesh Network는 다른 국을 향하는 호출이 중계 없이 직접 접속되는 그물 모양 네트워크로, 대용량을 빠르고 안전하게 전달할 수 있어 행사장이나 군 등에서 쓰인다."},{"verdict":"오답","why":"Modem Network는 출제 범위에서 이런 형태의 네트워크를 가리키는 표준 용어가 아니다. 모뎀은 디지털 신호와 아날로그 신호를 서로 바꾸는 장치다."}],"keywords":[{"term":"메시 네트워크(Mesh Network)","desc":"노드들이 그물처럼 서로 직접 연결된 네트워크"},{"term":"망형(Mesh) 토폴로지","desc":"모든 노드를 서로 연결, n개 노드면 n(n-1)/2개 회선 필요"},{"term":"VLAN","desc":"물리적 배치와 상관없이 논리적으로 LAN을 분리하는 기술"}],"memo":"'그물 모양', '중계 없이 직접', '행사장·군'이 나오면 메시 네트워크다."}},{"id":"written-2022-2-88","no":88,"unit":"정보시스템 구축 관리","q":"물리적 위협으로 인한 문제에 해당하지 않는 것은?","choices":["화재, 홍수 등 천재지변으로 인한 위협","하드웨어 파손, 고장으로 인한 장애","방화, 테러로 인한 하드웨어와 기록장치를 물리적으로 파괴하는 행위","방화벽 설정의 잘못된 조작으로 인한 네트워크, 서버 보안 위협"],"ans":4,"rate":93,"exp":{"concept":"정보 시스템에 대한 위협은 물리적 위협과 기술적(논리적) 위협으로 나눌 수 있다. 물리적 위협은 화재, 홍수, 하드웨어 고장, 파괴 행위처럼 장비 자체에 실제로 피해를 주는 것이고, 기술적 위협은 해킹, 악성코드, 잘못된 보안 설정처럼 소프트웨어나 네트워크를 통한 것이다.","choices":[{"verdict":"오답","why":"화재, 홍수 등 천재지변은 장비를 물리적으로 손상시키는 물리적 위협이다."},{"verdict":"오답","why":"하드웨어 파손이나 고장으로 인한 장애는 물리적 위협이다."},{"verdict":"오답","why":"방화나 테러로 하드웨어와 기록 장치를 물리적으로 파괴하는 행위는 물리적 위협이다."},{"verdict":"정답","why":"방화벽 설정을 잘못 조작해 생기는 네트워크, 서버 보안 위협은 소프트웨어 설정과 관련된 기술적(논리적) 위협으로, 물리적 위협이 아니다."}],"keywords":[{"term":"물리적 위협","desc":"천재지변, 하드웨어 고장, 물리적 파괴 등"},{"term":"기술적 위협","desc":"해킹, 악성코드, 설정 오류 등"},{"term":"방화벽(Firewall)","desc":"네트워크 트래픽을 규칙에 따라 허용·차단하는 보안 시스템"}],"memo":"보기 3의 방화(放火, 불을 지름)는 장비를 직접 부수는 물리적 위협이고, 보기 4의 방화벽(Firewall)은 네트워크 보안 장치로 그 설정 실수는 기술적 위협이다. 비슷한 글자에 속지 않는다."}},{"id":"written-2022-2-89","no":89,"unit":"정보시스템 구축 관리","q":"악성코드의 유형 중 다른 컴퓨터의 취약점을 이용하여 스스로 전파하거나 메일로 전파되며 스스로를 증식하는 것은?","choices":["Worm","Rogue Ware","Adware","Reflection Attack"],"ans":1,"rate":78,"wiki":[{"title":"애드웨어","url":"https://itwiki.kr/w/애드웨어"},{"title":"멀웨어","url":"https://itwiki.kr/w/멀웨어"}],"exp":{"concept":"웜(Worm)은 다른 프로그램에 기생하지 않고 스스로를 복제해, 네트워크의 취약점이나 이메일을 통해 다른 컴퓨터로 퍼져 나가는 악성 프로그램이다. 숙주 파일이 있어야 감염되는 바이러스와 달리 혼자서도 증식한다.","choices":[{"verdict":"정답","why":"Worm(웜)은 다른 컴퓨터의 취약점을 이용하거나 메일을 통해 스스로 전파되며 자신을 복제·증식하는 악성 프로그램이다."},{"verdict":"오답","why":"Rogue Ware(로그웨어)는 사용자를 속여 가짜 백신 같은 보안 프로그램을 설치하게 하거나 결제를 유도하는 악성 프로그램으로, 스스로 증식·전파하는 것이 특징이 아니다."},{"verdict":"오답","why":"Adware(애드웨어)는 광고를 띄우는 것을 목적으로 하는 소프트웨어로, 스스로 전파·증식하지 않는다."},{"verdict":"오답","why":"Reflection Attack(반사 공격)은 출발지를 피해자로 위조한 요청을 여러 서버에 보내 그 응답이 피해자에게 몰리게 하는 공격 방식으로, 스스로 증식하는 악성코드가 아니다."}],"keywords":[{"term":"웜(Worm)","desc":"스스로 복제·전파하는 독립형 악성 프로그램"},{"term":"바이러스(Virus)","desc":"다른 파일에 기생해 감염시키는 악성 프로그램"},{"term":"트로이 목마(Trojan Horse)","desc":"정상 프로그램으로 위장해 숨어 있는 악성 프로그램, 자기 복제 안 함"},{"term":"애드웨어(Adware)","desc":"광고를 노출하는 소프트웨어"}],"memo":"'스스로 전파, 스스로 증식'이 나오면 웜이다. 기생하면 바이러스, 위장하면 트로이 목마다."}},{"id":"written-2022-2-90","no":90,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 공격기법은?\n<img src=\"data/img/eip_written_20220424_090.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Ping of Death","Session Hijacking","Piggyback Attack","XSS"],"ans":1,"rate":76,"wiki":[{"title":"세션 하이재킹","url":"https://itwiki.kr/w/세션 하이재킹"},{"title":"XSS","url":"https://itwiki.kr/w/XSS"}],"exp":{"concept":"죽음의 핑(Ping of Death)은 ICMP 패킷(핑)을 허용 크기보다 훨씬 크게 만들어 보내는 서비스 거부(DoS) 공격이다. 큰 패킷이 여러 조각으로 나뉘어 전달되고, 대상 시스템이 이를 다시 조립하고 처리하는 과정에서 부하가 걸리거나 네트워크가 마비된다.","choices":[{"verdict":"정답","why":"Ping of Death는 허용 범위 이상의 큰 ICMP 패킷을 전송해 대상 시스템의 네트워크를 마비시키는 서비스 거부 공격이다."},{"verdict":"오답","why":"Session Hijacking(세션 하이재킹)은 정상 사용자의 세션 정보를 가로채 그 사용자로 위장해 접근하는 공격으로, 패킷 크기를 이용하지 않는다."},{"verdict":"오답","why":"Piggyback Attack(피기백 공격)은 인가된 사용자의 정당한 접근에 몰래 편승해 권한 없이 들어가는 공격 방식으로, ICMP 패킷과 관계없다."},{"verdict":"오답","why":"XSS(Cross Site Scripting)는 웹 페이지에 악성 스크립트를 삽입해 방문자의 정보를 빼내거나 악성 동작을 실행하게 하는 공격이다."}],"keywords":[{"term":"Ping of Death","desc":"허용 크기 이상의 ICMP 패킷으로 시스템을 마비시키는 DoS 공격"},{"term":"Smurf","desc":"출발지를 피해자로 위조한 ICMP 요청을 브로드캐스트해 응답을 피해자에게 집중시키는 공격"},{"term":"SYN Flooding","desc":"TCP 연결 요청(SYN)만 대량으로 보내 서버 자원을 고갈시키는 공격"},{"term":"ICMP","desc":"IP 통신의 오류와 제어 메시지를 전달하는 프로토콜, ping이 사용"}],"memo":"'허용 범위 이상의 ICMP 패킷'은 Ping of Death, 'ICMP + 브로드캐스트'는 Smurf다."}},{"id":"written-2022-2-91","no":91,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 소프트웨어는?\n<img src=\"data/img/eip_written_20220424_091.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["전역 함수 라이브러리","소프트웨어 개발 프레임워크","컨테이너 아키텍처","어휘 분석기"],"ans":2,"rate":84,"wiki":[{"title":"소프트웨어 개발 프레임워크","url":"https://itwiki.kr/w/소프트웨어 개발 프레임워크"},{"title":"스프링 프레임워크","url":"https://itwiki.kr/w/스프링 프레임워크"}],"exp":{"concept":"소프트웨어 개발 프레임워크는 애플리케이션의 공통 기반 부분을 클래스 라이브러리 등으로 미리 구현해 둔 반제품 소프트웨어다. 개발자는 이미 만들어진 기반을 확장해 필요한 부분만 채워 넣으면 된다. 자바 진영의 대표적인 예가 스프링(Spring)이다.","choices":[{"verdict":"오답","why":"전역 함수 라이브러리는 어디서나 호출할 수 있는 함수 모음으로, 애플리케이션의 기반 구조를 제공하는 소프트웨어가 아니며 스프링과도 관계없다."},{"verdict":"정답","why":"소프트웨어 개발 프레임워크는 개발할 애플리케이션의 일부분이 클래스 라이브러리로 이미 구현되어 있어 그 기반을 확장해 쓰는 것이며, 자바 기반의 대표 예가 스프링이다."},{"verdict":"오답","why":"컨테이너 아키텍처는 애플리케이션을 실행 환경과 함께 묶어 격리된 컨테이너로 배포·실행하는 구조로, 지문의 설명과 다르다."},{"verdict":"오답","why":"어휘 분석기는 컴파일 과정에서 소스 코드를 토큰 단위로 나누는 프로그램으로, 지문의 설명과 관계없다."}],"keywords":[{"term":"소프트웨어 개발 프레임워크","desc":"공통 기반을 미리 구현해 둔 반제품 소프트웨어"},{"term":"스프링(Spring)","desc":"자바 기반의 대표적인 오픈 소스 애플리케이션 프레임워크"},{"term":"전자정부 표준 프레임워크","desc":"스프링 기반으로 만든 국내 공공 사업용 개발 프레임워크"}],"memo":"'이미 구현된 기반을 확장해서 쓴다', '스프링'이 나오면 프레임워크다."}},{"id":"written-2022-2-92","no":92,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론 중 애자일(Agile) 방법론의 특징과 가장 거리가 먼 것은?","choices":["각 단계의 결과가 완전히 확인된 후 다음 단계 진행","소프트웨어 개발에 참여하는 구성원들 간의 의사소통 중시","환경 변화에 대한 즉시 대응","프로젝트 상황에 따른 주기적 조정"],"ans":1,"rate":84,"wiki":[{"title":"폭포수_모델","url":"https://itwiki.kr/w/폭포수_모델"}],"exp":{"concept":"애자일(Agile) 방법론은 고객과의 소통과 변화 대응을 중시하며, 짧은 주기로 반복하면서 계획을 계속 조정한다. 반면 폭포수 모형은 각 단계를 완전히 끝내고 확인한 뒤에야 다음 단계로 넘어가는 순차적 방식이다.","choices":[{"verdict":"정답","why":"각 단계의 결과가 완전히 확인된 뒤 다음 단계로 진행하는 것은 폭포수 모형의 특징으로, 반복과 변화 대응을 중시하는 애자일과 거리가 멀다."},{"verdict":"오답","why":"개발에 참여하는 구성원들 간의 의사소통을 중시하는 것은 애자일의 특징이다."},{"verdict":"오답","why":"환경 변화에 즉시 대응하는 것은 애자일의 핵심 특징이다."},{"verdict":"오답","why":"프로젝트 상황에 따라 계획과 방식을 주기적으로 조정하는 것은 애자일의 특징이다."}],"keywords":[{"term":"애자일(Agile)","desc":"고객 협력, 짧은 반복, 변화 대응을 중시하는 개발 방법론"},{"term":"폭포수 모형(Waterfall)","desc":"단계를 순차적으로 완료하며 진행하는 전통적 모형"},{"term":"스크럼(Scrum)","desc":"스프린트라는 짧은 주기로 반복 개발하는 애자일 방법론"}],"memo":"'완전히 확인된 후 다음 단계'는 폭포수다. 애자일은 '반복하며 조정'이다."}},{"id":"written-2022-2-93","no":93,"unit":"정보시스템 구축 관리","q":"대칭 암호 알고리즘과 비대칭 암호 알고리즘에 대한 설명으로 틀린 것은?","choices":["대칭 암호 알고리즘은 비교적 실행 속도가 빠르기 때문에 다양한 암호의 핵심 함수로 사용될 수 있다.","대칭 암호 알고리즘은 비밀키 전달을 위한 키 교환이 필요하지 않아 암호화 및 복호화의 속도가 빠르다.","비대칭 암호 알고리즘은 자신만이 보관하는 비밀키를 이용하여 인증, 전자서명 등에 적용이 가능하다.","대표적인 대칭키 암호 알고리즘으로는 AES, IDEA 등이 있다."],"ans":2,"rate":55,"wiki":[{"title":"암호화 알고리즘","url":"https://itwiki.kr/w/암호화 알고리즘"}],"exp":{"concept":"대칭 암호는 암호화와 복호화에 같은 키(비밀키)를 쓰므로 빠르지만, 상대방과 그 키를 안전하게 나눠 가지는 키 교환 문제가 있다. 비대칭 암호(공개키 암호)는 공개키와 개인키 두 개를 쓰므로 키 교환 부담은 적지만 느리다. 개인키로 서명하면 본인만 만들 수 있으므로 전자서명에 쓰인다.","choices":[{"verdict":"오답","why":"대칭 암호 알고리즘은 실행 속도가 비교적 빨라 다양한 암호 시스템의 핵심 함수로 사용될 수 있으므로 옳다."},{"verdict":"정답","why":"대칭 암호는 송신자와 수신자가 같은 비밀키를 가져야 하므로 비밀키를 전달하기 위한 키 교환이 반드시 필요하다. 키 교환이 필요 없다는 설명은 틀렸다."},{"verdict":"오답","why":"비대칭 암호는 자신만 보관하는 개인키(비밀키)로 서명할 수 있어 인증, 전자서명 등에 쓸 수 있으므로 옳다."},{"verdict":"오답","why":"AES와 IDEA는 대표적인 대칭키 암호 알고리즘이므로 옳다."}],"keywords":[{"term":"대칭키 암호","desc":"암·복호화 키가 같음, 빠름, 키 교환 필요 (DES, AES, IDEA, SEED, ARIA)"},{"term":"비대칭키 암호","desc":"공개키와 개인키 사용, 느림, 키 관리 쉬움 (RSA, ECC, 디피-헬만)"},{"term":"전자서명","desc":"개인키로 서명하고 공개키로 검증"}],"memo":"대칭키의 약점이 '키 교환(배송) 문제'이고, 이를 해결하려고 나온 것이 공개키 암호다."}},{"id":"written-2022-2-94","no":94,"unit":"정보시스템 구축 관리","q":"두 명의 개발자가 5개월에 걸쳐 10000 라인의 코드를 개발하였을 때, 월별(man-month) 생산성 측정을 위한 계산 방식으로 가장 적합한 것은?","choices":["10000／2","10000／(5×2)","10000／5","(2×10000)／5"],"ans":2,"rate":87,"wiki":[{"title":"LOC","url":"https://itwiki.kr/w/LOC"}],"exp":{"concept":"생산성은 일정 노력 동안 얼마나 많은 결과물을 만들었는지를 뜻한다. 소프트웨어에서는 개발한 코드 라인 수(LOC)를 투입한 노력(man-month, 인원 × 개월)으로 나누어 구한다. 1 man-month는 한 사람이 한 달 동안 하는 일의 양이다.","choices":[{"verdict":"오답","why":"10000 / 2는 개발 기간을 빼고 인원만으로 나눈 값이라 man-month 단위 생산성이 아니다."},{"verdict":"정답","why":"투입 노력은 2명 × 5개월 = 10 man-month이므로 생산성 = 10000 / (5 × 2) = 1,000 LOC/man-month다."},{"verdict":"오답","why":"10000 / 5는 인원을 빼고 기간만으로 나눈 값이라 man-month 단위 생산성이 아니다."},{"verdict":"오답","why":"(2 × 10000) / 5는 인원을 곱하고 있어 식의 구조가 틀렸다. 인원은 분모에 들어가야 한다."}],"keywords":[{"term":"man-month(MM)","desc":"한 사람이 한 달 동안 하는 작업량, 인원 × 개월"},{"term":"생산성","desc":"LOC / man-month"},{"term":"LOC 기법","desc":"원시 코드 라인 수의 낙관치·중간치·비관치로 비용을 추정하는 기법"}],"memo":"생산성 = 만든 양 / (사람 × 기간). 사람과 기간 둘 다 분모다."}},{"id":"written-2022-2-95","no":95,"unit":"정보시스템 구축 관리","q":"접근 통제 방법 중 조직 내에서 직무, 직책 등 개인의 역할에 따라 결정하여 부여하는 접근 정책은?","choices":["RBAC","DAC","MAC","QAC"],"ans":1,"rate":60,"wiki":[{"title":"RBAC","url":"https://itwiki.kr/w/RBAC"},{"title":"접근통제 정책","url":"https://itwiki.kr/w/접근통제 정책"}],"exp":{"concept":"접근 통제는 누가 어떤 자원에 접근할 수 있는지 정하는 방법이다. 역할 기반 접근 통제(RBAC)는 사람 개개인이 아니라 '팀장', '인사 담당자'처럼 조직 안의 역할에 권한을 주고, 사용자는 맡은 역할에 따라 권한을 얻는다.","choices":[{"verdict":"정답","why":"RBAC(Role Based Access Control)는 직무, 직책 등 조직 내 개인의 역할에 따라 접근 권한을 부여하는 접근 통제 정책이다."},{"verdict":"오답","why":"DAC(Discretionary Access Control, 임의 접근 통제)는 데이터 소유자가 사용자의 신원에 따라 접근 권한을 임의로 부여하는 방식이다."},{"verdict":"오답","why":"MAC(Mandatory Access Control, 강제 접근 통제)는 주체와 객체의 보안 등급을 비교해 시스템이 강제로 접근을 통제하는 방식이다."},{"verdict":"오답","why":"QAC는 출제 범위의 표준 접근 통제 정책이 아니다."}],"keywords":[{"term":"RBAC","desc":"역할(Role)에 따라 권한을 부여하는 접근 통제"},{"term":"DAC","desc":"소유자가 신원에 따라 임의로 권한을 부여하는 접근 통제"},{"term":"MAC","desc":"보안 등급(비밀 등급)에 따라 시스템이 강제로 통제"}],"memo":"Role이면 RBAC, 주인 마음대로(Discretionary)면 DAC, 강제(Mandatory) 등급이면 MAC이다."}},{"id":"written-2022-2-96","no":96,"unit":"정보시스템 구축 관리","q":"COCOMO(Constructive Cost Model) 모형의 특징이 아닌 것은?","choices":["프로젝트를 완성하는데 필요한 man-month로 산정 결과를 나타낼 수 있다.","보헴(Boehm)이 제안한 것으로 원시코드 라인 수에 의한 비용 산정 기법이다.","비교적 작은 규모의 프로젝트 기록을 통계 분석하여 얻은 결과를 반영한 모델이며 중소 규모 소프트웨어 프로\n젝트 비용 추정에 적합하다.","프로젝트 개발유형에 따라 object, dynamic, function의 3가지 모드로 구분한다."],"ans":4,"rate":61,"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"exp":{"concept":"COCOMO(Constructive Cost Model)는 보헴(Boehm)이 제안한 비용 산정 모형으로, 원시 코드 라인 수(LOC)를 바탕으로 필요한 노력(man-month)을 계산한다. 개발 유형은 프로젝트 규모와 복잡도에 따라 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)의 세 가지로 나눈다.","choices":[{"verdict":"오답","why":"COCOMO는 프로젝트를 완성하는 데 필요한 노력을 man-month로 산정해 나타낼 수 있으므로 옳다."},{"verdict":"오답","why":"COCOMO는 보헴이 제안한 원시 코드 라인 수 기반의 비용 산정 기법이므로 옳다."},{"verdict":"오답","why":"COCOMO는 비교적 작은 규모의 프로젝트 기록을 통계 분석한 결과를 반영한 모델로, 중소 규모 소프트웨어 프로젝트 비용 추정에 적합하다고 설명되므로 옳다."},{"verdict":"정답","why":"COCOMO의 개발 유형은 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded) 세 가지다. object, dynamic, function은 COCOMO의 모드가 아니다."}],"keywords":[{"term":"조직형(Organic)","desc":"기관 내부의 5만 라인(50KDSI) 이하 중소 규모 소프트웨어"},{"term":"반분리형(Semi-Detached)","desc":"30만 라인(300KDSI) 이하의 트랜잭션 처리 시스템, 운영체제 등"},{"term":"내장형(Embedded)","desc":"30만 라인(300KDSI) 이상의 최대형 규모, 신호기 제어 시스템 등"},{"term":"COCOMO 모형 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"COCOMO 개발 유형은 '조반내'(조직형, 반분리형, 내장형)다. object, dynamic, function은 객체지향 분석의 객체·동적·기능 모델링 용어로 혼동을 노린 보기다."}},{"id":"written-2022-2-97","no":97,"unit":"정보시스템 구축 관리","q":"각 사용자 인증의 유형에 대한 설명으로 가장 적절하지 않은 것은?","choices":["지식 : 주체는 '그가 알고 있는 것'을 보여주며 예시로는 패스워드, PIN 등이 있다.","소유 : 주체는 '그가 가지고 있는 것'을 보여주며 예시로는 토큰, 스마트카드 등이 있다.","존재 : 주체는 '그를 대체하는 것'을 보여주며 예시로는 패턴, QR 등이 있다.","행위 : 주체는 '그가 하는 것'을 보여주며 예시로는 서명, 움직임, 음성 등이 있다."],"ans":3,"rate":82,"wiki":[{"title":"인증","url":"https://itwiki.kr/w/인증"}],"exp":{"concept":"사용자 인증 유형은 무엇으로 본인을 증명하느냐에 따라 나뉜다. 지식 기반은 알고 있는 것(비밀번호), 소유 기반은 가지고 있는 것(스마트카드, 토큰), 존재(생체) 기반은 자신의 몸 자체(지문, 홍채, 얼굴), 행위 기반은 자신이 하는 행동(서명, 걸음걸이, 음성)이다.","choices":[{"verdict":"오답","why":"지식 기반 인증은 '그가 알고 있는 것'으로, 패스워드나 PIN이 예시이므로 옳다."},{"verdict":"오답","why":"소유 기반 인증은 '그가 가지고 있는 것'으로, 토큰이나 스마트카드가 예시이므로 옳다."},{"verdict":"정답","why":"존재(생체) 기반 인증은 '그가 무엇인가(그 자체)'를 보여 주는 것으로, 지문, 홍채, 얼굴 같은 생체 정보가 예시다. '그를 대체하는 것'이라는 설명과 패턴, QR이라는 예시는 모두 틀렸다."},{"verdict":"오답","why":"행위 기반 인증은 '그가 하는 것'으로, 서명, 움직임, 음성 등이 예시이므로 옳다."}],"keywords":[{"term":"지식 기반(Something You Know)","desc":"패스워드, PIN"},{"term":"소유 기반(Something You Have)","desc":"토큰, 스마트카드, OTP"},{"term":"존재 기반(Something You Are)","desc":"지문, 홍채, 얼굴 등 생체 정보"},{"term":"행위 기반(Something You Do)","desc":"서명, 동작, 음성"}],"memo":"존재는 '나 자신(몸)'이다. 대체물이나 패턴, QR은 존재 기반이 아니다."}},{"id":"written-2022-2-98","no":98,"unit":"정보시스템 구축 관리","q":"시스템의 사용자가 로그인하여 명령을 내리는 과정에 대한 시스템의 동작 중 다음 설명에 해당하는 것은?\n<img src=\"data/img/eip_written_20220424_098.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Aging","Accounting","Authorization","Authentication"],"ans":4,"rate":63,"wiki":[{"title":"인증","url":"https://itwiki.kr/w/인증"}],"exp":{"concept":"시스템에 로그인해 명령을 내리는 과정은 인증 → 인가 → 계정 관리(AAA) 순서로 이루어진다. 인증(Authentication)은 '당신이 누구인지' 확인하는 단계로, 아이디와 패스워드를 입력하는 것이 대표적이다. 인가는 인증된 사용자가 무엇을 할 수 있는지 권한을 주는 단계다.","choices":[{"verdict":"오답","why":"Aging(에이징)은 운영체제 스케줄링에서 오래 기다린 프로세스의 우선순위를 높여 주는 기법으로, 신원 증명과 관계없다."},{"verdict":"오답","why":"Accounting(계정 관리)은 사용자가 시스템 자원을 어떻게 사용했는지 기록하고 추적하는 단계다."},{"verdict":"오답","why":"Authorization(인가)은 인증된 사용자에게 어떤 자원에 어떤 권한으로 접근할 수 있는지 허가하는 단계다."},{"verdict":"정답","why":"Authentication(인증)은 자신의 신원(Identity)을 시스템에 증명하는 과정으로, 아이디와 패스워드를 입력하는 것이 가장 일반적인 예다."}],"keywords":[{"term":"Authentication(인증)","desc":"사용자의 신원 확인"},{"term":"Authorization(인가)","desc":"인증된 사용자에게 권한 부여"},{"term":"Accounting(계정 관리)","desc":"자원 사용 내역 기록·추적"},{"term":"AAA","desc":"인증, 인가, 계정 관리를 수행하는 보안 구조"}],"memo":"'누구냐' = 인증(Authentication), '무엇을 해도 되냐' = 인가(Authorization), '무엇을 했냐' = 계정 관리(Accounting)."}},{"id":"written-2022-2-99","no":99,"unit":"정보시스템 구축 관리","q":"다음에서 설명하는 IT 기술은?\n<img src=\"data/img/eip_written_20220424_099.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SDN(Software Defined Networking)","NFS(Network File System)","Network Mapper","AOE Network"],"ans":1,"rate":64,"wiki":[{"title":"SDN","url":"https://itwiki.kr/w/SDN"},{"title":"NFS","url":"https://itwiki.kr/w/NFS"}],"exp":{"concept":"SDN(Software Defined Networking)은 네트워크 장비에서 '어디로 보낼지 정하는 두뇌(제어부)'와 '실제로 데이터를 전달하는 몸통(데이터 전달부)'을 분리하고, 두뇌 역할을 소프트웨어로 중앙에서 관리하는 기술이다. 장비를 하나하나 바꾸지 않고 소프트웨어로 네트워크 경로와 정책을 바꿀 수 있다.","choices":[{"verdict":"정답","why":"SDN은 네트워크를 제어부와 데이터 전달부로 분리하고 소프트웨어로 네트워크를 제어·관리해, 기존 네트워크에 영향을 주지 않고 경로를 수정할 수 있게 하는 기술이다."},{"verdict":"오답","why":"NFS(Network File System)는 네트워크로 연결된 다른 컴퓨터의 파일 시스템을 자신의 파일처럼 사용할 수 있게 하는 분산 파일 시스템이다."},{"verdict":"오답","why":"Network Mapper(Nmap)는 네트워크의 호스트와 열린 포트, 서비스를 탐색하는 스캐닝 도구다."},{"verdict":"오답","why":"AOE(Activity On Edge) Network는 간선이 작업을, 정점이 작업의 시작·완료 시점을 나타내는 방향 그래프로, 프로젝트 일정 분석에 쓰인다."}],"keywords":[{"term":"SDN","desc":"제어부와 데이터 전달부를 분리하고 소프트웨어로 네트워크를 제어"},{"term":"NFV(Network Functions Virtualization)","desc":"방화벽, 라우터 같은 네트워크 기능을 범용 서버의 소프트웨어로 가상화"},{"term":"NFS","desc":"원격 파일 시스템을 로컬처럼 사용하는 분산 파일 시스템"}],"memo":"'제어부와 데이터 전달부 분리', '소프트웨어로 제어'가 나오면 SDN이다."}},{"id":"written-2022-2-100","no":100,"unit":"정보시스템 구축 관리","q":"프로젝트 일정 관리 시 사용하는 PERT 차트에 대한 설명에 해당하는 것은?","choices":["각 작업들이 언제 시작하고 언제 종료되는지에 대한 일정을 막대 도표를 이용하여 표시한다.","시간선(Time-line) 차트라고도 한다.","수평 막대의 길이는 각 작업의 기간을 나타낸다.","작업들 간의 상호 관련성, 결정경로, 경계시간, 자원할당 등을 제시한다. "],"ans":4,"rate":55,"wiki":[{"title":"PERT/CPM","url":"https://itwiki.kr/w/PERT/CPM"}],"exp":{"concept":"PERT(Program Evaluation and Review Technique) 차트는 작업들을 노드와 화살표로 연결한 네트워크 형태로 그려, 작업 사이의 선후 관계와 가장 오래 걸리는 경로(임계 경로)를 보여 주는 일정 관리 도구다. 반면 간트 차트(Gantt Chart)는 작업별 시작·종료 시점을 가로 막대로 그린 도표다.","choices":[{"verdict":"오답","why":"각 작업의 시작과 종료 일정을 막대 도표로 표시하는 것은 간트 차트에 대한 설명이다."},{"verdict":"오답","why":"시간선(Time-line) 차트라고도 부르는 것은 간트 차트다."},{"verdict":"오답","why":"수평 막대의 길이로 각 작업의 기간을 나타내는 것은 간트 차트의 특징이다."},{"verdict":"정답","why":"PERT 차트는 작업들 간의 상호 관련성, 결정 경로(임계 경로), 경계 시간, 자원 할당 등을 제시하는 네트워크 형태의 일정 관리 도구다."}],"keywords":[{"term":"PERT","desc":"작업 간 관계와 임계 경로를 보여 주는 네트워크 차트, 낙관치·중간치(최빈치)·비관치의 세 가지 추정 시간 사용"},{"term":"CPM(Critical Path Method)","desc":"작업의 선후 관계로 임계 경로를 찾아 일정을 관리하는 기법"},{"term":"간트 차트(Gantt Chart)","desc":"작업 일정을 수평 막대로 나타낸 시간선 차트"}],"memo":"'막대', '시간선'은 간트 차트, '상호 관련성', '결정 경로'는 PERT다."}}]};